window.__D("text/likkutei-sichot/c098",{"p":[[1300151221,"בער קומט אויס אז דורך דעם וואס דער אויבערשטער האט אים (יצחק׳ן) געהייסן זיך מקריב זיין אלס עולה תמימה, איז בדרך ממילא ארץ ישראל נקבע געווארן אלס מקומו⁶⁴ ומחיצתו (בדוגמא ווי דורך הקרבת העולה ווערט די עזרה איר מקום ומחיצה קבועה⁶⁵),\nוממילא איז חו״ל לגבי אים „חוץ למחיצתו“.\nמשא״כ לדעת רש״י, כנ״ל, אז אין חפצא פון א״י האט די נתינה ביים ברית בין הבתרים ניט אויפגעטאן.\nרש״י האט דאך אבער שוין מפרש געווען אין פ׳ חיי שרה⁶⁶ (אין דעם ענטפער פון אברהם צו אליעזר „השמר לך פן תשיב את בני שמה“) אויף די ווערטער „ה׳ אלקי השמים אשר לקחני מבית אבי — עכשיו הוא אלקי השמים ואלקי הארץ שהרגלתיו בפי הבריות אבל כשלקחני מבית אבי ה׳ אלקי השמים ולא אלקי הארץ שלא היו באי עולם מכירים בו ושמו לא הי׳ רגיל בארץ“,\nוואס (ווי גערעדט אמאל בארוכה⁶⁷) דערמיט האט אברהם מסביר געווען צו אליעזר׳ן, אז אין חו״ל, „בית אבי“, איז דער אויבערשטער בלויז „אלקי השמים“, ניט „אלקי הארץ“ — היות מ׳האט דארט ניט קיין הכרה אין דעם אויבערשטן און שמו הקדוש איז ניט מורגל בפי הבריות — און דעריבער „את בני לא תשב שמה“; משא״כ אין א״י איז ער (ניט נאר) „אלקי השמים (נאר אויך) ואלקי הארץ שהרגלתיו בפי הבריות“⁶⁸, אבער לאידך איז עס דארטן",[["64","64","להעיר גם ממשנ״ת (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181408\" data-slug=\"likkutei-sichot\" data-id=\"1300181408\">לקו״ש חי״ח ע׳ 399</a> ואילך) בדעת הרמב״ם (הל׳ מלכים ספ״ה) שבאיסור יציאה מהארץ י״ל שיש גם (מלבד מצד ענין הקדושה) הענין דבחירת הקב״ה שבחר בא״י ונתנה לישראל שזהו מקומם בזמן של גאולה, עיי״ש בארוכה."],["65","65","ולהעיר דבנוגע לק״ק מצינו גם דדרשינן פסול יוצא מ„הן לא הובא את דמה אל הקודש פנימה“, או מ„בקדש“ (ראה רש״י ד״ה שמא תודה״ה בקדש — פסחים פב, סע״א. רש״י ד״ה בשדה תודה״ה כיון — זבחים שם. רש״י זבחים כו, א ד״ה פרכסה. ועוד), „לפני ה׳“ (מנחות מח, רע״א ברש״י ותוס׳ שם). ולפי דרשות אלו שקאי רק בק״ק משמע קצת (א) שהוא מצד קדושתם, (ב) נוגע החיוב, שיהיו בפנים בקודש, ופסול יוצא הוא לפי שאינם „פנימה“ (או „בקדש“, „לפני ה׳“). משא״כ להדרשה „ובשר בשדה טרפה“, „כיון שיצא בשר חוץ למחיצתו“, (א) הוא דין כללי, (ב) משמעו שהפסול הוא מצד היציאה. אלא שגם בזה י״ל בב׳ אופנים, אם הפסול הוא מצד עצם היציאה, או מכיון שהוא נמצא בחוץ, וכלשון הרמב״ם הל׳ מאכ״א שם „כיון שיצא למקום שהוא לו כשדה“ [וראה צפע״נ למכות יח, א בתודה״ה איסורא. ובארוכה הל׳ איסורי ביאה פ״ה ה״ב דיש דברים הצריכים פנים ויש דברים שפסולים בחוץ, ע״ש. ומתרץ עפ״ז שינוי הלשונות ברמב״ם הל׳ מעה״ק שם ה״ה והי״ו *]. ואולי זהו החילוק בין ק״ק לשאר פסולי יוצא, ולכן הביא הרמב״ם לשון הנ״ל דוקא בהל׳ מאכ״א (אבל להעיר שכ״כ גם לענין ק״ק בפיה״מ זבחים ספ״ח. ועד״ז הוא ברש״י מכות שם). ובכל אופן בב״ר מדייק „חוץ לקלעים“ ** (ולא *) וראה בארוכה צפע״נ השלמה יט, א ואילך. **) לכאורה הי׳ אפ״ל שזהו החילוק בין פרש״י להמדרש, דבמדרש „כיון שיצאת חוץ לארץ“, הפסול הוא מצד היציאה, ולרש״י „אין חו״ל כדאי לך“ הפסול הוא מצד שנמצא בחוץ — אבל כבר נתחבר חוץ לעזרה — כבראם) שמדגיש יותר שהוא מצד גדר (מקום ו)מחיצות (ראה צפע״נ שם). ואכ״מ."],["66","66","כד, ז."],["67","67","לעיל ע׳ 159."],["68","68","ועפ״ז י״ל דהמבואר בפדר״א פל״ט בנוגע ליעקב „והי׳ מהרהר בלבו ואמר איך אעזוב ארץ אבותי ואת ארץ מולדתי ואת ארץ ששכינתו של הקב״ה בתוכה“ — אינו סתירה להמבואר בפנים, כי לא הי׳ קביעות הקדושה (גם דקדושת שכינה) בגוף הארץ (נוסף על המבואר לעיל הערה 46), כמובן שלפרש״י אין בזה הענין דפסול כו׳, לא רק מצד ענין הקדושה, אלא גם מחמת מקומו ומחיצתו."]]],[1300151222,"נאר איז אן אופן פון „הרגלתיו בפי הבריות“ — ניט קיין שינוי המהות אין די בריות, אין זייערע הנהגות און מעשים (וואס דעריבער „לא תקח אשה לבני מבנות הכנעני אשר אנכי יושב בקרבו“) —\nאיז דערפון פארשטאנדיק אז בערך מעלתו פון יצחק וואס איז געווען אן „עולה תמימה“ [איז כאטש ס׳איז ניט (אזויפיל) נוגע חשיבות הארץ — ווארום אין ארץ עצמה איז (נאך) ניט געווען קיין מעלה מיוחדת⁶⁹ און אויך ניט אין מהות פון אנשי הארץ —] איז (בעיקר) געווען שלילת היציאה דערפאר וואס „אין חוצה לארץ כדאי לך“, ווייל דארט איז ניטא „אלקי הארץ“, אפילו שמו איז ניט רגיל אין חוץ לארץ.\nז. ויש לבאר דעם חילוק צווישן די צוויי דיעות בפנימיות הענינים:\nלויט דעם מדרש (והלכה) איז געווען די בעלות פון אידן אויף א״י אויך בזמן האבות און מצד דעם האט יצחק ניט געטארט ארויסגיין (זייענדיק אן עולה תמימה); לויט פירוש רש״י איז ניט געווען קיין בעלות בפועל, דאס האט זיך ערשט אויפגעטאן ע״י בנ״י בכניסתם לארץ, און דער העדר היציאה מהארץ איז בלויז ווייל „אין חוצה לארץ כדאי לך“:\nמצד מדרש, וואס איז העכער פון פשט (— כולל פשטות הענינים) נאר פארבונדן מער מיט רוחניות הענינים (אבער דאס איז נוגע ופועל אויך אין גשמיות העולם), ווערט די בעלות פון אידן אויף א״י אויפגעטאן דורך „מאמרו של הקב״ה מעשה“ שנוגע צו די בעלות פון אידן אויף א״י,\nלויט פרש״י — פשוטו של מקרא — רעכנט מען זיך בלויז (ווי דאס איז אין עולם הפשט — עולם המעשה) מיט דער מעשה בפועל, ווי דאס איז אין עוה״ז,",[["","","מהמשך שם „ואלך אל ארץ בני חם בארץ שאין יראת שמים ביניהם“, שהוא הניגוד ל„שכינתו של הקב״ה כו׳“ (כמ״ש ברד״ל שם) — היינו שבא״י לאחר שאברהם ויצחק ויעקב פרסמו שמו של הקב״ה (ראה רמב״ם ריש הל׳ ע״ז) הי׳ שם (עכ״פ בסביבתם) יראת שמים (עכ״פ — בערך לארץ בני חם). ולהעיר שגם באיסור יציאה מא״י לאחרי הכבוש, י״ל שהוא מצד יראת חטא — ראה מאירי לכתובות (קיא, א) שמפרש מ״ש בגמ׳ שם „כשם שאסור לצאת מא״י לבבל כו׳“, „שכל מקום שחכמה ויראת חטא מצוין שם דינו כארץ ישראל“, וכן צריך לפרש לפי פרש״י שם ד״ה כך. ראה לח״מ לרמב״ם הל׳ מלכים ספ״ה. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181408\" data-slug=\"likkutei-sichot\" data-id=\"1300181408\">לקו״ש שם (ע׳ 399</a> ואילך). אבל להעיר — שיצחק ישב בגרר מקום אשר אברהם אמר עליו (וירא כ, יא) „רק אין יראת אלקים במקום הזה והרגוני גו׳“. ודוחק לומר שע״י שהייתו של אברהם שם דינו נשתנה. ובפרט שמפורש שגם יצחק ירא לומר אשתי „פן יהרגוני אנשי המקום“ (פרשתנו כו, ז). ולהעיר מפרש״י וירא כ, טו. וראה לעיל הערה 26."],["69","69","ואולי י״ל דגם מ״ש הרמב״ן (פרשתנו כו, ה) דהאבות שמרו המצות „בארץ בלבד ויעקב בחוצה לארץ בלבד נשא שתי אחיות וכן עמרם כי המצות משפט אלקי הארץ“, וכמו שביאר בארוכה בפ׳ אחרי (יח, כה) „שהיא נחלת ה׳ מיוחדת לשמו לא נתן עלי׳ מן המלאכים כו׳“, ולכן עיקר קיום המצות הוא בארץ“, „וזו היא מצות יעקב אבינו כו׳ בעת ביאתם לארץ הסירו את אלקי הנכר“ — אין כוונתו שבזמן האבות כבר נקבע זה בהארץ, כ״א שזהו טעם בכלל לזה שנצטוו במצות (במ״ת) — „עיקר כל המצות ליושבים בארץ“, ואצל האבות הי׳ מעין זה, מחמת ה„גברא“, כיון שבו פרסם אברהם (והאבות אחריו) שמו של הקב״ה, ובו נראה ה׳ אליהם ובנו שם מזבחות (לך יב, ז־ח. תולדות כו, כה. וישלח לג, כ. ועוד). ובנוגע ליעקב בפרט הרי הי׳ ארץ אבותיו, המקום שבו נולד, שם קיבל תורתו אצל שם ועבר (ראה מאירי הובא בהערה שלפנ״ז), ושם נתברך מאביו — לכן הי׳ א״י אצלו בדוגמת א״י לאחרי שנתקדשה בכניסתם לארץ. וצ״ע. וראה לעיל הערה 68."]]],[1300151223,"און דעריבער איז אויך די בעלות פון אידן אויף א״י געווארן דוקא דורך זייער כניסה וכיבוש במעשה.\nאבער לאידך, ווערט דורך דער מעשה בפועל פון אידן איבערגעאנדערשט דער מהות הארץ און עס\nווערט נתגלה נתינת הקב״ה פון עצם מהות הארץ, באופן אז עס איז געווארן אן ארץ ישראל, און אן ארץ הקודש און אין אן אופן תמידי, כנ״ל.\n(משיחות כ״ף מנ״א ומוצש״ק ראה תשל״ח)"],[1300151224,"<h3>תולדות ג</h3>\nא. אויפן פסוק1 „ויהי כי זקן יצחק ותכהין עיניו מראות” זאגט רש״י דריי פירושים וואס ס׳איז געווען די סיבה וואס האט געבראכט צו „ותכהין”: בעשנן של אלו (שהיו מעשנות ומקטירות לע״ז<sup data-n=\"2\">2</sup>. ד״א כשנעקד ע״ג המזבח והי׳ אביו רוצה לשחטו באותה שעה נפתחו השמים וראו מלאכי השרת והיו בוכים וירדו דמעותיהם ונפלו על עיניו לפיכך כהו עיניו. ד״א כדי שיטול יעקב את הברכות.\nאיז אין דעם ניט פארשטאנדיק:\nא) אין פשטות קומט אויס, אז דער פסוק גופא גיט דעם טעם — אין די ווערטער וואס ער זאגט פריער: „ויהי כי זקן יצחק” און אלס תוצאה דערפון — „ותכהין עיניו מראות”3 [ע״ד ווי עס שטייט4 ביי יעקב אבינו: „ועיני ישראל כבדו מזוקן”], און ווי מען זעט במוחש, אז אויף דער עלטער ווערט אפגע־שוואכט דער כח הראי׳. וויבאלד דער פסוק אליין זאגט די סיבה פון „ותכהין”, צוליב וואס דארף רש״י זוכן אנדערע טעמים5?\nב) אומעטום וואו רש״י ברענגט צוויי אדער מער פירושים, איז עס אלעמאל צוליב דעם וואס יעדער פון זיי האט אין זיך עפעס א שוועריקייט וואס איז ניטא אין דעם צווייטן פירוש. אויך דער סדר הפירושים איז בדיוק: די שוועריקייט פון צווייטן פירוש איז גרעסער ווי פון ערשטן פירוש, און אזוי איז דער דריטער פירוש — לגבי דעם צווייטן פירוש.\nדארף מען פארשטיין: וועלכע שוועריקייטן זיינען פאראן אין די דריי פירושים פון אונזער פרש״י; און מיט וואס איז דער צווייטער פירוש מער קשה פון ערשטן און דער דריטער פון די פריערדיקע צוויי?\nג) ווי גערעדט כמה פעמים, אז דארט וואו רש״י שרייבט דריי פירושים, איז (אויסער דער באזונדערער קשיא אין יעדן איינצלנעם פירוש וואס ווערט אראפגענומען דורך די צוויי אנדערע פירושים, איז) פאראן אויך א שווערי־קייט אין יעדע צוויי (פון די דריי) פירושים צוזאמען, צוליב וועלכער ס׳איז נויטיק דער דריטער פירוש, וואס לויט אים איז ניטא אט די קשיא6 (ווארום אויב מ׳וועט זאגן אז אויך דורך צוויי פירושים גייען אראפ אלע קשיות, וואלט דאך רש״י ניט דארפן אנקומען צו א דריטן פירוש).\nדארף מען אין פירוש רש״י שלפנינו געפינען אויך די קשיא משותפת פון",[["1","1","פרשתנו כז, א."],["2","2","בראם כאן מפרש שכהו עיניו מצד שהי׳ מיצר לו על עשן הע״ז (וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051151\" data-slug=\"likkutei-sichot\" data-id=\"1300051151\">לקו״ש ח״ה ע׳ 139</a> ואילך). ובתנחומא כאן (ח): אמר הקב״ה הריני מכהה את עיניו כו׳. אבל מפשטות לשון רש״י „בעשנן כו׳” מוכח, שכיהוי עיניו בא מהעשן עצמו (דטבע העשן להזיק לעינים — משלי יו״ד, כו), וכבשפ״ח כאן."],["3","3","וכן פירש הרשב״ם, רד״ק ורבינו בחיי כאן."],["4","4","ויחי מח, י."],["5","5","אבל אין להקשות דלפי פרש״י למה נאמר בכתוב „ויהי כי זקן יצחק” (וראה משכיל לדוד כאן)* — כי י״ל, שזוהי הקדמה (לא ל„ותכהין”, כ״א) לכללות הסיפור שרצה יצחק לברך את עשו, שזה שייך רק כאשר „זקן יצחק גו׳ לא ידעתי יום מותי”."],["6","6","אף שלפעמים המעלה היא לא מצד קושיא שישנה, כ״א, לפי שהוא קרוב יותר לפשוטו ש״מ. *) עיקר הקושיא הוא לפי פי׳ הראשון „בעשנן של אלו”, משא״כ לפי הב׳ והג׳ — ראה לקמן בפנים סעיף ו׳ והערה 26."]]],[1300151225,"יעדע צוויי פירושים צוזאמען, און ווי אזוי זי ווערט פארענטפערט דורכן דריטן פירוש.\nב. דער טעם וואס רש״י וויל ניט לערנען (ווי מ׳קען אננעמען בפשטות) אז „ותכהין” איז געשען דערפאר ווייל „זקן יצחק”: אין דער פריערדיקער סדרה7 שטייט „ויברך אלקים את יצחק”, טייטשט דארט רש״י: נתיירא (אברהם) לברך את יצחק כו׳ אמר יבא בעל הברכות ויברך כו׳ ובא הקב״ה וברכו.\nשטעלט זיך די קשיא8: ווי קומט עס וואס נאך דעם דער אויבערשטער אליין האט געבענטשט יצחק אבינו, זאל ער שפעטער זיין אינעם מצב פון „ותכהין עיניו”, וואס פארשאפט דעם מענטשן צער און יסורים, ביז — ווי רש״י שרייבט ווייטער9 — אז מצד דעם איז ער געווען „כמת”? ס׳איז דאך א דבר הפשוט, אז וויבאלד דער אויבער־שטער אליין, דער בעל הברכות, האט געבענטשט יצחק׳ן, האט די זקנה אים ניט געדארפט אזוי שאטן (ובפרט אז אין יענע יארן איז 123 יאר10 ניט געווען אזא טיפער עלטער), אז ער זאל גאנצע 57 יאר זיין „כמת”11!\n(ובפרט אז מען געפינט עס ניט בא קיינעם ניט11* פון די אלע מענשען וואס",[["7","7","כה, יא."],["8","8","ראה עד״ז לקמן ע׳ 217 — בביאור פרש״י בפסוק שלאח״ז („לא ידעתי יום מותי, אריב״ק כו׳”)."],["9","9","ויצא כח, יג. לא, מב. דרך אגב — גם בפרש״י זה נראה גודל דיוק הלשון שלו: המקור לפרש״י הוא בתנחומא פרשתנו (ו), אלא ששם הלשון „הואיל ונתייסם בעיניו כו׳” [וכן בפדר״א פל״ב: מכאן אתה למד שהסומא חשוב כמת], ואילו ברש״י הלשון: „שכהו עיניו .. והרי הוא כמת”. והביאור בזה [נוסף לזה שבקרא מצינו רק הענין ד„כהו עיניו” ולא שנתייסם**]: אא״פ לומר שיצחק הי׳ סומא, כי הי׳ „עולה תמימה”*** (פרש״י פרשתנו כו, ב. מב״ר פס״ד, ג), וסומא הוי מום (אמור כא, יח. כב, כב). [ואין מזה סתירה לזה שפרש״י עה״פ (ש״ב ה, ו) „העורים והפסחים” — „היו להם שני צלמים (עבודת כוכבים) א׳ עור וא׳ פסח שנעשו על שם יצחק ויעקב כו׳” — כי י״ל שזהו רק לדעת היבוסים שלא הבחינו דרגת „ותכהין” דיצחק (ופשוט שלא ידעו שהי׳ „עולה תמימה”). והרי גם יעקב חשבוהו ל„פסח” (שפירושו „דולג” — פרש״י בא יב, יא), אף שהי׳ רק „צולע” (וישלח לב, לב). ועוד ועיקר שהרי לאח״ז ויבא יעקב שלם בגופו (פרש״י וישלח לג, יח) — שהי׳ צולע משך זמן קצר ביותר במשך כל ימי חייו. ובפשטות י״ל שאא״פ לעשות צלם של (רק) כיהוי עינים]. ועפ״ז חידוש בהלכה (ע״ד הפשט) — דכיהוי עינים לא הוי מום****."],["10","10","שנותיו של יצחק אז (פרש״י פרשתנו כז, ב)."],["11","11","משא״כ ביעקב יש לומר, אשר: (א) כבידות עיניו באה מצד זה ש„מעט ורעים היו ימי שני חיי גו׳” (ויגש מז, ט). (ב) „כבדו” קל יותר מ„ותכהין” (ראה זהר פרשתנו קמב, א. ספורנו כאן). (ג) גם זה — הי׳ רק בסוף ימיו (וראה באר יצחק לפרש״י כאן). 11*) ואע״פ שפרש״י (בראשית ד, כג) שהי׳ למך סומא: א) הרי מסיים שם „כך דרש ר׳ תנחומא” (דקאי על כל הפירוש), ב) אינו מפורש בכתוב, ג) מביא גם פירוש אחר. *) גם בנדרים (סד, ב) דסומא חשוב כמת — אבל שם אין המדובר ביצחק. **) בבכורות מד, א: כל מחמת כהיותא כו׳, וברש״י שם: כהיותא, דאינו רואה (ובשטמ״ק מוסיף (וכ״ה ברבינו גרשום): כלל); אבל הפירוש ד„ותכהין” בפשש״מ הוא (לא שאינו רואה כלל, כ״א) שרק נחלש כח הראי׳ אפילו במקצת, וע״ד מש״נ: כהה הנגע — שלא עמד במראיתו (תזריע יג, ואו ובפרש״י. וראה תו״כ שם). ***) ובפשטות — וגם מזה שגם אחרי „ותכהין עיניו” הי׳ בא״י — משמע שכל ימיו הי׳ „עולה תמימה”. ****) ואף שבבכורות שם דגם „מחסורייתא” (שחסרה מראייתו אבל רואה מקצת — פרש״י) הוי מום — פשיטא שאין הכוונה שלא עמד בראיתו כ״א נחלש במקצת, כ״א אדרבא וכלשון רש״י שהראי׳ היא (רק) מקצת."]]],[1300151226,"זיינען דערמאנט ביז איצטער12, כאטש פילע פון זיי זיינען געווען א סך עלטער פון 123 יאר).\nדעריבער זאגט רש״י אנדערע טעמים אויף „ותכהין”. דאס מיינט, אז (בכלל ובפרט) מצד דער ברכה וואס דער אויבערשטער האט געבענטשט יצחק׳ן, ווען ס׳וואלטן זיך ניט אריינגעמישט קיין זייטיקע ענינים, וואלט ביי אים דאן טאקע געווען (על דרך ווי ביי משה רבינו) „לא כהתה עינו”12*. דא האבן זיך אבער אריינגעמישט זייטיקע סיבות — און זיי האבן גורם געווען אז „ותכהין עיניו”.\nג. וויבאלד אז לערנענדיק דעם פסוק „ותכהין עיניו מראות” ווערט גלייך קשה — ווי קומט עס, אז יצחק, וואס דער אויבערשטער אליין האט עם געבענטשט, זאל ליידן פון כהו עיניו, כנ״ל — לייגט זיך אויפן שכל צו זאגן, אז דער ענטפער אויף דער שאלה איז אנגעדייט אין די פסוקים גופא. און וויבאלד אז דעם פסוק פון „ותכהין עיניו מראות” קומט בהמשך צום פריערדיקן פסוק וואס דערציילט ווי די נשי עשו זיינען געווען „מורת רוח ליצחק ולרבקה” (צוליב דעם וואס זיי האבן געדינט ע״ז<sup data-n=\"13\">13</sup>, איז מסתבר14, אז אין דער סמיכות הכתובים איז מרומז די סיבה פון „ותכהין”15.\nאון דעריבער שטעלט רש״י דעם פירוש אז דער „ותכהין” איז געקומען „בעשנן של אלו”16 גלייך צום אנפאנג אלס פירוש העיקרי, ווייל ער איז מרומז דורך די פסוקים גופא. משא״כ לויט די אנדערע צוויי פירושים, איז די סיבה פון „ותכהין” ניט מרומז בפשטות הכתובים.\nד. אין דעם ערשטן פירוש זיינען אבער דא צוויי שוועריקייטן:\nא) ס׳איז מובן, אז די נשי עשו האבן ניט געוואוינט צוזאמען מיט יצחק׳ן, נאר זיי האבן געהאט א באזונדער דירה (אדער דירות) פאר זיך17; ס׳איז אויך פארשטאנדיק, אז דאס וואס „היו עובדות ע״ז” און „מעשנות וכו׳” האבן זיי געטאן אין זייער (רשות) דירה — און וויבאלד אזוי, איז ניט גלאטיק צו זאגן, אז „עשנן של אלו” אין זייער דירה, האט פארשאדט יצחק׳ן אין זיין הויז.\nב) פארוואס האט „עשנן” געשאדט בלויז יצחק׳ן, און ניט רבקה׳ן18?",[["12","12","אף שי״ל שאין מוזכר זה בכתוב — מפני שאין נפק״מ, משא״כ בנדו״ד (וביעקב), אבל גם עפ״ז עדיין לא יתורץ זה שמוכח בנוגע לכמה אנשים שלא היו סומים אף בגיל של 123 שנה ויותר. 12*) ברכה לד, ז. וראה ב״ר פס״ה, ה: וצדקת צדיקים זה משה (שנאמר בו לא כהתה עינו — ראה בחי׳ פרשתנו כאן) יסורו ממנו זה יצחק כו׳ כהו עיניו."],["13","13","פרש״י כו, לה. ולהעיר שבכמה כת״י רש״י איתא: ד״א מקטירות לע״ז כו׳."],["14","14","אבל מזה לחוד אינו מוכרח — כי אפשר שסמיכות שני ענינים אלו הוא לפי שלא היו ביניהם מאורעות אחרים שדברה בהם תורה."],["15","15","ראה גם תנחומא כאן ח. ראם ושפ״ח כאן."],["16","16","עפמ״ש בפנים יומתק לשון רש״י „בעשנן של אלו” (ולא של נשי עשו), שכוונתו בזה — אלו שנאמרו למעלה, בכדי להדגיש שפי׳ זה מרומז בסמיכות הכתובים."],["17","17","ראה טור הארוך ופענח רזא עה״פ ותהיין מורת רוח גו׳. וראה פרש״י כז, טו."],["18","18","כי לפירוש זה הכיהוי עינים אינו תלוי בזקנה, כדלקמן הערה 26. התירוצים שבתנחומא שהובאו במפרשי רש״י (שרבקה היתה רגילה בע״ז כו׳) הם רק אם נאמר שהכיהוי עינים בא בגלל שהעשן הי׳ של ע״ז, אבל לא לפרש״י (ראה לעיל הערה 2) שבא מהעשן גופא [אבל בשפ״ח כאן: שעשן קשה לעינים אבל רבקה היתה רגילה בו. וראה ג״כ חזקוני ודבק טוב]. בנוגע לנשי עשו — אין הכרח מהכתובים שלא כהו עיניהן. או י״ל שבהקטירן ידעו ליזהר מהעשן. [וכן י״ל בנוגע לעשו, ובפשטות יותר — כי הי׳ „איש שדה” ולא הי׳ נמצא כ״כ בביתו]."]]],[1300151227,"און מחמת די צוויי קשיות אויפן ערשטן פירוש מוז רש״י אנקומען צו די אנדערע פירושים19.\nה. די באזונדערע שוועריקייט אין יעדערן פון די אנדערע צוויי פירושים — (א) „כשנעקד ע״ג המזבח כו׳ וירדו דמעותיהם ונפלו על עיניו”. (ב) „כדי שיטול יעקב את הברכות” [אויסער זייער בשותפות׳דיקע שוועריקייט — ניט האבנדיק אויף זיך קיין רמז אין פסוק, כנ״ל]:\nאין צווייטן פירוש איז קשה: דער תוכן פון דעם פירוש („נפתחו השמים וראו מלאכי השרת והיו בוכים וירדו דמעותיהם וכו׳ לפיכך כהו עיניו”) איז אן ענין פון דרש20, לגמרי ניט עפ״י פשוטו של מקרא — דרכו של רש״י בפירושו עה״ת.\nאויפן דריטן פירוש איז אבער דא נאך א גרעסערע תמי׳: ווי קומט עס אז דער אויבערשטער זאל פארטונקלען די ראי׳ פון יצחק׳ן (און אויף אזוי פיל יארן), בכדי אז א צווייטער, יעקב, זאל דורכ־דעם באקומען די ברכות? ובפרט אז הרבה דרכים למקום, און זיכער האט דער אויבערשטער געהאט אן אנדער וועג דורך וועלכן יעקב זאל קריגן די ברכות.\nאון וויבאלד אז דאס איז א סך א גרעסערע שוועריקייט (ווי די שווע־ריקייט אויפן צווייטן פירוש) — ווייל פארשאפן יסורים און היפך הטוב פאר איינעם צוליב דער טובה פון א צווייטן זעט אויס ווי היפך היושר, א זאך וואס איז לחלוטין ניט שייך צו זאגן ח״ו ביחס צום אויבערשטן — דערפאר שטעלט רש״י דעם פירוש נאכן צווייטן פירוש21.\nו. ווי געזאגט פריער, האט יעדער פון די דריי פירושים א מעלה כלפי די אנדערע צוויי פירושים. אין אנדערע ווערטער: יעדע צוויי פירושים האבן די זעלבע שוועריקייט, אדער ניט גלאטי־קייט, וואס איז ניטא אין דעם דריטן פירוש.\nדער יתרון עיקרי וואס איז דא אין ערשטן פירוש לגבי די אנדערע צוויי באשטייט אין דעם, ווי געזאגט פריער, וואס בלויז ער איז מרומז אין פסוק.\nדי מעלה פון צווייטן פירוש קעגן ערשטן און דריטן: לויט אלע פירושים איז „ותכהין” געווען די סיבה וואס האט גורם געווען אז יצחק זאל די ברכות איבערגעבן צו יעקב׳ן. אבער לויטן ערשטן און דריטן פירוש איז דער „ותכהין” געקומען דורך אן ענין פון גנות און חסרון (לויטן ערשטן פירוש — מצד דעם עשן פון ע״ז, און לויטן דריטן פירוש — מצד דעם וואס יצחק האט געוואלט בענטשן עשו׳ן) — ובמילא קומט אויס אז אן ענין פון גנות און חסרון האט געבראכט צו .. די ברכות!",[["19","19","עוד מעלה בפירושים אלו על פירוש הא׳: לפי הא׳ קשה מדוע נאמר „ותכהין” אחרי „זקן יצחק”* (ראה לקמן ס״ו) — משא״כ לפי הג׳ (כדלקמן שם): וגם לפירוש הב׳ יש לתרץ כדלקמן הערה 26."],["20","20","וצע״ק למה לא כתב רש״י ע״ז „ומדרשו”, כדרכו בכ״מ. *) ובפרט שלפירוש הראשון נמצא שהתיבות „ויהי כי זקן יצחק” מפסיקות סמיכות הכתובים (בין „ותכהין” ל„ותהיין מורת רוח גו׳”). כמ״ש במשכיל לדוד כאן."],["21","21","בסגנון אחר: הקושי על פי׳ הב׳ הוא רק שאין לו מקור בפשש״מ (אבל הפירוש בקרא — ש„ותכהין” בא ע״י דמעות המלאכים — מתקבל על הדעת); משא״כ הקושי על פי׳ הג׳ הוא שעצם הפירוש (הטעם על „ותכהין”) אינו מתקבל כו׳ [וע״ד משנ״ת ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051043\" data-slug=\"likkutei-sichot\" data-id=\"1300051043\">לקו״ש ח״ה (ע׳ 43</a> הערה 39) זה שבכ״מ מקדים רש״י פי׳ האגדה ל„פשוטו”]."]]],[1300151228,"משא״כ לויטן צווייטן פירוש איז אדרבה: דער „ותכהין” איז געקומען צוליב יצחק׳ס מעלה — צוליב דער עקידה22.\nאויך דער דריטער פירוש האט א מעלה לגבי די ערשטע צוויי:\nלויט די ערשטע צוויי פירושים קומט אויס, אז „ותכהין עיניו מראות” איז געשען א סך פריער פארן זמן פון „זקן יצחק”. וואָרום בעת עשו האט גענומען די נשים חתיות (אלט זייענדיק „ארבעים שנה”<sup data-n=\"23\">23</sup> איז יצחק דאן אלט געווען הונדערט יאר (ווייל ווען עשו איז געבארן געווארן איז יצחק אלט געווען זעכציק יאר<sup data-n=\"24\">24</sup>. און לויטן צווייטן פירוש, אז דאס איז געקומען מצד די דמעות המלאכים, האט עס פאסירט נאך פריער — ווען יצחק איז אלט געווען 37 יאר25.\nשטעלט זיך די שאלה: פארוואס שטייט אין פסוק פריער „כי זקן יצחק” און דערנאך „ותכהין”? לויט די ערשטע צוויי פירושים26 האט דאך געדארפט שטיין אין א פארקערטן סדר, לויטן סדר המאורעות?\nלערנט דעריבער רש״י א דריטן פירוש „כדי שיטול יעקב את הברכות”, וואס לויט דעם פירוש איז גלאטיק דער סדר הכתוב: „ויהי כי זקן יצחק” און צוליב דעם האט ער געוואלט געבן די ברכות צו עשו׳ן, איז דערפאר — „ותכהין גו׳”, כדי אז יעקב זאל נעמען די ברכות.\nז. פון די הוראות פון דעם דריטן פירוש אין רש״י: ווי ווייט מען דארף זיין נזהר אין ריידן לשון הרע:\nלכאורה: בכדי אז יעקב זאל נעמען די ברכות האט דאך דער אויבערשטער געהאט א פשוט׳ע עצה — צו מגלה זיין יצחק׳ן27 אז עשו איז א רשע28, ובמילא וועט ער געבן די ברכות צו יעקב׳ן!\nובפרט, אז וועגן עשו׳ס פרויען האט שוין יצחק געוואוסט אז זיי דינען ע״ז29 (יצחק האט אבער געמיינט אז עשו איז ניט שולדיק אין דעם: ער קען אויף זיי ניט משפיע זיין), און אויך וועגן עשו׳ן אליין האט ער געוואוסט אז „עפעס” איז מיט אים ניט אינגאנצן גלאטיק — „אין דרך עשו להיות שם שמים שגור בפיו”30 —\nהיינט בשעת אז יצחק האט סיי ווי שוין געהאט עפעס א חשד אויף עשו׳ן, האט דאך אים דער אויבערשטער שוין געקענט מגלה זיין די גאנצע זאך, אז עשו איז א רשע און מ׳וואלט ניט",[["22","22","עוד יתרון בפירוש זה על פירוש הא׳ והג׳: לפי׳ זה (שכהו עיניו בעת מעשה העקידה, כדלקמן בפנים) מתורץ בפשטות למה לא הרגיש יצחק הא ד„זה (עשו) פירש לע״א” (פרש״י פרשתנו כה, כז), משא״כ לפי׳ הא׳ והג׳ שכהו עיניו לאח״ז."],["23","23","פרשתנו כו, לד."],["24","24","שם כה, כו."],["25","25","פרש״י פרשתנו כה, כ."],["26","26","עיקר הקושיא הוא לפירוש הראשון. כי בנוגע לפי׳ הב׳ י״ל בדוחק שהדמעות שנשרו מעיני המלאכים „היו רשומות בתוך עיניו” (ב״ר פס״ה, י׳), ובמילא פעולת הדמעות היתה פעולה נמשכת, ולא כהו עיניו רק לאחרי שהזקין [וכמ״ש בפענח רזא כאן. וראה מהרש״ל (והובא בש״ח) כאן. פדר״א פל״ב]. משא״כ לפי׳ הא׳ „בעשנן של אלו” פשוט שכבר כהו עיניו כמה זמן לפני זה, ולא רק עתה (כאשר „זקן יצחק” — קכג שנה) ע״י ריבוי העשן ד...קכג שנה!"],["27","27","ראה פרש״י וישב לז, לג: ולמה לא גלה לו הקב״ה כו׳."],["28","28","ובפרט אשר בלאה״כ ראה יצחק שדברים בגו, שהרי אברהם אביו לא ברכו (ראה פרש״י ח״ש כה, יא)."],["29","29","פרש״י פרשתנו כו, לה."],["30","30","שם כז, כא (מב״ר פס״ה, יט. תנחומא באבער פרשתנו יוד). אבל ראה רמב״ן ומפרשי רש״י שם."]]],[1300151229,"געדארפט אנקומען צו „ותכהין” פון יצחק׳ן.\nזעט מען דערפון אויף ווי ווייט מען דארף זיין31 אפגעהיט פון ריידן לשון הרע: יצחק איז געווען 57 יאר „כלוא בבית” און „כמת” אבי מ׳זאל ניט ריידן אויף א אידן (אפילו אויף א ישראל מומר<sup data-n=\"32\">32</sup> לשון הרע!\nאון אויב בשייכות צו עשו׳ן איז עס אזוי, איז בנוגע צו אידן נאך מתן תורה — נאכדעם ווי דער אויבערשטער האט געזאגט צו יעדער איד33 „אנכי הוי׳ אלקיך”, אז ביי יעדער איד איז „אנכי הוי׳” געווארן „אלקיך”, זיין כח וחיות34 — על אחת כמה וכמה.\n(משיחות ש״פ תולדות וש״פ וישלח תשכ״ח)",[["31","31","עד״ז (סנה׳ יא, א. ועוד): חטא ישראל כו׳ וכי דילטור אני."],["32","32","ראה קידושין יח, רע״א."],["33","33","בלשון יחיד (ראה רמב״ן יתרו כ, ב. פס״ר פכ״א, ו)."],["34","34","לקו״ת ר״פ ראה. ובכ״מ."]]],[1300151230,"<h3>תולדות ד</h3>\nא. אויף די ווערטער „לא ידעתי יום מותי\" (אין אונזער פרשה<sup data-n=\"1\">1</sup> זאגט רש\"י 2: „אמר ר' יהושע בן קרחה אם מגיע אדם לפרק אבותיו ידאג חמש שנים לפניהם וחמש לאחר כן, ויצחק הי' בן קכ\"ג 2*, אמר שמא לפרק אמי אני מגיע והיא בת קכ\"ז מתה והריני בן ה' שנים סמוך לפרקה, לפיכך לא ידעתי יום מותי שמא לפרק אמי שמא לפרק אבא\".\nדארף מען פארשטיין:\nא) וואס זוכט רש\"י א הסבר פאר־וואס האט יצחק געזאגט „לא ידעתי יום מותי\", בעת יצחק אליין זאגט דא פריער דעם טעם: „ויאמר הנה נא זקנתי\" — איך בין אלט געווארען (און דערפאר איז „לא ידעתי יום מותי\")?\nב) צוליב וואס דארף רש\"י ברענ־גען דעם נאמען פון דעם בעל המאמר 3? וואס איז דא ניט קלאר אדער ניט גלאטיק אין דעם פירוש, וואס דורך דער ידיעה, אז דעם פי־רוש האט געזאגט ריב\"ק, וועט עס ווערן קלאר און פארשטאנדיק?\nב. איז דער ביאור אין דעם: אין דער פריערדיקער סדרה 4 שטייט „ויברך אלקים את יצחק\", טייטשט רש\"י: „נתיירא (אברהם) לברך את יצחק מפני שצפה את עשו יוצא ממנו אמר יבא בעל הברכות ויברך את אשר ייטב בעיניו ובא הקב\"ה וברכו\".\nוויבאלד אזוי, שטעלט זיך די שאלה ביי אונזער פסוק: האבנדיק די ברכה פונעם אויבערשטן אליין, פון דעם בעל הברכות, איז דאס זיכער כולל אריכות ימים, האט יצחק ניט געדארפט איבערטראכטן וועגן יום מותו אין עלטער פון הונדערט מיט דריי און צוואנציק יאר, והא ראי': אברהם און שרה וועלכע האבן גע־האט א ברכה פון אויבערשטן האבן מאריך ימים געווען מער ווי הונדערט און דריי און צוואנציק יאר.\nדעריבער זאגט רש\"י אז יצחק's זארג האט זיך גענומען דערפון וואס ער האט דערגרייכט דעם עלטער וואס איז אפגערוקט פינף יאר פון זיין מוטערס פטירה; און מיט „הנה נא זקנתי\" האט ער געמיינט ניט סתם אלטקייט, נאר א באשטימטן עלטער, וואס איז פארבונדן מיט „פרק אמו\".\nעס קען דאך אבער ווערן ניט רעכט: ווי שטימט אט דער כלל, וויבאלד יצחק האט לפועל געלעבט 180 יאר 5 א סך מער ווי פינף יאר „סמוך לפרקה\" פון זיין מוטער? —",[["1","1","כז, ב."],["2","2","מב\"ר פס\"ה, יב. 2*) כן הוא בכ\"מ „קכ\"ג\", וכן לקמן בפרש\"י בסוף הסדרה (ממגילה יז, א) דיעקב הי' אז בן סג. ולכאורה הי' צריך לדאוג בהיותו בן קכב. וכמו שחי יצחק ה' שנים סמוך לפרק אביו והי' זה קפ שנים. ולהעיר מקו\"א לאדה\"ז ריש הל' ת\"ת שלו."],["3","3","כמדובר כמה פעמים שע\"ד הרגיל אין רש\"י מציין שם בעל המאמר, ועד\"ז שבפסוק הקודם אינו כותב שפירושיו הם בתנחומא וב\"ר כאן."],["4","4","כה, יא."],["5","5","וישלח לה, כח. הובא כבר בפרש\"י פרשתנו כה, ל."]]],[1300151231,"באווארנט עס רש\"י, אז אין דעם זיינען פאראן אייניקע אופנים: פינף יאר פאר אדער נאך „פרק אבותיו\": און אין פרק אבותיו גופא מיינט עס אדער פרק אמו אדער פרק אביו. ביי יצחק'ן, וואס האט געלעבט הונדערט און אכציק יאר, איז לפועל געווען דער אופן פון פינף יאר נאך פרק אביו 6.\nג. לכאורה, אויך נאכדעם ווי רש\"י איז עס מבאר מיט זיין פירוש בלייבט נאך אלץ שווער די קשיא: די ברכה וואס דער אויבערשטער האט געבענטשט יצחק'ן האט דאך געוויס געבראכט א הוספה אין זיינע פרטי החיים און אוודאי אין עצם החיים גופא — א הוספה אין אריכות ימים, מערער ווי ער וואלט געדארפט לעבן מצד הטבע. היינט אויב אז אפילו אין סדר הרגיל דערגרייכט א מענטש דעם עלטער פון די יארן סמוך לפרק אבותיו, האט דאך די ברכה וואס דער אויבערשטער האט יצחק'ן געבענטשט, אים זיכער צוגעגעבן מער ווי די צאל יארן פון פרק אבותיו. שטעלט זיך די שאלה:\nא) פארוואס האט יצחק געלעבט ניט מער ווי 180 יאר? וויבאלד אז אט די צאל יארן איז ניט מער ווי א זאך — וואס קומט אויך עפ\"י דרך הטבע — וואו איז דער צוגאב פון אריכות ימים וואס דארף קומען מצד ברכת ה' 7 ?\nב) דאס זעלבע קען מען פרעגן אויך אויף דעם, וואס צו 123 יאר האט שוין יצחק געזאגט „לא ידעתי יום מותי\": וויבאלד דאס איז דער סכום יארן וואס ער האט אמווייניקסטן געדארפט לעבן אויך לויטן סדר הרגיל בטבע (מיט פינף יאר ווינציקער ווי דער קירצסטער פון „פרק אבותיו\") און די ברכה האט דאך זיכער עפעס צוגע־געבן צו אט די יארן — היינט פאר־וואס האט ער צו 123 יאר שוין געזאגט „לא ידעתי יום מותי\" ?\nד. דער ביאור אין דעם:\nבשעת אברהם איז אלט געווען קנאפע 100 יאר און שרה קנאפע 90 יאר, זיינען זיי שוין דעמאלט געווען ניט נאר „זקנים\" נאר אויך „באים בימים\" 8 — שוין אריין אין אלע זייערע טעג, אלע טעג 9 וואס זיינען פאר זיי באשטימט געווארן 10 (און דאס וואס בפועל האבן זיי געלעבט לענגער, איז עס געווען מצד דער ברכה וואס דער אויבערשטער האט זיי געבענטשט).\nלויט דעם קומט אויס, אז מצד הטבע, אן דער ברכה פון אויבערשטן, האט יצחק צו 105 יאר שוין דער־גרייכט דעם העכסטן עלטער ווי דאס איז מצד „פרק אבותיו\": מיט פינף יאר",[["6","6","כי משמע ד„פרק\" דכאן הכוונה אפילו באם הי' מאורע וסיבה בחייו שלא האריך ימים יותר כמו — בשרה שמתה מפני בשורת העקדה (פרש\"י כג, ב)."],["7","7","לכאורה אפ\"ל, שמצד הטבע נקבע ליצחק ה' שנים פחות מאביו, או (יתירה מזה) לפי פרק אמו (ובזה גופא — ה' שנים פחות מאמו) — והברכה הוסיפה עד ה' שנים יותר מאביו — שלימות הטבע. אבל דוחק גדול הוא לומר שברכת ה' (בעל הברכות) היתה רק במדה שמתאימה גם ע\"פ טבע, ולא יותר."],["8","8","וירא יח, יא."],["9","9","ובזח\"א (רכד, א) מוסיף שנתלבש בכל הימים. וראה תו\"א פ' ח\"ש. ובכ\"מ."],["10","10","וצע\"ק ממש\"נ באברהם פעם ב' בא בימים (ח\"ש כד, א)."]]],[1300151232,"מער ווי די הונדערט יאר וואס זיינען באשטימט (אן דער ברכה) פאר זיין פאטער (וואָרום „פרק אבותיו\" מיינט די יארן וואס זיינען זייער פרק 11 — ניט דער ברכה פון בעל הברכות).\nבמילא — איז סיי אליבא דאמת און סיי לפי דעתו של יצחק, האט דעם אויבערשטנ's ברכה זייער פיל צו־געגעבן צו יצחק's יארן; און — די זעלבע צאל יארן וואס דעם אוי־בערשטנ's ברכה האט צוגעגעבן זיין פאטער:\nבפועל האט יצחק געלעבט 180 יאר — און אין דעם האט די ברכה גע־האט מוסיף געווען 75 יאר אויף די 105 יאר וואס ער וואלט אמהעכסטן דערגרייכט מצד סדר הרגיל (מיט פינף יאר מער פון זיין פאטער's באשטימטע 100 יאר) — און דאס איז פונקט דער זעלבער סכום יארן וואס די ברכה האט צוגעגעבן זיין פאטער אברהם, וואס האט געלעבט 175 יאר: מיט 75 יאר מער פון די באשטימטע הונדערט, כנ\"ל.\nאון אזוי איז אויך לפי דעתו של יצחק, וואס האט חושש געווען טא־מער זיינען זיינע יארן מיט פינף יאר ווייניקער פון „פרק אמי\" — איז דער חשבון בזה: די ברכה האט אים שוין מוסיף געווען די זעלבע צאל יארן ווי די ברכה האט צוגעגעבן זיין מוטער: שרה's באשטימטע יארן זיינען געווען — נייניציק, און דורך דער ברכה האט זי געלעבט 127 יאר — זיבן און דרייסיק יאר מערער; און אזוי אויך וואלט יצחק געלעבט (לפי דעתו, און\n— אן דער ברכה) בלויז 85 יאר (מיט פינף יאר ווייניקער ווי זיין מוטער), און פונקט ווי צו זיין מוטער האט אויך אים די ברכה צוגעגעבן נאך זיבן און דרייסיק יאר — האט ער דער־פאר אנגעהויבן דאוג זיין נאך 122 יאר — צו 123 יאר.\nה. עס איז אבער נאך אלץ דא א שוועריקייט: רש\"י שרייבט פריער 12, אז אברהם איז נפטר געווארן פינף יאר פאר דער צייט מצד דעם אויבער־שטנ's צווייטע ברכה צו אברהמ'ען „תבוא . . בשיבה טובה\" בכדי ער זאל ניט זען וי עשו איז יוצא לתרבות רעה. היינט וויבאלד אברהם האט גע־דארפט לעבן מצד דער ערשטער ברכה 180 יאר, קומט דאך אויס, אז יצחק וואס האט אויך געהאט די ברכה און צוזאמען מיט די פינף יאר מער פון פרק אביו, האט ער געדארפט לעבן 185 יאר און ניט בלויז 180.\nאון דעם ענטפער אויף דעם איז רש\"י מרמז אין דעם צוגעגעבענעם ענין „אמר ר' יהושע בן קרחה\":\nאין גמרא 13 ווערט דערציילט, וועגן א צאל תנאים ביי וועלכע מען האט געפרעגט „במה הארכת ימים\", און יעדערער פון זיי האט אנגעגעבן עטלעכע זאכן אין וועלכע ער איז געווען באזונדערס אפגעהיט, וואס צור־ליב זיי האט ער זוכה געווען צו אריכות ימים. די זעלבע שאלה („במה הארכת ימים\") האט מען אויך גע־פרעגט ביי ריב\"ק, און ער האט דערויף געענטפערט: „מימי לא נס־תכלתי בדמות אדם רשע\". ער האט",[["11","11","כולל גם מאורעות וסיבותיהם שבחייהם — ראה הערה 6."],["12","12","לך טו, טו. פרשתנו שם."],["13","13","מגילה כז, ב ואילך."]]],[1300151233,"זיין אריכות ימים פארבונדן בלויז מיט דער איינציקער זהירות — ער האט זיך אלעמאל געהיט פון איינצוקוקן אינעם געשטאלט פון אן אדם רשע.\nזעט מען דערפון, אז ריב\"ק האלט אז דאס אויסהיטן זיך פון הסתכלות בפני אדם רשע אליין איז שקול כנגד כמה ענינים וואס ברענגען צו אריכות ימים. ומכלל הן אתה שומע לאו: בשעת מען איז זיך יא מסתכל בפני אדם רשע, איז עס גורם א פארמינע־רונג פון אריכות ימים.\nאיז שוין רעכט וואס יצחק האט בלויז 180 יאר געלעבט: ער האט ניט אויסגעהיטן די הסתכלות בדמותו של עשו; און הגם ער האט טאקע ניט גע־וואוסט אז ער איז א רשע, האט אבער די הסתכלות גורם געווען 14 אז פון די 185 יאר וואס ער האט געדארפט לעבן, זאלן אפגענומען ווערן דער סמוך לפרק אביו (פינף יאר) — און די ברכת ה' האט אויפגעטאן אז ער זאל מאריך ימים זיין ווי „פרק אביו\" 15.\nו. אין פירוש רש\"י איז דאך פא־ראן אויך „יינה של תורה\" 16:\nדאס וואס יצחק האט מורא געהאט, אז זיינע יארן וועלן זיין מיט פינף יאר ווייניקער פון „פרק אמו\" — דער נידעריקסטער אופן אין סדר הטבע (און נאך מער: אויך אין „פרק אמו\" האט ער גערעכנט בלויז די 127 יאר וואס שרה האט געלעבט בפועל, ניט געקוקט אויף דעם וואס איר איז באמת\nגעווען באשערט צו לעבן לענגער און נאר בסיבת העקידה איז „פרחה נשמתה\"<sup data-n=\"17\">17</sup> — איז דעם טעם הפנימי דערפון, וויל יצחק איז במדריגתו קו הגבורה. און דערפאר האט ער געקוקט אויף אלע ענינים און זיי געמאסטן לויט מדת הגבורה.\nדאס איז געווען יצחק's הנהגה נאר אין שייכות צו זיך, בשעת ער האט אבער געבענטשט א צווייטן, איז זיין ברכה געווען אויפן העכסטן אופן פון היפך (הגבורה ו)הצמצום: זי האט כולל געווען סיי די ענינים פון „שמים\" סיי די ענינים פון „ארץ\", און אין זיי גופא „מטל השמים ומשמני הארץ\" 18 — אזעלכע ברכות וואס זיינען גרעסער אויך פון ברכת יעקב לבניו און פון ברכת משה לישראל 19.\nאון דאס איז א הוראה אין עבודה פון יעדער אידן — וואס יעדער איד איז יצחק איינער פון זיינע אבות און ער האט דערפאר פון זיינע ענינים 20: א איד ווען ער שטייט אפילו אין א הנהגה פון קו הגבורה, און דעריבער איז ער מחמיר וכו', דארף עס זיין בנוגע צו זיך אליין. ווען עס קומט אבער צו א צווייטן אידן דארף ער זיך פירן לויטן קו החסד, זיך באציען צו אים במדת הטוב און אים משפיע זיין גוטס ביד רחבה, אן קיין צמצומים והגבלות, ביז צו דער העכסטער מאס — „מטל השמים\" און „משמני הארץ\".\n(משיחות ש\"פ תולדות וש\"פ וישלח תשכ\"ח)",[["14","14","ראה מגילה שם (כח, א. ועד\"ז בתנחומא וכו' עה\"פ): „ר\"א אמר עיניו כהות שנאמר ויהי כי זקן יצחק ותכהין עיניו מראות משום דאסתכל בעשו הרשע\" — אף שיצחק לא ידע כו'."],["15","15","להעיר מפרש\"י בריש הסדרה „צר קלסתר פניו של יצחק דומה לאברהם\", ומפרש\"י כה, ל."],["16","16","היום יום ע' כד."],["17","17","פרש\"י ח\"ש כג, ב."],["18","18","פרשתנו כז, כח. וראה תו\"א ד\"ה ראה ריח בני. תו\"ח ד\"ה ויתן לך. אוה\"ת שם. ובכ\"מ."],["19","19","סידור שער התקיעות (רמז, ב)."],["20","20","תו\"א ר\"פ וארא."]]],[1300151234,"<h3>תולדות ה</h3>\nא. אין פסוק ¹ „וישמע יעקב גו׳ וילך פדנה ארם”, איז רש״י מפרש — אויף די ווערטער „וישמע יעקב” ² — „מחובר לענין של מעלה, וירא עשו כי ברך יצחק וגו׳, וכי שלח אותו פדנה ארם, וכי שמע יעקב אל אביו והלך פדנה ארם, וכי רעות בנות כנען, והלך גם הוא אל ישמעאל”.\nלערנענדיק אין פשטות, באווארנט דא רש״י: מ׳קען ניט זאגן אז מיט „וישמע יעקב גו׳” מיינט די תורה צו דערציילן די מאורעות, אז יעקב אבינו האט געפאלגט זיין פאטער און געגאנגען קיין פדן ארם — ווייל דאס איז שוין דער־ציילט געווארן פריער ³ אין דער פרשה („וישלח יצחק את יעקב וילך גו׳”) ⁴, און די פסוקים וואס שטייען פאר און נאך „וישמע יעקב” ריידן גאר וועגן עשו׳ן — דעריבער איז רש״י מסביר, אז „וישמע יעקב” קומט בהמשך צו „וירא עשו” וואס שטייט אין פריערדיקן פסוק, דער פסוק רעכנט אויס נאך א פרט וואס עשו האט געזען.\nמ׳דארף אבער פארשטיין:\nא) אט דער אויפטו, אז „וישמע יעקב” איז „מחובר” צו „וירא עשו”, וואלט געווען מובן אויך ווען רש״י וואלט גע־זאגט בקיצור „וישמע יעקב, מחובר לענין של מעלה וירא עשו” ⁵: צוליב וואס איז רש״י מפרט די אלע פרטים וואס עשו האט געזען און וועלכע שטייען בפירוש אין פסוק?\nב) אין פסוק ווערט דערציילט נאך א זאך וואס עשו האט געזען — „ויצו עליו לאמר לא תקח אשה מבנות כנען” — פארוואס איז רש״י משמיט דעם פרט?\nג) צווישן די פרטים אין דעם „ענין של מעלה” צו וועלכע „וישמע יעקב” איז מחובר, האט, לכאורה, אן ארט אויסצורעכענען נאר די וועלכע שטייען פאר „וישמע יעקב”, אבער ניט דעם פרט פון „וישמע יעקב” גופא, און מכ״ש ניט דעם פרט פון „כי רעות בנות כנען” וואס שטייט נאך „וישמע יעקב”.\nד) נאך מער פלא איז, וואס רש״י איז מסיים „והלך גם הוא אל ישמעאל” — וואס דאס געהערט ניט צו די פרטים וואס עשו האט געזען, נאר דאס איז די תוצאה בפועל פון „וירא עשו”: ווען ער האט געזען אז „רעות בנות כנען” איז ער אוועק צו ישמעאל.\nמ׳קען ניט זאגן אז מיט דעם סיום „והלך גם הוא אל ישמעאל” מיינט רש״י צו מסביר זיין ⁶, אז די אלע פרטים וואס „וירא עשו” — האבן דערפירט צו „וילך עשו אל ישמעאל” (און דעריבער רעכנט אויס רש״י אלע פרטים וועלכע שטייען",[["1","1","פרשתנו כח, ז."],["2","2","ראה לקמן הערה 18."],["3","3","שם, ה."],["4","4","משכיל לדוד כאן."],["5","5","ויתירה מזה: הפירוש ד„וישמע יעקב” מחובר ל„וירא עשו” ואינו סיפור עוה״פ ע״ד יעקב, לכאורה — מובן הוא מעצמו [ע״ד הפשט. משא״כ ע״ד הדרש — ראה ב״ר פס״ז, יב. תנחומא באבער ויצא א], ואין צריך רש״י לפרשו."],["6","6","הרא״ם מפרש שכוונת רש״י היא לבאר שהוא״ו שבתיבת „וילך” אינה משמשת לחיבור, כ״א להפוך העתיד לעבר — אבל ביאור זה אינו שייך, לא להתיבות „וישמע יעקב” שרש״י מעתיקם ולא לפירושו „מחובר לענין של מעלה”."]]],[1300151235,"אין פסוק, אויך „וכי שמע כו׳ והלך כו׳ וכי רעות כו׳ והלך כו׳”) —\nווייל דער ענין, אז „וירא עשו” איז א הקדמה און די סיבה פון „וילך עשו גו׳” איז פארשטאנדיק פון זיך אליין: אויך אן רש״י׳ס פירוש אז „וישמע יעקב” איז „מחובר לענין של מעלה”, וואלט מען פארשטאנען אז אלע פרטים וועלכע שטייען אין פסוק (אויסער „וישמע יעקב גו׳”) זיינען א הקדמה צום אויספיר „וילך עשו גו׳”.\nפון דעם וואס רש״י שטעלט דאס אריין אין זיין פירוש „מחובר לענין של מעלה” איז פארשטאנדיק, אז דאס קומט אין פארבינדונג מיט דעם פירוש: דוקא נאך רש״י׳ס אויפטו אז „וישמע יעקב” איז „מחובר לענין של מעלה” (און די אלע פרטים וועלכע רש״י רעכנט אויס), ווערט פארשטאנדיק דער פסוק „וילך עשו אל ישמעאל”, און דעריבער איז רש״י מסיים „והלך גם הוא אל ישמעאל”.\nב. וועט מען דאס פארשטיין בהק־דים: וויבאלד אז נאך דעם ווי דער פסוק זאגט שוין איינמאל „וירא עשו [כי ברך יצחק גו׳ ושלח אותו גו׳ ויצו עליו גו׳]”, חזר׳ט איבער דער פסוק נאכאמאל „וירא עשו [כי רעות בנות כנען בעיני יצחק אביו וילך גו׳]”, איז פארשטאנדיק פון דעם, אז די זאכן וואס עשו האט געזען באשטייען פון צוויי סוגים, וואס ביי יעדן סוג איז געווען אן אנדער (אופן פון) „וירא” און דעריבער שטייט „וירא עשו” צוויי מאל.\nאון דער חילוק צווישן די צוויי „וירא” איז — ע״ד פרש״י לעיל (אין אנהויב פ׳ וירא ⁷) — „מהו וירא וירא שני פעמים. הראשון כמשמעו והשני לשון הבנה נסתכל כו׳ והבין כו׳”: דער ערשטער „וירא עשו” מיינט אז ער האט געזען („כמשמעו”) זאכן וואס זיינען פאר־געקומען ביי אנדערע — צווישן יצחק׳ן מיט יעקב׳ן („ברך גו׳ את יעקב ושלח אותו גו׳ ויצו עליו גו׳”); דאקעגן דער צווייטער „וירא” איז „לשון הבנה” — ער האט זיך איבערצייגט („נסתכל כו׳ והבין” *<sup data-n=\"7\">7</sup> אז „רעות בנות כנען בעיני יצחק אביו”, וואס דער „וירא” איז אן ענין וואס איז אים נוגע און אים מחייב צו (כהמשך הכתובים, אז דער „וירא” האט אים באווירקט צו) גיין צו ישמעאל׳ן.\nמ׳דארף אבער פארשטיין: דער תכלית פונעם גאנצן סיפור פון „וירא עשו” איז דאך צו ערקלערן די סיבה וואס האט דערפירט צו „וילך עשו אל ישמעאל ויקח גו׳”, און אויף דעם וואלט געווען גענוג דער פרט פון צווייטן „וירא” — „וירא עשו כי רעות בנות כנען בעיני יצחק אביו (וואס דעריבער) וילך עשו גו׳” — צוליב וואס דערציילט די תורה די גאנצע אריכות וואס עשו האט געזען ביים ערשטן „וירא” ⁸?\n[לכל היותר וואלט מספיק געווען צו דערציילן דעם פרט פון „ויצו עליו לאמר לא תקח אשה מבנות כנען” וואס פון דעם האט ער „וירא” — פאר־שטאנען אז „רעות בנות כנען גו׳” און דעריבער „וילך עשו גו׳”\n— און דוקא דעם פרט איז רש״י משמיט, כנ״ל].",[["7","7","יח, ב. וראה בראשית ג, ז ובפרש״י. וישב מ, טז. פרש״י מקץ מב, א. ועוד. *7) כי ראי׳ (כמשמעו) דאופי בנות כנען — ידע מכבר (שהרי נשיו היו מבנות כנען) ועתה נתחדש אצלו והבין שהן רעות בעיני יצחק."],["8","8","ראה גם אלשיך ר״פ ויצא. אוה״ח כאן פסוק ר."]]],[1300151236,"ג. דער ביאור אין דעם: דאס וואס די תורה דערציילט די גאנצע אריכות איז צו פארענטפערן א תמי׳ אין דעם ענין פון „וילך עשו אל ישמעאל”:\nדאס וואס עשו איז געגיין נעמען ישמעאל׳ס טאכטער, און האט ניט גע־נומען פון די בנות כנען וואס האט זיך געפונען בשכנות, איז געווען בכדי צו ווייזן אז ער (שטייט ניט אפ פון יעקב׳ן און אויך ער) איז מקיים דעם רצון פון יצחק׳ן ⁹.\nאיז ניט מובן: יצחק האט דאך אנגע־זאגט יעקב׳ן ניט נאר „לא תקח אשה מבנות כנען”, נאר אויך „שלח אותו פדנה ארם לקחת לו משם אשה”. און יעקב האט מקיים געווען סיי דעם צד שלילי און סיי דעם צד חיובי; ער האט ניט גענומען פון די בנות כנען, און איז געגאנגען קיין פדן ארם:\nהיינט פארוואס האט עשו נאר — ניט גענומען אשה מבנות כנען, ער איז אבער ניט געגאנגען קיין פדן ארם ¹⁰ בכדי לקחת לו משם אשה ¹¹?\nבכדי צו פארענטפערן אט די תמי׳ אין הנהגת עשו ¹², זאגט תורה צוויי מאל „וירא עשו” ¹³: אז אין די זאכן וועלכע עשו האט געזען זיינען געווען, כנ״ל, צוויי סוגים, וואס יעדערער קומט מסביר זיין אן אנדער פרט אין „וילך עשו אל ישמעאל”: דער ערשטער „וירא” איז מסביר פארוואס עשו האט אנגענומען אז ער דארף ניט גיין קיין פדן ארם; דער צווייטער „וירא” — פארוואס עשו איז — געגיין נעמען אן אשה פון ישמעאל.\nד. והביאור: די שליחות וואס יצחק האט געשיקט יעקב׳ן קיין פדן ארם „לקחת לו משם אשה”, איז לויט עשו׳ס מיינונג ¹⁴ געווען (ניט דערפאר ווייל יצחק האט געהאלטן אז נאר דארט איז דער שידוך הראוי, נאר) א מיטל און כלי צו באקומען די ברכות מיט וועלכע יצחק האט אים געבענטשט ¹⁵, און ווי דער פסוק איז דא נאכאמאל מדגיש: „(וירא עשו כי ברך גו׳) ושלח אותו פדנה ארם גו׳ בברכו אותו גו׳”. און דעריבער האט ער געהאלטן אז דער ענין פון „(וישמע יעקב גו׳) וילך פדנה ארם” איז נוגע בלויז צו יעקב׳ן ¹⁶, און צו אים, עשו׳ן, האט עס ניט קיין שייכות —",[["9","9","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051177\" data-slug=\"likkutei-sichot\" data-id=\"1300051177\">לקו״ש ח״ה ע׳ 165</a> (ובהערה 13 שם)."],["10","10","כי אף שבנות ישמעאל הן ממשפחת אברהם (וראה רשב״ם, אברבנאל אוה״ח ועוד כאן) — מ״מ, מכיון שיצחק ציוה ליעקב ליקח אשה מבנות לבן דוקא (ולא מבנות ישמעאל) *), גם עשו הי׳ צריך לעשות כן. ולהעיר מפרש״י ויצא (כט, יז): שהיו הכל אומרים כו׳ הגדולה לגדול כו׳."],["11","11","ראה אלשיך שם (שהי׳ ענין נסי ש„בל ישית לב אל כל דברי אביו רק על מחצית׳ כו׳”, עיי״ש. וראה הערה 13)."],["12","12","להעיר מפרש״י לעיל כה, לד (אבל אינו דומה לנדר״ד שב׳ הציוויים — „לא תקח גו׳ וקח לך משם אשה גו׳” — נאמרו יחד, ולכאורה אין מקום לחלק ביניהם). *) ולהעיר מפרש״י חיי שרה כד, מט."],["13","13","כי מכיון שבהכתובים שקודם „וירא עשו” (שם, א־ב) מסופר ב׳ הענינים: „ויצוהו גו׳ לא תקח גו׳ קום לך פדנה ארם” — הרי מובן, שעשו ראה לא רק הציווי „לא תקח גו׳ מבנות כנען” אלא גם השליחות לפדן ארם (דמאי שנא), ובמילא הוצרך הכתוב לבאר הטעם על שלא השתדל עשו ללכת פדן ארם."],["14","14","משא״כ לדעת יעקב — ולכן, ג״ז הי׳ סיבה להליכת יעקב לפדן ארם, היינו שגם בתוכן — ולא רק בזמן — הי׳ זה קודם ל„וילך פד״א”."],["15","15","וראה רמב״ן כאן (פסוק ה׳). אלשיך שם."],["16","16","ועפ״ז יומתק מה שהכתוב מקדים בראיית עשו „וישמע יעקב וגו׳” — כי גם זה ביאור על אי הליכתו לפדן ארם. כי מכיון אשר „וישמע יעקב גו׳”, הברכות הן כבר של יעקב. (משא״כ באם לא שמע יעקב וגו׳ הי׳ הולך עשו לפד״א בחשבו שע״י הליכתו יקבל הוא את הברכות)."]]],[1300151237,"און דערפאר איז ער ניט געגאנגען קיין פדן ארם.\nדאקעגן יצחק׳ס ציווי „לא תקח אשה מבנות כנען” איז אין דעם „וירא (הבין) עשו” אז דאס איז ווייל „רעות בנות כנען בעיני יצחק אביו”, דעריבער האט עס א שייכות אויך צו אים, און דערפאר — „וילך עשו אל ישמעאל גו׳”.\nה. לויט דעם אלעם איז מובן די אריכות אין פירוש רש״י:\nנאכדעם ווי רש״י זאגט אז „וישמע יעקב” איז (ניט א מאמר המוסגר, נאר) מחובר און א פרט אין „וירא עשו” קומט רש״י באווארענען וואס ביים ערשטן „וירא עשו” (פאר די ווערטער „וישמע יעקב גו׳”) שטייט „ויצו עליו לאמר לא תקח אשה מבנות כנען”\n— דלכאורה: לויטן אויבנדערמאנטן ביאור, אז דער ערשטער „וירא עשו” קומט מסביר זיין עשו׳ס ניט גיין קיין פדן ארם (ווייל די פרטים וואס ער האט געזען אז זיי האבן צו אים קיין שייכות ניט), קומט דאך אויס, אז „ויצו עליו לאמר לא תקח אשה מבנות כנען” האט שייכות צום צווייטן „וירא עשו” וואס קומט מסביר זיין עשו׳ס ניט נעמען אן אשה מבנות כנען —\nדעריבער איז רש״י מפרש אז „וישמע יעקב” איז „מחובר לענין של מעלה” ¹⁷ און טייטשט אויס די פרטים צו וועלכע עס איז מחובר („כי ברך יצחק וגו׳ וכי שלח אותו פדנה ארם”) און שפרינגט אריבער און איז משמיט דעם פרט פון „ויצו גו׳ לא תקח גו׳”: דערמיט איז ער מדגיש אז דער „ויצו גו׳” איז (אין עשו׳ס ראי׳) ניט נוגע צו „וישמע יעקב גו׳ וילך פדנה ארם” (דעם אויספיר פון ערשטן „וירא”), נאר שייך צום צווייטן *17 „וירא עשו” — „כי רעות בנות כנען (וואס דערפאר) והלך גם הוא אל ישמעאל” ¹⁸.\nו. דערמיט איז מובן דער דיוק לשון רש״י, וואס ער ברענגט דעם פרט פון „וכי רעות בנות כנען” ערשט נאך „והלך פדנה ארם”:",[["17","17","עפ״י המבואר בפנים — שכוונת רש״י היא לא (רק) לתרץ ד„וישמע יעקב גו׳” הוא פרט ב„וירא גו׳” — יומתק יותר דיוק לשון רש״י „מחובר לענין של מעלה” (ולא „למקרא של מעלה”) — ע״ד לשון רש״י וארא ו, כח. ואתחנן ד, י. ועוד). *17) אעפ״כ לא כתב כאן רש״י פעם שני׳ וראה — כי סמך על מש״כ בכתוב, כמו שלא העתיק התיבות „בעיני יצחק אביו” אף שרק זה „ראה” עתה (כנ״ל הערה *7)."],["18","18","ואף שעיקר החידוש שבפירש״י הוא בנוגע ה„ויצו גו׳” (שאינו מחובר לשאר הפרטים שב„וירא עשו” הראשון, כי שייך הוא ל„וירא עשו” השני) — מ״מ, כותב רש״י את פירושו על התיבות „וישמע יעקב”, בכדי להדגיש את תוכן החילוק שבין הציווי „לא תקח גו׳” לשאר הפרטים שב„וירא עשו” הראשון, שחלוק הוא בזה שבעיקרו שייך לעשו. וזה שרש״י לא העתיק מהכתוב התיבות „ויצו גו׳ וירא עשו גו׳” (להדגיש שזוהי ראי׳ שני׳) ואינו מרמזו אפילו בתיבת גו׳, — כי הביא העיקר בהתיבות שבפנים פירושו (כרגיל בכ״מ בפרש״י) „וירא עשו כי ברך יצחק וגו׳ וכי — בוא״ו המוסיף, היינו שג״ז ראה, וכאילו כותב ומפרט „וירא כי — שלח אותו פדנה ארם ו(וירא) כי שמע כו׳ ו(וירא) כי רעות בנות כנען” — וא״צ לפרט דראי׳ האחרונה היא מזה דויצו עליו גו׳, כי זהו פשוטו ש״מ (ועפ״ז גם בטלה קושיא ג׳ דסעיף א). ועפ״ז יובן מש״כ רש״י „(וכי שמע יעקב) אל אביו כו׳” — אף שבפירושו כאן מביא רק התחלת הענין, ומשמיט „ואל אמו” — כי „ואל אמו” אינו שייך ל(וירא) עשו. והביאור על אי הליכת עשו לפד״א הוא רק שמיעת יעקב אל אביו, שעפ״ז ברכות אביו הן כבר של יעקב. — ומש״כ גם „והלך לפד״א” הוא להדגיש שהיו בזה ב׳ ענינים: א) שמיעה ליצחק (שלילת בנות כנען, ועוד) ב) והלך לפד״א. ובהאחרון הדגיש רש״י לעיל (שלח) אותו פד״א. וק״ל."]]],[1300151238,"דאס וואס „ויצו גו׳” שטייט בכתוב ביים ערשטן „וירא עשו” איז (דערפאר ווייל בפועל איז עס פארגעקומען פאר וילך פד״א — און) ווייל אף יעקב׳ן האט עס גע׳פועל׳ט, אז „וישמע גו׳ וילך פד״א”; אבער בנוגע עשו׳ן, דאס וואס דער פסוק (לפי פירש״י) וויל מסביר זיין די צוויי פרטים אין הנהגת עשו (כנ״ל ס״ג־ד), געהערט עס צום צווייטן „וירא עשו”.\nז. לויט דעם איז אויך פארשטאנדיק פארוואס רש״י ברענגט אראפ (ניט נאר די פרטים צו וועלכע „וישמע יעקב” איז מחובר, נאר אויך) „וכי שמע יעקב אל אביו והלך פדנה ארם וכי רעות בנות כנען וכו׳”:\nדערמיט איז רש״י אויסן צו מסביר זיין פארוואס „וישמע יעקב” איז (מחו־בר בלויז צו „כי ברך .. וכי שלח כו׳” און) ניט מחובר צו „ויצו גו׳” — ווייל דער ארט פון דעם פרט „ויצו גו׳” (וועלכער ער דריקט אויס (דורך זיין טעם) אין די ווערטער „וכי רעות בנות כנען”) איז (לויט עשו׳ן) ערשט נאך דעם גאנצן סדר פון „וישמע יעקב גו׳ וילך פדנה ארם”, עס געהערט צום „וירא” וואס האט באווירקט הליכת עשו צו ישמעאל.\nאון דעריבער ברענגט רש״י אויך דעם אויספיר „והלך גם הוא אל ישמעאל” ¹⁹, בכדי צו קלאר מאכן, אז „ויצו גו׳” איז (לויטן אינהאלט — „רעות בנות כנען”) — ניט אן ענין וואס איז „מחובר” צו „וישמע יעקב גו׳ וילך פדנה ארם”, נאר — א חלק פון צווייטן „וירא” וואס האט באווירקט עשו׳ס הליכה צו ישמעאל, כנ״ל.\nח. דאס וואס רש״י לאזט אויס דעם „ויצו גו׳” ביים אויסרעכענען די פרטים צו וועלכע „וישמע יעקב” איז מחובר, איז עס ניט בלויז מצד דעם וואס אין דעם „ויצו גו׳” האט עשו געזען אן ענין וועלכער האט ניט קיין חיבור צו די אנדערע פרטים (ווי געזאגט פריער, אז דעם „ויצו גו׳” האט ער געזען ווי אן ענין וואס האט א שייכות אויך צו אים), נאר אויך מצד דעם וואס „וישמע יעקב” האט (אין עשו׳ס ראי׳) קיין חיבור ניט צום „ויצו”: לויט עשו׳ס מיינונג איז יעקב מיט זיין גיין קיין פדן ארם דוקא געווען אויסן (אויספאלגן יצחק׳ס שליחות) בכדי צו באקומען די ברכות, ער האט עס אבער ניט געטאן צוליב דעם ציווי „לא תקח גו׳”.\nאון אויך דער ענין איז א הקדמה צו „וילך עשו אל ישמעאל”, וועלכן רש״י ברענגט אין סיום זיין פירוש — „והלך גם הוא אל ישמעאל”: עשו, מיט זיין גיין צו ישמעאל׳ן, איז געווען אויסן צו ווייזן (ניט נאר אז ער איז מקיים יצחק׳ס רצון, נאר אויך) אז בא עם פעלט ניט לגבי יעקב׳ן ²⁰, ואדרבה: ער איז נאך פיינער פון אים. ווייל ער, עשו, זוכט צו מקיים זיין יצחק׳ס רצון, כאטש ער איז אויף דעם ניט נצטווה געווארן ²¹.\n(משיחת ש״פ תולדות תשכ״ו)",[["19","19","נוסף כי רק לפי פרש״י — בב׳ הסוגים בכתוב — מובן מש״נ „וילך עשו אל ישמעאל”, כנ״ל ס״ג־ד."],["20","20","וכהדגשת רש״י „והלך גם הוא אל ישמעאל”."],["21","21","ועפ״ז מובן עוד טעם על הליכתו לישמעאל דוקא ולא לפדן ארם, כי גם בזה רצה להראות את מעלתו על יעקב, שנושא הוא את בת בנו של אברהם דוקא — ראה לקו״ש ח״ה שם הערה 14."]]],[1300151239,"<h3>ויצא</h3>\nא. בקשר מיט דעם אויבערשטנ׳ס ברכה צו יעקב אבינו „ופרצת ימה וקדמה וצפונה ונגבה\"<sup data-n=\"1\">1</sup>, זאגן חז״ל<sup data-n=\"2\">2</sup>: „כל המענג את השבת נותנין לו נחלה בלי מצרים שנאמר 3 אז תתענג על ה׳ גו׳ והאכלתיך נחלת יעקב וגו׳ לא כאברהם וכו׳ ולא כיצחק וכו׳ אלא כיעקב שכתוב בו ופרצת ימה וקדמה וצפונה ונגבה\".\nעס איז ידוע<sup data-n=\"4\">4</sup>, אז שכר-מצוה איז מדה כנגד מדה — דארף מען פאר־שטיין: מיט וואס איז די מצוה פון (עונג) שבת אין א בחינה פון „בלי מצרים\" וואס דערפאר<sup data-n=\"5\">5</sup> איז אויך איר שכר א „נחלה בלי מצרים\"<sup data-n=\"6\">6</sup>?\nב. אט דעם ענין — אז דער שכר פאר שמירת שבת איז די ברכה „ופרצת\" („נחלה בלי מצרים\") — גע־פינט מען אויך בנוגע צו יעקב׳ן גופא:\nחז״ל זאגן<sup data-n=\"7\">7</sup>: אברהם שאין כתוב בו שמירת שבת ירש את העולם 8 במדה שנאמר 9 קום התהלך בארץ לארכה ולרחבה וגו׳ אבל יעקב שכתוב בו שמירת שבת שנאמר 10 ויחן את פני העיר נכנס עם דמדומי חמה וקבע תחומין מבעוד יום, ירש את העולם 8 שלא במדה שנאמר 1 והי׳ זרעך כעפר הארץ וגו׳ 10*.\nמפרשים 11 זיינען מסביר, אז דער טייטש פון די ווערטער „אברהם שאין כתוב בו שמירת שבת\" איז (ניט אז עס ווערט בכלל ניט דערמאנט אין תורה אז ער האט געהיט מצות שבת — ווארום עס שטייט 12 דאך ביי אברהם׳ען „וישמור משמרתי\" און חז״ל 13 טייטשן: „אפילו הלכות עירובי חצירות הי׳ אברהם יודע\" — נאר) אז עס ווערט ניט געזאגט „בפירוש\" או „בדרך פרט\" וועגן שבת באזונדער, נאר בלויז בכלל, איינגעשלאסן אין אלע מצות פון התורה כולה; משא״כ ביי יעקב׳ן שטייט „בדרך פרט\" אז ער האט געהיט מצות שבת.\nאון וויבאלד אט די מצוה פון שמי־רת שבת ווערט אין דער תורה אונ־טערשטראכן ביי יעקב׳ן (און ניט ביי אברהם׳ען) — איז דאס גופא א באַ־ווייז אז ביי יעקב איז דער קיום מצות שבת געווען אויסגעטיילט פון אנדערע מצות 14; און צוליב דער באזונדערער",[["1","1","פרשתנו כח, יד."],["2","2","שבת קיח, סע״א ואילך."],["3","3","ישעי׳ נח, יד."],["4","4","<a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">ראה סוטה ח, ב</a> וט, ב (במשנה). ובכ״מ. וראה תניא פל״ט (נג, א): שמשכרה נדע מהותה כו׳."],["5","5","ראה ב״י אור״ח ר״ס רמב. חדא״ג מהרש״א שבת שם."],["6","6","ועיין שו״ע אדה״ז שם: נתפרשו בשבת ע״י הנביאים . . ועונג . . וכל המענג את השבת שכרו מפורש בקבלה אז תתענג על ה׳ וגו׳ ובדברי רז״ל שמוחלין כר."],["7","7","ב״ר פי״א, ז. פס״ר ספכ״ג."],["8","8","בפס״ר שם: הארץ."],["9","9","לך יג, יז."],["10","10","וישלח לג, יח. *10) וסיפא דקרא: ופרצת ימה וקדמה וצפנה ונגבה (פי׳ מהרדז״ו). ובפס״ר (וכן בב״ר הוצאת תיאדור) הובא הסיום בפנים."],["11","11","רש״י לב״ר שם. פי׳ מהרדז״ו שם."],["12","12","תולדות כו, ה."],["13","13","ב״ר פס״ד, ד. וש״נ. וראה גם פירש״י עה״פ."],["14","14","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051081\" data-slug=\"likkutei-sichot\" data-id=\"1300051081\">לקו״ש ח״ה ע׳ 69</a>, שי״ל שהמצות שנאמרו בפירוש אצל א׳ מהאבות, קיים מצד ענינו הפרטי, עיי״ש."]]],[1300151240,"מעלה אין זיין קיום מצות שבת האט ער זוכה געווען צו ברכת „ופרצת\".\nאויך דארף מען זאגן, אז דערפון וואס פון אלע פרטים אין מצות שבת וואס יעקב האט מקיים געווען, דער־מאנט די תורה בפירוש דעם פרט פון „קבע תחומין\" — איז פארשטאנדיק, אז כאטש די ברכה „ופרצת\" האט א שייכות צו שמירת שבת אין אלגעמיין (כל׳ חז״ל: „יעקב שכתוב בו שמירת שבת\"), פונדעסטוועגן האט זי א באזונדערע שייכות צום ענין פון תחומין.\nאין אנדערע ווערטער: אט די ספעציעלע מעלה אין קיום מצות שבת, מיט וועלכע יעקב האט זיך אויסגעצייכנט, האט זיך אויסגעדריקט במיוחד אינעם קיום פון דעם ענין התחומין.\nדארף מען פארשטיין: א) אין וואס איז באשטאנען די באזונדערע מעלה פון קיום מצות שבת דורך יעקב לגבי דעם קיום פון דער זעלבער מצוה דורך אברהם, וואס צוליב דעם ווערט דאס דערמאנט נאר ביי יעקב׳ן, און וואס דערפאר האט ער זוכה געווען צו ברכת „ופרצת\"? ב) פארוואס דריקט זיך אויס אט די מעלה דוקא אין דעם ענין פון תחומין 15?\nג. וועט מען עס פארשטיין בהק־דים דאס וואס דער מיטעלער רבי — בעל הגאולה פון יו״ד כסלו 16 — איז מבאר אין זיין מאמר „אתה אחד\" 17, דעם חילוק צווישן דער מצוה פון שבת און אנדערע מצות:\nאנדערע מצות, ווי באלד זייער אופן הקיום איז דורך אן „עבודה ועשי׳\", זיינען דא חילוקים צווישן דעם אופן קיום המצוה דורך צדיקים גדולים און דעם אופן הקיום דורך אנשים פשוטים: צדיקים גדולים, בא זייער הנחת תפילין כנגד הלב ועל הראש, למשל, איז דאך ביי זיי דער לב ו(מוחין שב)ראש באופן נעלה ביותר — משא״כ ביי אנשים פשוטים. און על דרך זה ביי אנדערע מצות.\nדאקעגן די מצוה פון שמירת שבת, וואס באשטייט פון מנוחה און שביתה פון עניני עשי׳, איז דאך אין דעם „ניט\", אין דעם העדר 17* ניטא קיין אונטערשייד צווישן איין איד און א צווייטן. וואַרום הגם די שביתה פון אנשים פשוטים איז פון מלאכה סתם, די שביתה פון עושי מלאכת המשכן — אין מלאכות המשכן, אויב איז דאך די שביתה פון דער עבודת הבירורים של ימות החול 18 — איז עס בלויז א חילוק אין די ענינים פון וועלכע מ׳איז",[["","","*17) אין להקשות דה״ז בכל מצות לא תעשה * — ואינו — כי, לדוגמא, ל״ת דלא יהי׳ לך אלקים אחרים — תוכנה האיסור דע״ז (דשייך לאמונה ודעת כו׳) וכתוצאה מזה בא האיסור דעשיית ע״ז, השתחוואה וכו׳ והשבתת ע״ז כו׳. משא״כ השביתה ומנוחה דשבת — זהו תוכן הציווי („מנוחה שלימה\", שביתה — „מכל מלאכה\") וכמש״נ (יתרו כ, י־יא): לא תעשה כל מלאכה גו׳ כי גו׳ וינח ביום השביעי."],["18","18","ראה ד״ה אתה אחד שם: ובורר אסור בגשמיות וברוחניות כו׳. *) להעיר משייכות איסור תחומין לכל מצות ל״ת — מד״ה להבין שרשי הדברים כו׳ השמים כסאי סוס״ג (אוה״ת בראשית (כרך ג׳) ע׳ 948)."],["15","15","ובפרט לפי׳ ידי משה לב״ר פי״א שם ש„אברהם לא קיים עירובי תחומין ולא עשה המצוה רק במדה כו׳\"."],["16","16","יום אמירת (שיחה) מאמר זה."],["17","17","ס״ע 8 ואילך (נדפס, בקונט׳ בפ״ע — תשכ״ה). מאמרי אדהאמ״צ קונטרסים ס״ע י ואילך."]]],[1300151241,"שובת; אבער אין ענין און עצם השביתה זיינען „הכל שוין ממש\" 19.\nאון דורך דעם וואס ער איז מקיים בשלמות די שביתה ומנוחה ווייל עס איז „בעיניו כאלו כל מלאכתו עשוי׳\" 20, און „משום עונג שבת\" איז ער ניט „מהרהר כלל בעסקיו\" — איז „אין 21 לך עונג גדול מזה\" 22.\nד. דער טעם פארוואס אלע זיינען גלייך אין דער מצוה פון שבת, איז דער מיטעלער רבי מבאר 23, ווייל דער עיקר המצוה פון שבת איז „במנוחת הנפש בעצמותה בבחי׳ יחידה שלמעלה מבחי׳ הגילוי במוח ולב\". ד.ה. די מצוה פון שבת איז פאר־בונדן מיט עצם הנפש, בחי׳ יחידה שבנפש. און דערפאר זיינען ניטא אין דעם קיין חילוקים צווישן איין איד מיטן צווייטן, ווייל אין דער בחי׳ פון יחידה זיינען אלע אידן גלייך, פון דעם גדול שבגדולים ביז דעם פשוט שבפשוטים.\nאון לויט דעם, איז דער מיטעלער רבי מבאר דאס וואס מיר זאגן אין דער תפלה פון מנחת שבת „כי מאתך היא מנוחתם ועל מנוחתם יקדישו את שמך\":\nמנוחת שבת איז „מאתך ממש\", פון עצמותו ומהותו ית׳ 24, און דערפאר איז די מנוחה אויך ביי אידן פאר־בונדן מיט עצם הנפש ממש — בחי׳ יחידה. „ועל מנוחתם יקדישו את שמך\": דער ענין פון מסירת נפש על קידוש השם 25, געפינט זיך אין זיין גאנצקייט ביי אלע אידן בשוה, ווייל דער כח פון מס״נ על קידוש השם קומט פון יחידה שבנפש; און דער־פאר איז „ועל מנוחתם יקדישו כו׳\", וואַרום מנוחת שבת און קידוש השם זיינען ביידע געבונדן מיט יחידה שבנפש.\nה. דאס וואס בחי׳ יחידה שבנפש איז גאנץ ביי יעדער איד, ניט קוק־דיק אויפן מצב פון זיינע כוחות — איז דאס דערפאר, וואס יחידה איז לגמרי אפגעטראגן פון די כוחות פון דעם מענטשן, זי איז העכער פון „גילוי\".\nד.ה. יחידה שבנפש איז העכער אפילו פון די בחי׳ מקיפים פון דער נשמה, וואַרום אויך זיי האבן א בע־רד׳דיגע ווירקונג אויפן מענטשן 26 — ווי ס׳איז מבואר אין חסידות 27 אויפן מאמר רז״ל 28 „אע״ג דאינהו לא חזו",[["19","19","עיין שם ריש ע׳ 9 (מאמרי אדהאמ״צ שם ריש ע׳ יא)."],["20","20","שו״ע אדה״ז סשי״ו סכ״א. וראה בב״י שם שהביא המקור מאגה״ת לר׳ יונה ובאגה״ת שם: וכן אנו אומרים בתפלה מנוחת שלום השקט ובטח מנוחה שלימה שאתה רוצה בה — שבזה קאי אדמרר האמצעי במאמרו."],["21","21","שו״ע שם מהטור (מסמ״ק סר״פ. (רפ״א))."],["22","22","ראה באריכות איך דהעונג דשבת בא מצד השביתה ומנוחה דשבת: סידור קעד, א ואילך. קצט, ג ואילך. המשך תרס״ו ע׳ תקמג ואילך. ועוד."],["23","23","ס״ע 8 (מאמרי אדהאמ״צ שם ס״ע י) ואילך."],["24","24","וראה ד״ה אתה אחד שם (לפנ״ז) בפי׳ „מנוחה שלימה שאתה רוצה בה\" — בחי׳ שלימותא דכולא שאתה מעצמותו רוצה בה כו׳. ובסידור (ר, רע״ב) פי׳ שאתה בעצמות התענוג הפשוט כו׳."],["25","25","בפע״ח, בסי׳ האריז״ל וכו׳: דיכוון למס״נ על קי״ה באמרו יקדישו את שמך."],["26","26","ד״ה אתה אחד שם ע׳ 9 (מאמרי אדהאמ״צ שם ע׳ יא-יב). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670177\" data-slug=\"torat-chaim\" data-id=\"2300670177\">תו״ח לך צה, סע״ג</a> ואילך. אמ״ב שער הציצית פ״ד. פ״ח. פכ״א. סד״ה תקעו עת״ר. ד״ה וזאת התרומה שם. וראה תר״א נה, רע״ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380864\" data-slug=\"likkutei-torah\" data-id=\"4001380864\">לקו״ת תצא לו, ד</a>."],["27","27","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380372\" data-slug=\"likkutei-torah\" data-id=\"4001380372\">לקו״ת במדבר טז, א</a> ואילך. תצא שם. האזינו עא, ד. מקומות שבהערה הקודמת. ועוד."],["28","28","מגילה ג, א. סנהדרין צד, רע״א"]]],[1300151242,"מזלייהו חזי\", אז פון בחי׳ מזל שבנשמה, וואס דאס איז דער מקיף הנשמה, פאלן אריין הרהורי תשובה צום מענטשן אן הכנות וכו׳.\nאבער יחידה שבנפש איז העכער פון צו האבן א גלוי׳דיקע ווירקונג אין מענטשן, ביז עס זעט אויס כאילו זי האט ניט קיין שייכות צו אים.\nדערפאר קען ניט זיין די השראה פון בחי׳ יחידה אין די כלי הגוף: נאכמער: אפילו ניט אין די מקיפים שעל האדם, ווי לבושים און בית 29, וואס אין זיי זיינען שורה די מקיפים של הנשמה — וואַרום ווי באלד זיי האבן א שייכות און אנגעמאסטנקייט צום מענטשן 30\n[ניט בלויז „לבושים\", דער „מקיף הקרוב\", וועלכע נעמען ארום דעם מענטשן און אופן פון זיין צו־געפאסט לויט דער מאס פון דעם וואס טראגט די לבושים, נאר אויך „בית\", וואס איז א „מקיף הרחוק\" איז ווייט פון מענטשן, האט אויך ער א שייכות וערך צום מענטשן]\nקען דארטן ניט זיין די השראה פון יחידה וואס איז מובדל לגמרי פון מענטשן.\nנאר די השראה פון יחידה איז (ווי ס׳איז מבואר דארט אין מאמר<sup data-n=\"31\">31</sup> אין די ד׳ אמות של האדם „הרחוקים בתכלית הריחוק אשר אין ריחוק יותר ממנו\" — און דערפאר קען דארט שורה זיין יחידה שבנפש.\nאון דאס איז אויך דער טעם 32 פארוואס ס׳איז דא דער דין פון ד׳ אמות ביום השבת, ווי חז״ל 33 לערנען פון פסוק 34 „שבו איש תחתיו אל יצא איש ממקומו\" — ווייל אין שבת איז דער גילוי פון בחי׳ יחידה, וואס השר־אתה איז אין די ד׳ אמות של האדם 35.\nו. עפ״י כהנ״ל, איז מובן די שיי־כות פון ברכת „ופרצת\" מיט מצות שבת: „ופרצת\" איז א „נחלה בלי מצרים\", וואס לאמתתו — איז דאס דער מרחב פון עצמותו ומהותו ית׳ וואס האט ניט קיינע הגבלות; און דאס ווערט נמשך דורך שמירת שבת, וואס „מאתך היא מנוחתם\" — „מאתך ממש\" 36.\nאון דאס איז אויך די מעלה אין דער שמירת שבת פון יעקב אויף שמירת שבת פון אברהם:",[["29","29","ראה בארוכה ד״ה מזמור שיר — לקו״ת ברכה צת, ד ואילך (בשינויים — בסה״מ הנחות הר״פ ע׳ עט ואילך). סידור שער התפלה יט, ד ואילך. ובכ״מ."],["30","30","ראה מקומות שבהערה הקודמת. ד״ה אתה אחד שם."],["31","31","שם. אמ״ב שער הק״ש פמ״ב-מג׳. שער הציצית פכ״א. תו״ח בשלח רנה, א. שם ב׳ ואילך. וראה קונט׳ ענינה של תורת החסידות ס״כ, דזהו טעם הדין דד׳ אמות של אדם קונה לו גם שלא מדעתו, עיי״ש."],["32","32","ד״ה אתה אחד ע׳ 10 (מאמרי אדהאמ״צ שם ע׳ יב). אמ״ב שער הק״ש שם."],["33","33","עירובין מח, א. נא, א. ירושלמי שם פ״ד ה״א. מכילתא בשלח טז, כט. פרש״י שם — לענין ד׳ אמות חוץ לתחום. בתיב״ע, פס״ר ורא״ם לבשלח שם — שגם טלטול ד׳ אמות ברה״ר נלמד משם."],["34","34","בשלח שם."],["35","35","להעיר מהקס״ד בספרי זוטא (שלח טו, לב) — דאין לאדם בשבת אלא ד׳ אמות לחוד (גם בתוך התחום)."],["36","36","ראה גם אוה״ת ויצא קצא, ב. ולהעיר מחדא״ג שבהערה 5. *) באמ״ב שם (וכן בתו״ח שם — רנד, סע״ב ואילך), דד׳ אמות הוא דוגמת מקיף דבית, מקיף דמקיף — אבל בד״ה אתה אחד הוא כבפנים."]]],[1300151243,"ביי אברהם איז תורה כולל דעם פרט פון שמירת שבת אינעם קיום פון כללות התורה, ווייל זיין ענין איז ניט געווען דער באווייזן בגילוי די מעלה פון שמירת שבת לגבי אנדערע מצות — גילוי בחי׳ יחידה;\nדוקא ביי יעקב׳ן 37 (קו האמצעי, וואס ער דוקא איז עולה בפנימיות 37* הכתר), וואס ביי עם איז געווען דער ביטול בתכלית 38 — וואס דערפאר שטייט 39 (אלס הקדמה צו ברכת „ופרצת\") „והי׳ זרעך כעפר הארץ\", וואס „עפר\" ווייזט אויף תכלית ה־ביטול 40 — האט ביי אים מאיר געווען בחי׳ יחידה, וואס דריקט זיך אויס בגילוי אין שמירת שבת, כנ״ל בארוכה.\nז. עפ״ז וועט מען אויך פארשטיין פארוואס פון גאנצן כלל פון שמירת שבת ווערט דא אויסגעטיילט דער ענין פון תחומין: דער „תחום\" פון א מענטש איז בדומה צו די ד׳ אמות שלו, וואַרום דער תחום איז דאך „מקומו\" של האדם (דערפאר לערנט מען עס אפ׳ 41 פון פסוק „אל יצא איש ממקומו\"). וואס פון דעם איז מובן, אז דער גילוי בחי׳ יחידה האט א שייכות צו דעם תחומו של האדם.\nאין אנדערע ווערטער: כשם ווי ס׳איז דא די השראה פון בחי׳ יחידה אין די ד׳ אמות של האדם, אזוי י״ל בדרך אפשר איז אויך דא מעין זה איר השראה אין כללות׳דיקן „מקום\" פונעם מענטשן 42 — אין זיין תחום.\nאון דערפאר, הגם דער ענין פון יחידה דריקט זיך אויס אין כללות־דיקן קיום פון מצות שבת, האט עס אבער א ספעציעלע שייכות מיט דעם ענין תחומין — וואס דארטן איז די השראה פון בחי׳ יחידה.\n(ממאמר ד״ה והי׳ זרעך, ש״פ ויצא, יו״ד כסלו תשכ״ב)",[["37","37","ראה סידור שבהערה 24, ד.מנוחה שלימה כו׳ שייך ליעקב דוקא, בחי׳ נחלה בלי מצרים. וראה סידור שם, דזה שייך לסעודה שלישית דשבת דכתיב בי׳ והאכלתיך נחלת יעקב (זח״ב פח, ב) — כי העונג דסעודה שלישית הוא „עצמות התענוג הפשוט\", בחי׳ „נחלה בלי מצרים\" דיעקב. ובהמשך תרס״ו (ר״ע תקמה) שהוא „עצמות התענוג ממש . . בחי׳ עצמות א״ס שלמעלה גם מבחי׳ סוכ״ע כו׳ (סעודה דשחרית)\". *37) <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670142\" data-slug=\"torat-chaim\" data-id=\"2300670142\">תו״ח נח סה, ב</a>. ד״ה פדה בשלום תרע״ג (בהמשך תער״ב ח״א). ועוד."],["38","38","ובד״ה כל המרחם תש״ט (פ״א ואילך) מבואר דהשייכות של נחלה בלי מצרים ליעקב הוא מצד מדתו של יעקב — מדת הרחמים, עיי״ש."],["39","39","ראה במדב״ר פ״ב, יב: ויעקב נתברך בעפר הארץ כו׳. ראה אוה״ת בלק ע׳ תתקיח. תתקכו."],["40","40","ראה ב״ר עה״פ (פס״ט, ה): מה עפר עשוי דיש לכל כו׳."],["41","41","עירובין נא, א. ירושלמי שם. מכילתא שם ומשפטים כא, יג. פרש״י ותיב״ע בשלח שם."],["42","42","ראה אמ״ב ו<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550453\" data-slug=\"torat-chaim\" data-id=\"2300550453\">תו״ח (רנה, רע״א</a>) שם, שגילוי יחידה בד״א הוא לפי שהן מקומו של האדם. ולהעיר שבאמ״ב שם (פמ״ג — משא״כ לפנ״ז בפמ״ב) ותו״ח (<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550698\" data-slug=\"torat-chaim\" data-id=\"2300550698\">שם, ב</a>), וכן בד״ה אתה אחד שם, מובא הכתוב „אל יצא איש ממקומו\" שממנו נלמד תחומין (ולא ד׳ אמות)."]]],[1300151244,"<h3>ויצא ב</h3>\nא. בשייכות צום פסוק (בפרשתנו) 1 „ויקרא את שם המקום ההוא (דעם מקום המקדש) בית א־ל\", זאגט די גמרא 2: „לא כאברהם שכתוב בו הר שנאמר 3 אשר יאמר היום בהר ה' יראה ולא כיצחק שכתוב בו שדה שנאמר 4 ויצא יצחק לשוח בשדה אלא כיעקב שקראו בית שנאמר ויקרא את שם המקום ההוא 5 בית א־ל\" 6 — און דערפאר שטייט אין ישעי' 7 „בית אלקי יעקב\" און ניט „אלקי אברהם\" אדער „אלקי יצחק\" 8 (וכדלקמן).\nזיינען מפרשים 9 מבאר אז די דריי שמות „הר\" „שדה\" און „בית\" זיינען מציין די דריי בתי מקדשות, און דעריבער ווערט דוקא דער מקדש השלישי אנגערופן „בית\" וואס ווייזט אויף א קביעות'דיקן „מקום מיושב\" (ניט „הר\" און „שדה\"), ווייל אין דעם באשטייט דער חידוש און מעלה פון ביהמ\"ק השלישי וואס נאר ער וועט זיין א בנין קבוע ונצחי, ניט ווי בית ראשון ובית שני וואס זיינען חרוב געווארן.\nאון דאס איז אויך דער טעם וואס דוקא „יעקב קראו בית\", ווייל „נחלת יעקב\" איז א „נחלה בלי מצרים\" 10, ווי עס שטייט לפנ\"ז אין דער פרשה *10: „ופרצת ימה וקדמה וצפונה ונגבה\".\nמען דארף אבער פארשטיין: וויבאלד אז דוקא „יעקב קראו בית\", האט, לכאורה, דער ענין פון „בית\" (מקום מיושב וקבוע) זיך געדארפט אויסדריקן אין דער הנהגה און סדר החיים 11 פון יעקב אבינו (ובפרט — בערך צו אברהם ויצחק — שקראו „הר\" ו„שדה\") — ובפועל איז אדרבה, דוקא בא יעקב'ן געפינט מען היפך ההתיישבות והקבי־עות (ובפרט — בערך פון אברהם ויצחק, וואס האבן א גאר גרויסן טייל פון זייערע יארן געלעבט במנוחה ובקביעות, אויף אין ארט) יעקב איז כל ימיו געווען אין אן אופן פון „גר בארץ\", „רעים היו ימי שני חיי\" 12 — פריער זיין אנטלויפן פון עשו'ן ווי דערציילט בתחלת פרשתנו: „ויצא יעקב מבאר שבע\", דערנאך זיין געפינען זיך אין חרן",[["1","1","כח, יט."],["2","2","פסחים פח, א."],["3","3","וירא כב, יד."],["4","4","חיי שרה כד, סג."],["5","5","כ\"ה בגמרא לפנינו. אבל בע\"י „ויקרא למקום א־ל בית א־ל\" — הכי דוישלח (לה, ז)."],["6","6","ובמדרש תהלים מזמור פא (יצחק קראו שדה שנאמר כריח שדה) יעקב קרא אותו פלטין שנאמר (פרשתנו כח, יז) „אין זה כי אם בית אלקים\" (ועד\"ז הוא בילקוט ישעי' רמז שצא (לענין יעקב)). וכן מוכח מספרי ברכה (לג, יב) וב\"ר (פס\"ט, ז): כי אם בית אלקים בנוי ומשוכלל לעת\"ל (משא\"כ באברהם ויצחק שלא נרמז בשם בית בספרי שם וב\"ר פנ\"ו, יו\"ד. ספס\"ה)."],["7","7","ב, ג (דרז\"ל זו הובאה בפרש\"י שם). ובע\"י הוא עה\"פ דמיכה (ד, ב) והלכו גוים גו' ואל בית אלקי יעקב גו'."],["8","8","בגמ': „ולא אלקי אברהם ויצחק אלא כו'\". ובע\"י: „אלקי אברהם אלקי יצחק לא נאמר אלא אלקי יעקב כו'\"."],["9","9","ראה חדא\"ג מהרש\"א ועיון יעקב לפסחים שם. צרור המור בפרשתנו. ובארוכה — אלשיך בפרשתנו. ולתהלים מזמור כד."],["10","10","שבת קיח, ב. *10) כח, יד."],["11","11","ע\"ד מש\"נ (במקדש הא') שאמר דוד (דה\"א כב, ז־יו\"ד): אני הי' עם לבבי לבנות בית גו' ויהי עלי דבר הוי' לאמר גו' הנה בן נולד לך הוא יהי' איש מנוחה גו' הוא יבנה בית לשמי גו'."],["12","12","ויגש מז, ט ובפרש\"י. ולהעיר מפרש\"י לך טו, יג (ד\"ה בארץ)."]]],[1300151245,"„(עם לבן) גרתי\", און נאכדעם אז סוף סוף „ביקש יעקב לישב בשלוה קפץ עליו רוגזו של יוסף\" 13, ביז אז מ'זאגט אז ויחי יעקב איז געווען נאר די זיבעצן יאר (און זיי אויך — זיינען געווען) במצרים *13.\nב. וועט מען דאס פארשטיין בהק־דים דעם ביאור אין דעם אויבנדער־מאנטן פסוק אין ישעי' 14 (אויף וועלכן די גמרא שטעלט זיך) „והלכו עמים רבים ואמרו לכו ונעלה אל הר ה' אל בית אלקי יעקב ויורנו מדרכיו ונלכה באורחותיו וגו'\", וואס לכאורה איז ניט מובן: דער פסוק רעדט טאקע וועגן דעם בית המקדש השלישי 15, וואס ער ווערט אנגערופן „בית\", כנ\"ל — וואס איז אבער נוגע אט די הדגשה (אז דאס איז „בית אלקי יעקב\") אין דעם תוכן הכתוב אז „והלכו עמים רבים ואמרו לכו ונעלה אל הר ה' גו' ויורנו מדרכיו וגו'\" ?\nאויך דארף מען פארשטיין וואס דער פסוק הנ\"ל („והלכו עמים גו' לכו ונעלה גו'\") איז מסיים מיט „כי\" — א נתינת טעם: „כי מציון תצא תורה ודבר ה' מירושלים\" 16: א) אין פשטות מיינט ניט דער פסוק צו זאגן אז די עמים וועלן קומען „אל בית אלקי יעקב\" בכדי זיך מגייר זיין און לערנען תורה ודבר ה' (ווי ס'איז אויך פארשטאנדיק פון דעם המשך בכתוב שלאח\"ז<sup data-n=\"17\">17</sup> — טא ווי אזוי איז „מציון תצא תורה ודבר ה' מירו־שלים\" א סיבה וטעם צו „לכו ונעלה גו'\" ?\nב) וואס איז דער כפל הלשון „מציון תצא תורה ודבר ה' מירושלים\", וואס לכאורה האבן זיי איין כוונה ותוכן: און אזוי אויך דער כפל פריער „ויורנו מדרכיו ונלכה באורחותיו\" ?\nהגם אז, בפשטות, חזר'ט עס איבער דער פסוק צוליב חיזוק והדגשה, נאר ליופי המליצה ענדערט ער דעם לשון: „ירושלים\" אנשטאט „ציון\", און אנ־שטאט „תורה\" „ודבר ה'\", און עד\"ז אין „ויורנו מדרכיו ונלכה באורחותיו\" — וכמבואר במפרשי התנ\"ך בכ\"מ —\nאבער, לאידך גיסא, איז דאך אין תורה, ובפרט אין תושב\"כ, אלעס בתכלית הדיוק ביז אז מ'לערנט אפ כמה הלכות פון א יתור אדער שינוי לשון אין תורה, און אפילו בפשוטו של מקרא, ואפילו בשירה — איז רש\"י 18 מפרש כפל הלשונות וכו' —\nועד\"ז דא איז דאס ניט קיין כפל לשון מיט פונקט דעמזעלבן תוכן, נאר עס רעדט זיך וועגן צווי ענינים: א) ויורנו מדרכיו ב) ונלכה באורחותיו, און אזוי אויך אינעם טעם אויף דעם: א) מציון תצא תורה ב) ודבר ה' מירושלים, וכדלקמן.\nג. דער חילוק צווישן „תורה\" און „דבר ה'\": די גמרא 19 זאגט „דבר ה' זו הלכה\" — דבר הלכה ברורה; משא\"כ „תורה\" (ובפרט ווען עס קומט צוזאמען מיט „דבר ה'\") איז כולל אויך עניני",[["13","13","פרש\"י וישב לז, ב. *13) סדר אלי' רבה פ\"ה. וראה בעה\"ט עה\"פ."],["14","14","ביאור הכתוב ע\"ד הקבלה והחסידות, ראה אוה\"ת ישעי' שם. וש\"נ."],["15","15","ראה מפרשי הכתובים שם."],["16","16","ברד\"ק שם: זה דברי הנביא לא דברי העמים. ובמהר\"י קרא: שזהו דברי העמים."],["17","17","ושפט בין הגוים גו' וכתתו חרבותם גו'. וראה ראב\"ע למיכה שם."],["18","18","שירת הים — בפ' בשלח. ובכ\"מ."],["19","19","שבת קלה, ב (ולהעיר מפרש\"י שם). וראה שם לקמן „דבר ה' ולא ימצאו\" — „שלא ימצאו הלכה ברורה כו'\"."]]],[1300151246,"שקו\"ט 20, קס\"ד וועלכע מען פרעגט אפ וכו' 21.\nובפרטיות יותר:\nמען געפינט בנוגע מנהגים, וואס תורה זאגט אז מ'זאל זיך פירן אין יעדן ארט לויט מנהגי המקום — מקום שנהגו 22 וכו'.\nאויך בעניני הלכה קען זיין א חילוק ממקום למקום ובל' הש\"ס אז באתרי' דרב 23 הלכה כרב און באתרי' דשמואל — הלכה כשמואל. עד\"ז אפילו במחלוקת פון ב\"ש און ב\"ה, איידער ס'איז אפגע'פסק'נט געווארן דהלכה כב\"ה 24, איז יעדערער פון זיי האט זיך געפירט לויט זיין שיטה.\nנאך מער: אפילו נאכדעם ווי מ'האט גע'פסק'נט די הלכה ווי ב\"ה ביז אז „ב\"ש במקום ב\"ה אינה משנה\" 25 — איז „אלו ואלו דברי אלקים חיים\" 26. וח\"ו וח\"ו לומר אז דעת ב\"ש איז ניט קיין חלק פון תורה — וואס דעמאלט האט ער ניט קיין שייכות צו גאנץ תורה 27 (וע\"ד פסק הרמב\"ם 28 וועגן דעם וואס זאגט אויף אן ענין פון תושבע\"פ אז דאס איז ניט מעם ה', ח\"ו).\nויתרה מזו אפילו א סלקא דעתך און א קשיא אין גמרא — אויך זיי זיינען א חלק פון תורה שניתנה מפי הגבורה 29. און אפילו ווען איינער לערנט נאר דעם סלקא דעתך און די קשיא פון תורה (ניט לערנענדיק בשעה זו די מסקנא און דעם תירוץ) איז ער מחוייב בברכת התורה און ער זאגט אויף דעם סלקא דעתך און קשיא — אזוי אויך אויף דער דיעה שאין הלכה כמותה — „ונתן לנו את תורתו\".\nד. הגם אז אלע דיעות מחולקות און פלוגתות אין גמרא וכו' און אזוי אויך די ענינים פון קס\"ד וקושיות שבתורה, זיינען א חלק פון תורה, „אלו ואלו דברי אלקים חיים\" — ווערט די הלכה גע־פסק'נט נאר ווי איין דיעה, ובלשון הגמרא 30 „והוי' עמו 31 שהלכה כמותו\", הלכה און דעות חלוקות זיינען בדוגמת החילוק פון שם „הוי'\" און שם „(אלו ואלו דברי) אלקים חיים\", וואס ביידע זיינען פון די ז' שמות שאינן נמחקין 32.\nאון ס'איז ידוע דער ביאור בזה 33: „אלקים\" — אויך „אלקים חיים\" וואס איז העכער פון „אלקים\" סתם 34 — איז לשון רבים 35, וואס דאס ווייזט אויף א ריבוי בחי' און התחלקות, כביכול — דערפאר איז עס אזוי אויך אין תורה, אז",[["20","20","אע\"פ שבכל ענין בתורה, ואפילו בסיפורי התורה — ישנה הוראה, שלכן תורה — לשון הוראה (זח\"ג נג, ב. רד\"ק הובא בגו\"א ר\"פ בראשית). וראה לקמן בפנים."],["21","21","להעיר מעניני התורה עליהם נאמר „דרוש וקבל שכר כו' יגדיל תורה ויאדיר\" (חולין סו, ב. ישעי' מב, כא)."],["22","22","פסחים פ\"ד. ב\"ב בתחלתה. ועוד."],["23","23","ראה שבת יט, ב."],["24","24","או לר' יהושע דלא משגח בבת קול, עירובין ו, ב ואילך."],["25","25","ברכות לו, ב. וש\"נ."],["26","26","עירובין יג, ב."],["27","27","וכדמוכח גם מזה שלעתיד ההלכה כב\"ש (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380531\" data-slug=\"likkutei-torah\" data-id=\"4001380531\">לקו\"ת קרח נד, סע\"ב</a> ואילך. וש\"נ)."],["28","28","הלכות תשובה פ\"ג ה\"ח (וראה כס\"מ שם). וראה פירוש המשניות סנהדרין פ' חלק יסוד הח'."],["29","29","ראה לקוטי לוי יצחק אגרות ע' רסו. וראה לעיל ע' 94 ובהנסמן שם."],["30","30","סנהדרין צג, ב."],["31","31","ש\"א טז, יח."],["32","32","שבועות לה, א."],["33","33","ראה בארוכה אוה\"ת יתרו ע' תתא ואילך. ד\"ה וידבר אלקים תרכ\"ז. המשך תרס\"ו ע' תלא ואילך. ועוד."],["34","34","ראה פרדס ש' ערכי הכינויים בערכו. מאו\"א בערכו. שערי אורה (להר\"י גיקטליא) ש\"ח."],["35","35","ראה גם רש\"י וירא כ, יג. וישלח לה, ז."]]],[1300151247,"מצד „אלקים חיים\" איז שייך דער ענין ההתחלקות פון „אלו ואלו\"; אבער „הוי'\" איז שם המפורש 36 שם העצם 37 שם המיוחד 38, למעלה מהתחלקות, וואס דעריבער ווערט פון שם הוי' נמשך דער ענין פון הלכה פסוקה אין תורה — דוקא איין דיעה.\nה. עד\"ז איז אויך דער חילוק צווישן „תורה\" און „דבר הוי'\":\nתורה איז כולל אויך די סברות און די דיעות שאין הלכה כמותן (ווי אויך די הוראות וואס מ'קען פון זיי אפלערנען במק\"א); משא\"כ „דבר הוי'\" (וואס איז ווי די גמרא זאגט: „דבר הוי'\") — זו הלכה\".\nאון דאס איז כוונת הכתוב „מציון תצא תורה ודבר הוי' מירושלים\" — דער ענין פון „תורה\" איז פארבונדן מיט „ציון\", און „דבר הוי'\" — מיט „ירושלים\":\nס'איז ידוע 39 אז דער תוכן ומהות פון יעדער זאך דריקט זיך אויס אין איר נאמען: אזוי איז עס אויך בנדו\"ד: די נעמען „ציון\" און „ירושלים\" 40 — הגם ביידע באצייכענען די זעלבע שטאט 41 — ווייזט יעדער נאמען אויף א באזונדער ענין און מעלה אין דער שטאט — דער נאמען „ציון\" (לשון סימן 42, וכמו „הציבי לך ציונים\"<sup data-n=\"43\">43</sup> דריקט אויס דעם ענין וואס זי איז (נאר) א „סימן\" פון אן עילוי רוחני, וכידוע 44 אז „ירושלים של מטה\" איז מכוונת „כנגד ירושלים של מעלה\": דער נאמען „ירושלים\" ווייזט אויף די מעלה פון יראת שמים וואס איז דא אין איר, ווי עס שטייט אין מדרש 45 ונקרא ירושלים על שם יראה ועל שם שלם, ד.ה. אז אין „ירושלים\" איז די בחינה יראה בשלימות 46.\nאון ווי מ'איז מסביר 47 דעם פסוק 48 „למען תלמד ליראה את ה\"א כל הימים\" וואס שטייט ביי מעשר שני, אז דאס וואס מען האט געזען „מקום שכינה וכהנים בדוכנם ולוים בעבודתם וישראל במעמדם\", האט עס געלערנט און געבראכט „ליראה את ה\"א\".\nו. די צווי בחינות הנ\"ל — „ציון\" און „ירושלים\" — זיינען דא אויך אין די",[["36","36","סוטה לח, א. סנהדרין ס, א. רמב\"ם הלכות יסודי התורה פ\"ו ה\"ב."],["37","37","כ\"מ הל' ע\"ז פ\"ב ה\"ז. פרדס ש\"ט. מו\"נ ח\"א פס\"א ואילך. עיקרים מאמר ב' פכ\"ח."],["38","38","סוטה שם. סנהדרין שם. והוא המייחד כו' וכל השמות כלולים בו (בארוכה בכהנ\"ל — פרדס שם. שערי אורה (הנ\"ל) ש\"ה. תו\"א ס\"פ נח. אוה\"ת יתרו ע' תתלה ואילך. ועוד)."],["39","39","שער היחוד והאמונה פ\"א. ובכ\"מ. וראה אור\"ת להה\"מ ס\"פ בראשית."],["40","40","ציון וירושלים ע\"ד הקבלה והחסידות — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380344\" data-slug=\"likkutei-torah\" data-id=\"4001380344\">לקו\"ת במדבר ט, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380715\" data-slug=\"likkutei-torah\" data-id=\"4001380715\">דברים א, ב</a> ואילך. רשימות הצ\"צ לתהלים (יהל אור) קמז, יב. וש\"נ. ד\"ה שבחי ירושלים תרכ\"ז. לקוו\"צ (לזהר ח\"ב ע' רפד. ליקוטים על מארז\"ל ע' קעא. ועוד). ויש לתווך עם המבואר בפנים, וראה לקמן הערה 55."],["41","41","להעיר מפרש\"י יומא עז, סע\"ב."],["42","42","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380715\" data-slug=\"likkutei-torah\" data-id=\"4001380715\">לקו\"ת דברים א, סע\"ב</a>."],["43","43","ירמי' לא, כ. הובא בד\"ה ציון במשפט תפדה לאדה\"ז (קה\"ת תשל\"ז, תשל\"ג) ע' 14 לענין ד„ציון הוא לשון סימן\" (וגם הובא שם אנא סימנא כו' — זח\"א רכה, א (שהובא גם בהמאמר בלקו\"ת שם))."],["44","44","תנחומא ר\"פ פקודי. זח\"א קפג, ב."],["45","45","ב\"ר פנ\"ו, יו\"ד. תוד\"ה הר (תענית טז, א)."],["46","46","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380960\" data-slug=\"likkutei-torah\" data-id=\"4001380960\">לקו\"ת ר\"ה ס, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381155\" data-slug=\"likkutei-torah\" data-id=\"4001381155\">שה\"ש ו, ג</a>. ובכ\"מ."],["47","47","תוד\"ה כי מציון ב\"ב כא, א (ושם: כדדרשינן בספרי * למען תלמד ליראה וגו' (ראה יד, כג) גדול מע\"ש שמביא לידי תלמוד לפי שהוי' כו'). רשב\"ם ראה שם. ולהעיר שבתוס' שם מפרש כן מ\"ש בגמ' „מושיבין מלמדי תינוקות בירושלים מאי דריש כי מציון תצא תורה\". וראה לקמן הערה 53."],["48","48","ראה שם. *) בספרי שנדפס מכת\"י (נ. י. תשכ\"ט): מגיד שהמעשר מביא את האדם לידי ת\"ת. וכן הוא ביל\"ש שם. ובספרי בדפוס שלפנינו ליתא."]]],[1300151248,"דרגות העבודה פון אידן 49. ווארום כשם ווי (דער אויבערשטער) „בחר בארץ ישראל\" אזוי אויך „בחר לחלקו ישראל\" 50 — זיינען זיי בדומה זה לזה: אזוי ווי אין ירושלים (דער „מובחר\" שבארץ ישראל) זיינען פאראן די צווי בחינות „ציון\" און „ירושלים\", עד\"ז זיינען אויך ביי אידן, בעבודתם, פאראן די צווי בחינות:\n„ירושלים\" — „על שם יראה ועל שם שלם\" — איז, אין עבודה, די מדריגה פון תכלית ושלימות היראה והביטול: זיין הארעווען און אויסאיידלען זיך אין אן אופן אז זיין גאנצע מציאות איז יראה — ביטול בתכלית.\n„ציון\", מלשון סימן, איז דער אופן העבודה פון א אידן דורך וועלכן ער דערגרייכט צו ווערן א ציון וסימן פון די ענינים נעלים אין אלקות שלמעלה: ער איז נאך אינעם ציור פון א מציאות און ניט בתכלית הביטול, אבער זיין מציאות איז אזוי אויסגעארבעט (און אויס־געאיידלט) אז זי איז א סימן אויף די ענינים שלמעלה.\nאון וויבאלד אז ער איז א מציאות, און במצבו זה — אויך בנוגע צו זיין שכל — הארעוועט ער צו פארשטיין תורה, „נעמט\" ער תורה אויך לויט זיינע כחות ההבנה וההשגה.\nאון דערפאר איז „מציון (איז) תצא תורה\", אז „סימן\" (א „ציון\" בעת'ן זיין א גדר פון עפעס א מציאות) איז פאר־בונדן מיט בחי' „תורה\", וואס אין איר איז שייך ריבוי והתחלקות (כנ\"ל סעיף ד'); היות אז לימוד והשגה בתורה איז לויט זיין מציאות, איז עס דאך במילא אין אן אופן פון ריבוי והתחלקות וכו', כל אחד כפי השגתו וכפי שרש נשמתו למעלה 51.\nאבער פונדעסטוועגן, וויבאלד אז זיין מציאות איז א ציון וסימן אויף די ענינים שלמעלה, דעריבער זיינע סברות וכו' חלקים פון תורת אמת און „אלו ואלו דברי אלקים חיים\", ד.ה. אז די סברות רבות ווערן נשתלשל — און זיינען דערפאר א ציון וסימן — פון ריבוי הבחינות וואס זיינען דא, כביכול, אין „אלקים חיים\" (לשון רבים).\nאבער 52 דאס אלץ איז נאר בנוגע השגת התורה, וואס איז ניט פארבונדן מיט הלכה למעשה, אויף דעם איז מספיק בחי' „ציון\" און עס איז ניט א הכרח אנקומען צו בחי' „ירושלים\" 53.\nבשעת עס קומט אבער צו „(דבר הוי' זו) הלכה\" — אויף דעם איז ניט מספיק בחי' „ציון\" 54, מען דארף האבן שלימות",[["49","49","ראה ירושלמי תענית פ\"ד סה\"ב. מגילה פ\"ג סה\"ו (לענין ציון). ובהמובא בהערה 46 (בנות ירושלים). וראה בהמצוין בהערה 40."],["50","50","תנחומא ראה ח."],["51","51","להעיר מבאוה\"ז וישלח (כ, ב)."],["52","52","להעיר שישנו גם במדרי' נעלית — „אנא סימנא בעלמא\" (בחי' ציון) שאמר רשב\"י, אף שזהו מצד עוצם ביטולו שאינו בבחי' מציאות לעצמו כלל (המשך תרס\"ו ע' קנט, ועוד), הרי מצינו יתירה מזו (ראה ד\"ה ציון במשפט תפדה תשל\"ז פ\"ז (סה\"מ — מלוקט ח\"א ע' קנו) ובהערה 58 שם. וראה תר\"ש ע' 12 ואילך). וראה המשך תרס\"ו שם החילוק בין נשמות דמ\"ה (בחי' ד\"א) דעיקר עבודתם הוא בבחי' ביטול מצד נשמתם דוקא בהשגה והתבוננות בבחי' דביקות אמיתי באוא\"ס בבחי' ביטול במציאות ממש, ונשמות דב\"ן בחי' מלכות (כמו נשמת דוד ואלי') שעבודתם בביטול היש. וראה לקמן הערה 55, 87."],["53","53","להעיר שבב\"ב שם „תקינו שיהו מושיבין מלמדי תינוקות (הלימוד דתורה ולא הלכה) בירושלים\" הובא רק תחילת הכתוב „כי מציון תצא תורה\", ותו לא. אבל בע\"י הובא גם סיום הכתוב „ודבר ה' מירושלים\"."],["54","54","וע\"ד החילוק בין תורה ומצות (ראה יהל אור שם ע' 575 בהגה\"ה „ועי' כהג\"ג כו'\"). וראה בכ\"ז"]]],[1300151249,"היראה — „ודבר הוי' 55 מירושלים\"; וכמבואר בהמשך תרס\"ו 56, אז פסק'נען א הלכה באמת לאמיתו קען מען נאר דורך שלימות היראה: ער האט מורא טאמער חלילה וועט זיין פסק הלכה ניט זיין מכוון כפי רצון העליון, ועד — היפך, ר\"ל, פון רצה\"ע.\n[אפילו ווען ס'האנדלט זיך וועגן א דקדוק קל של דברי סופרים, און אפילו „בלויז\" מה שתלמיד ותיק מחדש — וויבאלד אז דא רעדט זיך וועגן ה„נאמר למשה מסיני\", וועגן רצון העליון, איז דאך קיין חילוק ניט צי ס'איז א זאך וואס דער רצה\"ע האט געוואלט אז עס זאל זיין דאורייתא אדער א דרבנן 57 — ער האט מורא אז זיין פסק הלכה למעשה (וואס דורך דעם וועט א איד טאן א מעשה בפועל) זאל זיין ח\"ו היפך רצון העליון]\nאט די יראה רופט ביי אים ארויס א נאך גרעסערע און שטארקערע יגיעה און העמקה אין תורה, ביז צו מכוון זיין די הלכה באמת לאמיתתה.\nאון דאס איז דער פירוש פון „ודבר הוי' מירושלים\" — שלימות היראה: בכדי צו מכוון זיין די הלכה לאמיתתה איז ניט מספיק יראה סתם, ווי יראת העונש אדער אפילו א העכערע דרגא ביראה; דא איז נויטיק די שלימות'דיקע יראה (שמא לא יכוון לרצון העליון), וואס ברענגט די שלימות'דיקע מסקנה פון הלכה באמת לאמיתו.\nז. עפ\"י הנ\"ל וועט מען פארשטיין נאך אן ענין: דער סדר הפסוקים פון „אתה הראת\", וואס מ'זאגט פאר הקפות, פארענדיקט זיך מיט „כי מציון תצא תורה ודבר הוי' מירושלים\" — וואס לכאורה אינו מובן: בשלמא דאס וואס מ'זאגט נאר דעם חלק פון פסוק אין ישעי' (ומיכה) און ניט דעם גאנצן פסוק, קען מען מסביר זיין בפשטות — ווייל נאר דער חלק פון פסוק, זיין תוכן, איז נוגע צו (די פסוקים פאר) הקפות; עס איז אבער ניט מובן פארוואס מען זאגט אויך דעם וואָרט „כי\" — וואס פאר־בינדט דעם סיום הפסוק, אלס נתינת טעם, מיט דעם אנהויב פסוק — וויבאלד תחילת הפסוק זאגט מען ניט (איז דא ניט נוגע כנ\"ל) ?\nמוז מען זאגן אז דער (נתינת טעם פון) וואָרט „כי\" ביי די פסוקים פון אתה",[["","","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161449\" data-slug=\"likkutei-sichot\" data-id=\"1300161449\">לקו\"ש חט\"ז ע' 436</a> (ס\"ד), וע' 440. ובכ\"מ. ובתורה גופא הוא החילוק בין לימוד התורה (בכלל) והלכה: הביטול שבלימוד התורה הוא בעיקר (ביטול ישות שכלו) בכדי שיבין ויתייחד עם שכל התורה. ובכדי לכוון להלכה הוא מבטל שכלו מכל וכל בהנחת עצמותו לגמרי, ואז נרגש אצלו רצה\"ע שלמעלה מהשכל. ראה בארוכה בהנסמן בהערה 33."],["55","55","בהנסמן בהערה 40 מבואר דבחי' ציון הוא פנימיות המל' (פנימיות הלב) וירושלים חיצוניות המל'. וביהל אור שם שלכן בציון נאמר שם אלקים, ובירושלים שם הוי', דהעלאת מ\"ן דבחי' ציון הוא לבחי' אלקים, בינה, וירושלים הוא לבחי' חכמה שהוא שם הוי'. וע\"פ המבואר בהערה שלפנ\"ז מובנת השייכות להמבואר בפנים: דמצד זה שהוא בחי' ציון וסימן שלמעלה, שמצד ביטולו מיוחד עם אלקות הרי\"ז רק עם בחי' „אלקים\" אלקות שבא בהתלבשות ולפ\"ע העולמות, ומצד בחי' ירושלים, ביטול והנחת עצמותו לגמרי, הרי נרגש ומתגלה בו בחי' „הוי'\" שלמעלה מהשתל' לגמרי. ולהעיר דבכל השמות א־ל אלקים כו' נשתמש בהם גם בל' חול כו' משא\"כ שם הוי' לא נמצא שישתמש בו בל' חול כו' (פרדס ש\"ט פ\"א הובא ונתבאר בהמשך תרס\"ו ס\"ע תעו ואילך)."],["56","56","ע' תו. וע' תכ ואילך."],["57","57","דהרי ב„עבד פשוט\" (ראה ד\"ה ומקנה רב תרס\"ו והמאמרים שלאח\"ז) אין אצלו חילוקים בהמצות, וזה שבמצוה דאורייתא הוא מחמיר בספיקו ובמצוה דרבנן הוא מקיל (ועוד חילוקים כיו\"ב) אין זה לפי שמחלק בין המצות, כ\"א מפני שחילוק זה הוא רצון העליון."]]],[1300151250,"הראת באצית זיך (ניט צום אנהויב פון דעם פסוק, אין ישעי' (ומיכה) נאר) צום פסוק 58 וואס מ'זאגט פריער פאר הקפות „מלכותך מלכות כל עולמים וממשלתך בכל דור ודור\",\n[ס'איז קיין סתירה ניט וואס במקורו, אין ישעי' (ומיכה), איז „מציון תצא תורה\" א טעם אויף תחילת הכתוב שם (וואס איז, לכאורה, ניט דער ענין פון „מלכותך מלכות גו'\") — ווארום, מען געפינט בכמה ענינים אז פון דעמזעלבן טעם קומען כמה תוצאות 59].\nאבער צוזאמען דערמיט דארף מען זאגן, אז וויבאלד דער זעלבער ענין „מציון תצא תורה גו'\" איז א טעם אויף צווי זאכן — מוזן די צווי האבן א שייכות צווישן זיך (בתוכנם כדלקמן).\nח. בפשטות איז משמע, אז די צווי לשונות, „מלכותך מלכות כל עולמים\" און „וממשלתך בכל דור ודור\", אנט־האלטן אין זיך דעם זעלבן תוכן און ווערן איבערגע'חזר'ט נאר צוליב הדגשה וחיזוק (ובשינויי לשון — ליופי המליצה), אבער עפ\"י הנ\"ל (ס\"ב) איז מובן, אז לויטן פי' פנימי פון דעם פסוק (ע\"ד ווי אין פסוק „כי מציון גו' מירושלים\") זיינען דאס (אויך) צווי באזונדערע ענינים:\nדער אונטערשייד צווישן „מלוכה\" און „ממשלה\" 60: מלוכה ווערט אנגענומען ברצון ווי דער לשון „ומלכותו ברצון קבלו כו'\": ממשלה איז אן אופן פון שליטה (וואס ווערט ארויפגע־צוואונגען) בע\"כ.\nדי צווי אופנים — „מלוכה\" און „ממשלה\" — קומען מצד די צווי ענינים פון „מציון תצא תורה\" און „ודבר ה' מירושלים\", און בעבודת כל אחד ואחת (און אזוי אויך אין דער בחינה פון ציון וירושלים בכלל, כדלקמן):\nמצד דער בחינה פון „תורה\", וואס דאס איז דער לימוד התורה לויט זיין הבנה והשגה כנ\"ל, איז דער אופן הלימוד מיט א חיות און געשמאק; און גדול לימוד שמביא לידי מעשה — איז אויך כללות קיום המצות שלו מתוך רצון ועונג. ד.ה. אז מצד בחי' „ציון\" און „תורה\" איז דער קבלת עול מלכות שמים אין אן אופן פון „מלכותך מלכות כל עולמים\" — ברצון.\nבשעת עס קומט אבער צו „דבר ה'\" צו פסק'נען א הלכה למעשה און דער־נאך מקיים זיין דאס אין פועל ממש, איז אויף דעם ניט גענוג די הבנה והשגה לויט זיין שכל (אין אן אופן פון „ציון\"), נאר אדרבה: מיט זיין שכל המורגש קען ער אמאל קומען צו א מסקנא וואס איז ניט כהלכה באמתו, און דוקא דורך בחי' „ירושלים\" — שלימות היראה והביטול — ער איז זיך מכריח און איז זיך מבטל מכל וכל 61, דעמאלט קומט ער צו און דערהערט דעם רצון העליון, בחי' הוי', און ער איז מכוון הלכה באמת לאמיתתה (און טוט אזוי למעשה — אפילו ווען עס איז היפך שכלו).",[["58","58","תהלים קמה, יג."],["59","59","ולהעיר שמצינו שמשתמשים בלשון הכתוב לכוונה אחרת — ראה משנה פאה (פ\"ב מ\"ב) „וכל ההרים אשר במעדר יעדרון\", והוא לשון הכתוב בישעי' ז, כה. וראה לקו\"ש ח\"ד ע' 1139 הערה 2."],["60","60","לקו\"ת דברים א, ריש ע\"ב. ר\"ה נו, סע\"ב ואילך. ד\"ה אשרי יושבי ביתך לאדה\"ז (קה\"ת תשל\"א) עה\"פ (מאמרי אדה\"ז תק\"ע — ע' קמ\"מא). סידור עה\"פ (נג, ג ואילך). מילואים ליהל אור עה\"פ (ע' תרפה ואילך). ובכ\"מ."],["61","61","ולכן דוד זכה שכיון להלכה מצד תכלית השפלות והביטול שלו (דבחי' מלכות), וכן ב\"ה מכיון שהיו נוחים ועלובין, אף שב\"ש מחדדי טפי — ראה בארוכה בכהנ\"ל בהמצויין בהערה 33. המשך הנ\"ל ע' תלט ואילך."]]],[1300151251,"ד.ה. אז דער לימוד התורה פון „דבר הוי'\", פון הלכה למעשה און במילא אויך דער קיום המצות בכלל כהלכתן, איז דאס דורך דער כפי' וביטול פון זיין מציאות — דוגמת ענין הממשלה 62.\nט. וויבאלד אז אידן בכלל (און יעדער איד בפרט) דארפן זיך משתדל זיין צו דערגרייכן ניט נאר זייער אייגענע שלימות, נאר אויך בריינגען די גאנצע וועלט לשלימותה — און אויך, ווי דער רמב\"ם 63 פסק'נט: „צוה משה רבנו מפי הגבורה לכוף את כל באי עולם לקבל מצות שנצטוו בני נח\", און דער אופן הקיום דארף זיין „שיקבל אותן ויעשה אותן מפני שצוה בהן הקב\"ה בתורה והודיענו ע\"י משה רבינו\" — איז ניט מספיק דאס וואס ביי אידן זיינען דא „תורה\" און „דבר הוי'\" אין זייערע צווי בחינות, נאר עס דארף זיין „מציון תצא תורה ודבר ה' (דארף ארויסגיין) מירושלים\":\nדורך „ציון תצא תורה\", פועל'ט מען אויך ביי „עמים רבים\" די תנועה פון „לכו גו' ויורנו מדרכיו\" דעם ענין הלימוד *63 אין די ענינים פון ז' מצות שלהם — וואס כאטש דאס איז אויך אן ענין פון ביטול, איז דאך דאס פאר־בונדן מיט זייער מציאות והבנה והשגה:\nאון דורך דעם וואס „דבר ה'\" קומט ארויס „מירושלים\" פועל'ט מען ביי זיי דעם „ונלכה באורחותיו\" 64 — די הליכה (אויך מל' הלכה) בפועל וואס דאס איז א תנועה פון ביטול בתכלית — פאלגן און טאן די ז' מצות ווי עס איז ע\"פ „דבר ה'\".\nאון אזוי איז אויך בנוגע די צווי ענינים פון מלוכה וממשלה, אז זייער טעם וסיבה („כי\") זיינען די צווי אופנים מ„ציון\" „מירושלים\": דורך „מציון תצא תורה\" טוט זיך אויף דער ענין פון „מלכותך מלכות כל עולמים\", און אויך וועלט („כל עולמים\") איז מקבל דעם ענין המלוכה ברצון; און דורך „דבר ה' מירושלים\", שלימות היראה והביטול ווערט אויפגעטאן דער ענין פון „וממשלתך בכל דור ודור\" — אז וועלט („בכל דור ודור\") שטייט אין דער תנועה פון תכלית הביטול מצד „ממשלה\" 65.\nיוד. יעדער ענין איז פאראן ווי ער קומט באופן כללי און ווי ער דריקט זיך אויס בפרטיות. אזוי איז עס אויך בנדו\"ד: אע\"פ אז בכללות רעדט דער פסוק אין ישעי' וועגן דעם זמן דלעתיד, בביהמ\"ק השלישי וואס דעמאלט וועט זיין דער „מציון תצא תורה ודבר ה' מירושלים\" בתכלית השלימות ובמילא — אויך די שלימות פון מלכותך מלכות גו' ודור', אבער בפרטיות זיינען די צווי ענינים (אבל — ניט בשלימותם) איינגע־שטעלט אין באזונדערע זמנים:\nכשם ווי ס'איז דא אין דעם א חילוק צווישן זמן הבית און זמן הגלות 66: בזמן הבית האט מאיר געווען אלקות בגילוי, ובמילא איז דעמאלט די עבודה פון אידן געווען (בעיקר) אין דער תנועה פון",[["62","62","ראה לקמן הערה 65."],["63","63","הל' מלכים ספ\"ח. *63) מצו\"ד ומצו\"ץ לישעי' עה\"פ."],["64","64","ע\"ד הב' במש\"נ לך לך מארצך (ל' רצון) גו'."],["65","65","בהנסמן בהערה 60, דבחי' ממשלה היא למטה מבחי' מלוכה. אבל עפ\"י המובא בהערה 55 במעלת הביטול דבחי' ירושלים על בחי' ציון, מובן גם בנדו\"ד, דשרש הממשלה הוא ביטול למעלה מטו\"ד — ראה סידור שם, ויהל אור שם, דמלוכה היא מבחי' פנימיות המלכות (כחב\"ד חג\"ת דמלכות) וממשלה מבחי' נה\"י דמלכות) — בלי טעם ורצון. וכידוע בענין היראה (ראה בהנסמן לקמן הערה 82). וראה המשך תרס\"ו ע' תמ."],["66","66","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381108\" data-slug=\"likkutei-torah\" data-id=\"4001381108\">לקו\"ת ברכה צה, ב</a>. סה\"מ אידיש בתחילתו. ד\"ה קול דודי תש\"ט פ\"ב ואילך."]]],[1300151252,"אהבה ורצון, וואס האט זיי געגעבן א געשמאק אין דער עבודה — משא\"כ בזמן הגלות, ווען אלקות איז ניט מאיר בגלוי, איז דעמאלט די עבודה (בעיקר) מצד קב\"ע — יראה וביטול 67:\nאזוי איז אויך אין דער עבודה פון זמן הבית גופא פאראן אן אונטערשייד צווישן דעם זמן פון בית ראשון און דעם זמן פון בית שני 68:\nדער בית ראשון איז געבויט געווארן דורך שלמה המלך אין דער צייט ווען „קיימא סיהרא באשלמותא\" 69 — שלימות הגילוי דאלקות פון בחי' בינה „עלמא דחירו\", וואס דערפאר זיינען אידן דעמאלט געווען במצב חירות משעבוד הגויים — איז דער גילוי פון מקדש אין וועלט געווען באופן נעלה און אויך די עבודה פון אידן איז דאן געווען אין אן אופן פון גילוי, פון אהבה, וואס דאס איז די בחי' פון „ציון\" וואס ממנה „תצא תורה\", כנ\"ל; אבער אין זמן פון בית שני, וואס דעמאלט איז ניט געווען דער גילוי אזא אופן, ווי די גמרא זאגט 70: אכבדה 71 חסר ה' — ה' דברים חסרו בבית שני ארון וכפורת כו', און די אידן זיינען געווען אונטער דער שליטה פון מלכי האומות — איז די עבודה דעמאלט געווען (בעיקר) מיט יראה וביטול — בחי' „ירושלים\" 72, כנ\"ל.\nעד\"ז איז אויך דער חילוק צווישן „מלכותך מלכות כל עולמים\" און „וממשלתך בכל דור ודור\", ווי עס האט זיך אויסגעדריקט אין דעם אונטער־שייד צווישן די צווי זמנים 73: אין זמן פון בית ראשון איז דער סדר ההנהגה געווען בבחי' „מלוכה\" — סיי בנוגע אידן, אז זייער עבודה איז געווען אינעם אופן פון „מלכותו ברצון קבלו\", און סיי אין וועלט בכלל איז עס געווען א זמן פון מנוחה ושלוה 74:\nבבית שני איז געווען (בעיקר) דער אופן פון „ממשלה\": סיי בעבודת ישראל — עבודה ביראה, דורך כפי' והכרח; און אזוי אויך אין וועלט איז געווען א זמן פון מלחמות, און עמים רבים האבן שולט געווען אויף אידן, ובמילא האט מען געדארפט אנקומען אז עס זאל זיך אנהערן ממשלתו של הקב\"ה 75.",[["67","67","בלקו\"ת שם מבואר שבזמן הבית כשהי' גילוי אלקות היתה „ההשתחוואה בבחי' פנימית הוא בחי' בטל רצונך מפני רצונו שאין לו רצון וחפץ אחר\", משא\"כ בזמן הגלות ההשתחוואה היא „בבחי' חיצוניות שמכניע את הגוף שלא ימרוד\". אבל ראה בהנסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091073\" data-slug=\"likkutei-sichot\" data-id=\"1300091073\">לקו\"ש ח\"ט ע' 73</a> ואילך, דנפק\"מ בין „מהות\" הביטול ו„מדת\" הביטול ובזמן הגלות המעלה במהות הביטול. ועפ\"ז מובן גם החילוק דבית ראשון ובית שני כדלקמן הערה 72."],["68","68","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380949\" data-slug=\"likkutei-torah\" data-id=\"4001380949\">לקו\"ת ר\"ה נז, ג</a> ואילך."],["69","69","זח\"א קנ, א. וראה שמו\"ר פס\"ז, כו. ובכ\"מ."],["70","70","יומא כא, ב."],["71","71","חגי א, ח."],["72","72","ע\"פ משנ\"ת בלקו\"ש ח\"ט <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071184\" data-slug=\"likkutei-sichot\" data-id=\"1300071184\">שם (וח\"ז ע' 172</a>) מובן גם בנדו\"ד, שלכן בזמן בית ראשון הוא בדוגמת בחי' ציון אף שהי' ביטול פנימי, ביטול במציאות, כיון שהוא שייכות למציאות האדם (שבא מצד השגתו ואהבת ה' כו'), משא\"כ בזמן בית שני הוא בחי' ירושלים כיון ש(איכות) הביטול היא בשלימות (ביטול אמיתי יותר)."],["73","73","ראה לקו\"ת שם (ואוה\"ת חנוכה שא, א. בראשית ע' 1102) שבבית ראשון האיר בחי' ה' עילאה בינה משא\"כ בבית שני ה' תתאה בחי' מלכות, והרי זה גם ההפרש דבחי' ציון וירושלים כמבואר בלקו\"ת (במדבר) ויהל אור (שבהערה 40), דציון הוא פנימיות המלכות (ה' עילאה. אוה\"ת שם), וירושלים חיצוניות המלכות: וגם החילוק דמלוכה וממשלה כמבואר בד\"ה אשרי, סידור ויהל אור (שבהערה 60). וראה יהל אור שם (סק\"ד), דמושל ברוחו הוא אתכפיא ומלוך על יצרך היינו אתהפכא ברצון. שזהו החילוק דב\"ר וב\"ש כבפנים וכבהערה שלפנ\"ז."],["74","74","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380323\" data-slug=\"likkutei-torah\" data-id=\"4001380323\">ראה מלכים א</a> קאפיטל ה. וראה לקו\"ת במדבר ג, ד ואילך. ובכ\"מ."],["75","75","ראה לקו\"ת דברים <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380946\" data-slug=\"likkutei-torah\" data-id=\"4001380946\">שם. ר\"ה נו, ד</a>: וממשלתך בכל דור ודור אפילו דור המבול ודור"]]],[1300151253,"יא. עפ\"י כהנ\"ל וועט מען פאר־שטיין די שייכות פון די ג' בתי מקדשות צו אברהם יצחק ויעקב 76:\nדי עבודה פון אברהם איז בקו החסד מדת האהבה 77, „אברהם אוהבי\" 78, דעריי־בער איז זיין עבודה געווען (בעיקר) אין מפרסם און מגלה זיין אלקות מלמעלה למטה, וואס בדוגמת זה איז געווען די עבודה בבית ראשון 79, כנ\"ל.\nאון דעריבער האט דאס א שייכות (מיוחדת) צו בחי' „ציון\" ו„תורה\" 80: ענינו של אברהם איז דאס וואס ער איז א ציון וסימן צו בחי' חסד שבאצילות 81, היות אבער אז מצד החסד שטייט ער מיט אן אהבה ותענוג צו אלקות — און אהבת ה' אפילו אין דער העכסטער מדרי', איז דאס „יש מי שהוא אוהב\" 82.\nעבודת יצחק איז בקו הגבורה — בחי' יראה וביטול 83, כמ\"ש 84 „ופחד יצחק הי' לי\", איז דאס בדוגמא צו דער בחי' און עבודה פון בית שני 85; און אין דעם באשטייט זיין שייכות צו „ודבר ה' מירושלים\", ווארום שלימות היראה והביטול איז געווען ביי יצחק'ן, מערער ווי דאס איז געווען 86 ביי אברהם'ן 87.\nדי עבודה פון יעקב'ן בחיר האבות 88 איז בבחי' קו האמצעי, תפארת, וואס איז כולל ביידע קווין — סיי עבודת אברהם (קו החסד והאהבה) און סיי עבודת יצחק (קו הגבורה והיראה) 89, און דעריבער איז ער כנגד בית ג' 90, וואס דעמאלט וועט זיין די התכללות פון ביידע מעלות: תכלית השלימות פון גילוי אלקות (נאך מער ווי ס'איז געווען בבית ראשון) — בחי' „ציון\" ו„תורה\", און צוזאמען דערמיט וועט אויך זיין דער ביטול בתכלית השלימות — „דבר ה' מירושלים\" 91.",[["","","הפלגה. וביהל אור שם בתחילתו מהרמ\"א „ופי' דור ודור היינו שגם אחרי שהחריב ביהמ\"ק לא סילק השגחתו כו'\"."],["76","76","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091027\" data-slug=\"likkutei-sichot\" data-id=\"1300091027\">לקו\"ש ח\"ט ע' 27</a> ואילך השייכות דג' מקדשות להאבות בסגנון אחר קצת. וקרוב להמבואר בפנים הוא באלשיך פרשתנו."],["77","77","אגה\"ק סט\"ו. תו\"א ותו\"ח ר\"פ תולדות. ובכ\"מ."],["78","78","ישעי' מא, ח."],["79","79","ולכן „קראו הר\" (לא רק לפי שעתיד ליחרב וליעשות הר, כבאלשיך כאן ובתהלים. עיין יעקב ופי' הרי\"ף לע\"י פסחים שם) „כי באברהם כתיב (לך יב, ט) הלוך ונסוע הנגבה בחי' אהבה נק' הר כמו הר שבולט כו'\" (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380960\" data-slug=\"likkutei-torah\" data-id=\"4001380960\">לקו\"ת ר\"ה ס, ב</a>. עיי\"ש)."],["80","80","להעיר מזח\"ב רנח, א. ובתוד\"ה הר תענית שם: „אברהם שקראוהו הר כו' וההר נקרא כו' כדכתיב כי מציון תצא תורה\". ולהעיר מב\"ר (פנ\"ו, יוד) בזה שהראה הקב\"ה לאברהם הביהמ\"ק „בנוי ומשוכלל כו' כענין שנאמר (תהלים קב, יז) כי בנה ה' ציון גו'\". ובאיכה (ה, יח) „על הר ציון ששמם\"."],["81","81","להעיר מספר הבהיר (סקצ\"א. זח\"א רסד, ב. הובא בפרדס שער כב פ\"ד. ועוד) כך אמרה מדת החסד כל ימי היות אברהם בארץ (כ\"ה בפרדס. בס' הבהיר ובזהר: בעולם) לא הוצרכתי אני לעשות מלאכתי שהרי אברהם עומד שם במקומי. וראה אגה\"ק שם."],["82","82","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370512\" data-slug=\"torah-or\" data-id=\"3901370512\">תו\"א קיד, ד</a>. ביאוה\"ז פא, א (לענין אברהם). ובכ\"מ (ראה בהמצויין בס' הערכים־חב\"ד ח\"א ע' רעט ואילך)."],["83","83","אגה\"ק סי' יג. תו\"א ותו\"ח ר\"פ תולדות. ובכ\"מ."],["84","84","פרשתנו לא, מב."],["85","85","השייכות לשדה — ראה תו\"א ס\"פ חיי שרה."],["86","86","וגם זה שאברהם קרא אותו „יראה\" (ב\"ר שם) הרי זה מצד עקידת יצחק."],["87","87","ראה בהמצויין בהערה 82 במעלת אתכפיא, יראה תתאה (דשרשה בחכמה עילאה בחי' אין) על בחי' אהבה. והמובן משם, דבבחי' אהבה אף שאינו מציאות לעצמו הו\"ה מציאות דקדושה עכ\"פ (בחי' ציון), משא\"כ בבחי' אתכפיא (יראה) הוא בתכלית הביטול (ירושלים). וראה לעיל הערה 52, 73."],["88","88","שער הפסוקים תולדות כז, כה. וראה ג\"כ ב\"ר פע\"ו, א. זח\"א קיט, ב. קמז, ב."],["89","89","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370083\" data-slug=\"torah-or\" data-id=\"3901370083\">תו\"א יז, ג</a>. לקו\"ת ואתחנן ה, ב ואילך. וש\"נ."],["90","90","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380656\" data-slug=\"likkutei-torah\" data-id=\"4001380656\">לקו\"ת מטות פג, ג</a> ואילך."],["91","91","ועפ\"ז י\"ל שזה שהראה הקב\"ה לאברהם"]]],[1300151254,"יב. עפ\"י כהנ\"ל וועט מען פארשטיין דעם טעם וואס די נצחיות'דיקע קביעות פון מקדש שלישי האט א שייכות דוקא צו יעקב'ן (דוקא יעקב „קראו בית\"), און אויך ווי אזוי דאס איז נוגע צו די עמים רבים, וואס וועלן זאגן „לכו ונעלה . . אל בית אלקי יעקב וגו'\":\nקעגן 92 יעדער מדה אין קדושה איז דא א מדה אין לעו\"ז, וואס זי איז מנגד צו דער מדה אין קדושה: אהבה זרה איז די מדה וואס קען מנגד זיין צו אהבת ה', קעגן יראת ה' קען זיין דער ניגוד פון „יראה רעה או כעס\": ובלשון חז\"ל 93 „אברהם יצא ממנו ישמעאל\" (אהבה פון לעו\"ז), און „יצחק יצא ממנו עשו\" (יראה פון לעו\"ז). און דערפאר איז בעבודת האדם קען זיין אז יעדע פון די מדות בפע\"ע זאל ניט האבן קיין קיום (ווי מען זעט עס אין די תוצאה ופעולת „המדה\" — די גרים וואס אברהם אבינו האט מגייר געווען 94, האבן ניט געהאט קיין קיום<sup data-n=\"95\">95</sup>.\nאון עד\"ז איז עס אויך ביי בית ראשון ובית שני, אז יעדערער פון זיי איז געווען אין איין בחינה ומדרי' (בעיקר), דעריבער האט אין זיי געקענט זיין א שליטה פון לעו\"ז, און זיי זיינען חרוב געווארן:\nמשא\"כ מדתו של יעקב, וואס זי איז כולל ביידע קווין חסד וגבורה, קען דעריבער אויף איר ניט זיין קיין מנגד, און דעריבער איז דוקא ביי יעקב'ן געווען מטתו שלימה, שלא יצא ממנו פסול 96.\nאון אזוי איז עס אויך בנוגע דעם בית שלישי: וויבאלד אין אים וועלן זיין ביידע מעלות פון „ציון\" ו„ירושלים\", וועט ער דעריבער זיין א בית קבוע ונצחי.\nיג. דאס איז אויך דער טעם ההדגשה אין פסוק „והלכו עמים רבים ואמרו לכו ונעלה אל הר ה' אל בית אלקי יעקב\" און „כי\" ווי דאס איז מצד דעם טעם וואס „(כי) מציון תצא תורה ודבר ה' מירושלים\":\nכשם ווי מ'זעט עס בגשמיות אז פועל זיין אויף א צווייטן קען מען דעמאלט ווען יענער זעט אז דער וואס מאנט ביי אים מיינט עס מיט אן אמת:\nאזוי אויך בעניננו: בכדי אז אידן זאלן פועל'ן אין וועלט, איז ניט גענוג אז ביי אידן איז דא נאר איין קו (די בחי' פון „ציון\", אדער נאר די בחי' פון „ירושלים\"), נאר עס דארף זיין ביי אים ביידע קווין צוזאמען 97 (אין דער בחי' „ציון\" ו„תורה\" דארף זיך אנהערן „ירושלים\" און „דבר ה'\", וואס אין עבודת האדם מיינט דאס אז אין דער עבודה מתוך אהבה ושכל ועונג דארף זיך אנהערן שלימות הביטול; און אזוי אויך לאידך גיסא, אין בחי' „ירושלים\" און „דבר ה'\", דארף זיין אויך שכל ותענוג וחיות<sup data-n=\"98\">98</sup>;",[["","","ויצחק הבית בנוי ומשוכלל לעת\"ל, הרי זה בכ\"א לפי מדרי': לאברהם הראה בחי' ציון כו' שבבית הג', וליצחק בחי' ירושלים שבבית הג'. וראה יפ\"ת לב\"ר ספס\"ה, שטעם שהראה הקב\"ה ליצחק בית הג' כדי שלא יאמרו מה הועילו הברכות ליעקב כו'."],["92","92","לקו\"ת ואתחנן ה, א ואילך. וראה „התמים\" ח\"ג בתחלתו [קכ, א] תצלום מגכ\"ק הצ\"צ."],["93","93","ויק\"ר פל\"ו, ה. פסחים נו, א. ספרי דברים ו, ד. לב, ט. לג, ב."],["94","94","פרש\"י לך יב, ה (מב\"ר). זח\"א עט, א. ובכ\"מ."],["95","95","ראה רמב\"ם הל' עכו\"ם פ\"א ה\"ג. חנה אריאל (להרה\"ח וכו' הרר\"א מהאמלי) וירא לג, סע\"א. הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101089\" data-slug=\"likkutei-sichot\" data-id=\"1300101089\">לקו\"ש ח\"י ע' 89</a> הערה 14."],["96","96","ראה בהנסמן בהערה 93."],["97","97","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091028\" data-slug=\"likkutei-sichot\" data-id=\"1300091028\">לקו\"ש ח\"ט ע' 28</a> ואילך."],["98","98","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061086\" data-slug=\"likkutei-sichot\" data-id=\"1300061086\">לקו\"ש שם ע' 75</a>. ח\"ו ע' 173."]]],[1300151255,"און בשעת אז ס'איז דא די התכללות פון ביידע ענינים „ציון וירושלים\" דעמאלט איז דאס אן ענין פון אמת — מדתו של יעקב 99 — דאס איז זיין גאנצע מציאות ובמילא איז אין דעם ניטא קיין הפסק ושינויים;\nאון דעריבער איז דאס דער טעם אויף „והלכו עמים רבים ואמרו לכו ונעלה אל הר ה' אל בית אלקי יעקב ויורנו מדרכיו ונלכה באורחותיו\", ווייל דאס איז מעורר די עמים צו לימוד התורה (אין די ענינים פון ז' מצות בני נח), און צו שלימות אין זייער קיום — „נלכה באורחותיו\".\n(משיחות ליל ויום שמח\"ת תשל\"ו)",[["99","99","ראה לקו\"ת מטות שם ובהגהות להמאמר באוה\"ת שם, לענין שייכות גאולה הג' ליעקב. וראה המשך הנ\"ל ע' תלד. ובכ\"מ."]]],[1300151256,"<h3>ויצא ג</h3>\nא. אויף די פסוקים1 „וידר יעקב נדר לאמר אם יהי׳ אלקים עמדי גו׳ והי׳ ה׳ לי לאלקים והאבן הזאת אשר שמתי מצבה יהי׳ בית אלקים גו׳״ — פרעגן מפרשים2: ווי קומט עס אז יעקב האט תולה געווען דעם קיום פון זיינע מעשים טובים (והאבן הזאת גו׳ עשר אעשרנו לך) אין אַ תנאי „אם יהי׳ אלקים עמדי גו׳״ ? צי האט דען יעקב געדינט דעם אויבערשטן נאר, ח״ו, צוליבן שכר ותועלת — ע״מ לקבל פרס ? !\nאיז דערפון גופא3 געדרונגען, אז מיט זיין פאַרבינדן דעם נדר (מעשים טובים) מיט אַ תנאי האט יעקב ניט געמיינט אז זיין מטרה איז צו האַבן די עניני התנאי, און בכדי זיי צו באַקומען האט ער גע־געבן אַ נדר צו טאן מעשים טובים, נאר להיפך: די מטרה זיינע איז געווען דער קיום הנדר4, און זיין תולה זיין דעם נדר אינעם תנאי „אם יהי׳ אלקים עמדי גו׳״ איז ווייל דאס איז דער וועג דורך וועלכן4* דער נדר קען זיך אויספירן5.\nב. וועט מען דאס פאַרשטיין בהק־דים וואס בנוגע דעם תנאי און דעם נדר זיינען דאָ צוויי פירושים: רש״י לערנט6 אז דער תנאי איז כולל (און ענדיקט זיך מיט) „והי׳ ה׳ לי לאלקים״ („שלא ימצא פסול בזרעי״), און דער נדר הויבט זיך אָן מיטן צווייטן פסוק — „והאבן הזאת אשר שמתי מצבה גו׳״; און דער רמב״ן7 לערנט, אז „והי׳ ה׳ לי לאלקים״ איז (ניט דער המשך התנאי „כדברי רש״י״, נאר) דער אנהויב פון נדר, און דער תנאי ענדיקט זיך מיט די ווערטער „ושבתי בשלום אל בית אבי״.\nדארף מען פאַרשטיין לשיטת הרמב״ן: ווייבאַלד „והי׳ ה׳ לי לאלקים״ איז די התחלה פון דעם נדר, האט די חלוקת הפסוקים געדארפט זיין אין אן אופן אז „והי׳ ה׳ לי לאלקים״ זאל זיין (ניט דער סיום פון פסוק „ושבתי בשלום גו׳״ וואס רעדט וועגן תנאי, נאר) די התחלה פון פסוק „והאבן הזאת גו׳״ וואס רעדט וועגן נדר ?\n[ובפרט אז „והי׳ ה׳ לי לאלקים״ האט (לשיטתו) ניט בלויז אַ שייכות צו „והאבן הזאת גו׳ יהי׳ בית אלקים״ מצד דעם וואס זיי זיינען טיילן פון נדר, נאר נאכ־מער — זיי זיינען איין תוכן והמשך, ובלשון הרמב״ן: אעבוד השם המיוחד . . במקום האבן הזאת שתהי׳ לי לבית אלקים].\nמוז מען זאגן אויך לדעת הרמב״ן, אז „והי׳ ה׳ לי לאלקים״ (הגם אז דאס איז אַ",[["1","1","פרשתנו כח, כ ואילך."],["2","2","פענח רזא וריב״א פרשתנו שם, כב. אברבנאל ריש פרשתנו (קושיא הה׳). עקידה שער כה (קושיא הב׳). אלשיך פרשתנו כח, כ (קושיא הה׳). וראה רא״ם לפרש״י שם, כא. דברי דוד שם כב. ועוד."],["3","3","ע״ד הפשט בפרש״י — ראה דברי דוד ומשכיל לדוד שם כב (ועוד), שהנדר הי׳ לעשות מה שאינו מחויב. אבל ביאור זה אינו מספיק כי מובן שאצל יעקב אבינו — שהאבות ה״ה המרכבה (ב״ר פמ״ז, ו. פפ״ב, ו. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא פכ״ג</a>) — גם העבודה דענינים אלו (לפנים משורת הדין „פולחן דנדבה״ וכיו״ב) היתה שלא ע״מ לקבל פרס, ובמילא — בלי שום תנאי."],["4","4","להעיר מרמב״ן שם, כ: ויתכן עוד ע״ד הפשט כו׳. רבחיי בעה״ת שם. ועוד. 4*) ע״ד (ולא ממש) ב׳ הרמב״ם הל׳ תשובה פ״ט (הקדמתו לפ׳ חלק)."],["5","5","ראה כלי יקר (שם, כא בסופו): כ״א לא ישמרו מן ד׳ ראשי עבירות אלו אז לא יהי׳ בית אלקים כי יחרב בעבורם."],["6","6","וכן הוא לפי׳ המדרש (ב״ר פ״ע, ד) ורשב״ם."],["7","7","ועד״ז ברד״ק. ספורנו. כלי יקר."]]],[1300151257,"חלק פון נדר) האט אין אַ פרט מער שיי־כות מיטן תנאי „ושבתי בשלום״ ווי מיטן המשך הנדר „והאבן הזאת גו׳״, וואס דעריבער שטייען זיי („והי׳ גו׳״ און „ושבתי גו׳״) אין איין פסוק.\nג. כשם ווי דער נדר ווערט איינגע־טיילט אין צוויי פסוקים („והי׳ ה׳ לי לאלקים״ און „והאבן הזאת וגו׳״) דער־פאר וואס דאס זיינען צוויי סוגים אין נדר, כנ״ל — עד״ז איז אויך בנוגע די תנאים וואס יעקב האט אויסגענומען, אז דאס וואס זיי טיילן זיך אין צוויי פסוקים — (א) „אם יהי׳ אלקים עמדי גו׳ ושמרני גו׳ ונתן גו׳ ובגד ללבוש״, און (ב) „ושבתי בשלום אל בית אבי״ (און לויט רש״י — אויך דעם סיום הפסוק „והי׳ ה׳ לי לאלקים״) — איז עס צוליב דעם וואס זיי זיינען צוויי סוגים.\nאון ווי דאס איז אויך מודגש אין לשון הפסוק: אין ערשטן פסוק רעדט זיך וועגן זאכן וואס דער אויבערשטער וועט טאן — „יהי׳ אלקים עמדי ושמרני גו׳ ונתן לי גו׳״; משא״כ אין צווייטן פסוק איז דער לשון „ושבתי גו׳״ (ניט — „והשיבני גו׳״ וכיו״ב)8, כאילו ווי די השבה וועט זיך אויפטאן פון זיך אליין9.\nד. די נקודת הביאור בכל זה:\nדי „ירידה״ פון יעקב אבינו — זיין אר־ויסגיין פון באר שבע (ארץ ישראל) קיין חו״ל ובפרט חרן (חרון אף של מקום (בעולם)<sup data-n=\"10\">10</sup>, איז געווען לצורך עלי׳. און אין דער עלי׳ זיינען דאָ דריי ענינים:\nא) דורך דעם וואס זייענדיק דארט, אין חרן און בית לבן, איז ער ניט מושפע געווארן און איז אר־ויס פון דארט „שלם מן החטא״11 — איז יעקב נתעלה געווארן צו אַ העכערער דרגא ווי ער איז געווען פריער קודם הירידה.\n[וע״ד (ולא ממש<sup data-n=\"12\">12</sup> המעלה פון אַ בעל תשובה אויף אַ צדיק — „מקום שבע״ת עומדין אין צדיקים גמורים יכולין לעמוד בו״ — וואס דאס איז דערפאַר וואס דער בעל תשובה האט „טועם״ געווען „טעם החטא״ און פונ־דעסטוועגן „פירש ממנו וכבש יצרו״13].\nב) דארט דוקא האט ער דורכגעפירט דעם ציווי „פרו ורבו גו׳ וכבשוה״, דעם „קח לך משם אשה גו׳ ויפרך גו׳״14 ובאופן דמטתו שלימה15.\nג) בלשון החסידות — דורך זיין עבודה מיט די צאן לבן, במשך עשרים שנה16, האט ער מברר ומעלה17 געווען די ניצוצות קדושה וואס האבן זיך גע־פונען אין צאן לבן — און דאס האט אויפגעטאן אין אים אן עילוי ביז אינעם אופן פון „ויפרוץ האיש מאד מאד״18.",[["8","8","אלשיך שם (קושיא הה׳). גו״א דברי דוד לפרש״י שם, כא, לבוש שם, כ. ועוד."],["9","9","אף שגם „ושבתי גו׳״ הוא „כמו ש(הקב״ה) אמר לי והשיבותיך אל האדמה״ (רש״י שם, כא)."],["10","10","פרש״י ס״פ נח."],["11","11","לשון רש״י בפסוק זה. וראה רש״י וישלח לב, ה."],["12","12","בדומה יותר — ראה פ״ו משמונה פרקים להרמב״ם."],["13","13","רמב״ם הלכות תשובה פ״ז ה״ד."],["14","14","תולדות כח, ב־ג."],["15","15","ויק״ר פל״ו, ה. וראה פסחים נו, א. ספרי דברים ו, ד. ועוד."],["16","16","וגם לאחר זה בדרכו מחרן לא״י — ראה תורת ה״מ (הובא באור המאיר) במה שרדף לבן אחר יעקב (נתבאר באוה״ת פרשתנו תתסט, א ואילך)."],["17","17","כמרומז גם בנגלה (בתשב״כ): ויקם שדה עפרון (ח״ש כג, יז ובחז״ל עה״פ. פרש״י שם)."],["18","18","פרשתנו ל, מג. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370109\" data-slug=\"torah-or\" data-id=\"3901370109\">תו״א כג, ג</a>. ועוד."]]],[1300151258,"ה. „מעשה אבות — סימן לבנים״. איז מובן, אז דער ענין פון „ויצא יעקב מבאר שבע וילך חרנה״ איז פאראן אויך אין עבודת כאו״א; און ווי דער אור החיים19 איז מבאר, אז דער פסוק איז מרמז אויף כללות ירידת הנשמה למטה (און אויך אויף דער ירידה פון אידן אין גלות<sup data-n=\"20\">20</sup>, וואס דאס איז אַ ירידה צורך עלי׳ — און אין דעם זיינען דאָ די ענינים הנ״ל (ע״ד ווי די ענינים אין דער עלי׳ פון יעקב)21:\nא) די נשמה זייענדיק למעלה פאַר דער ירידה איז זי בבחינת צדיק; און דורך דעם וואס זי איז יורד למטה און ווערט נתלבש אין אַ גוף ונה״ב וועלכע זיינען מעלים ומסתיר אויף אלקות און פונדעסטוועגן טוט זי איר עבודה בתורה ומצוות — קומט אין איר צו די מעלה (פון והרוח תשוב אל האלקים21*) פון בעל תשובה22.\nב) בירידתה למטה איז זי מקיים דעם ציווי פרו ורבו גו׳ (און תומ״צ בכלל).\nג) דורך איר עבודה למטה אין דברים גשמיים טוט זי אויף אַז די וועלט זאל ווערן אַ דירה לו ית׳ — „דירה בתחתו־נים״, און דורך דעם ווערט זי נתעלה אַ סאָך העכער ווי זי איז געווען פריער23.\nאון אין דעם ענין וואס די וועלט („תחתונים״) ווערט אַ דירה לו ית׳ (און אין די עליית הנשמה וואס ווערט דורך דעם), איז דאָ אַ יתרון (בפרט אחד) אין דער עבודה פון „וכל מעשיך יהיו לשם שמים״24 און „בכל דרכיך דעהו״25 אויף דער עבודה פון לימוד התורה און קיום המצוות; וואַרום דורך דעם וואס אויך די עניני הרשות פון מענטשן („מעשיך״ און „דרכיך״) זיינען „לשם שמים״ און אין אַן אופן פון „דעהו״, ווערט די דירה לו ית׳ אויך אין „תחתונים״ ממש26.\nו. ויש לומר, אז דער יתרון פון דער עבודה אין עניני הרשות לגבי דער עבודה פון תומ״צ איז אויך בנוגע דעם ערשטן עילוי (וואס די נשמה קומט צו צו דער מעלה פון בעל תשובה)26*:\nבשעת אַ איד טוט אַ מצוה, אפילו ווען דער קיום המצוה איז אין אַן אופן וואס ער דאַרף זיך מתגבר זיין אויפן יצה״ר וואס שטערט עם פון מקיים זיין די מצוה,\nפונדעסטוועגן, ווייבאַלד אז נאכדעם",[["19","19","פרשתנו כח, יד. הובא ונתבאר בקיצורים והערות לתניא ע׳ נז. ד״ה ויצא תר״ל."],["20","20","ראה זהר ריש פרשתנו קמז, א: אוקי האי קרא בגלותא. שם כג, ב (הובא באוה״ת פרשתנו תתנד, א). ב״ר פס״ח, יג. ובשל״ה פרשתנו (רצב, ב): ענין ויצא יעקב רומז ג״כ לגלות. ע״ש."],["21","21","<a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">ראה גם ד</a>״ה ויצא שם, שמבאר ב׳ ענינים בירידה צורך עלי׳. אלא שב׳ הענינים שבד״ה ויצא שם, הם: העלי׳ דנפה״א למעלה משרשה ע״י בירור הגוף ונפה״ב — שהוא (בכללות) ענין הג׳ שבפנים; ו„להמשיך דירה בתחתונים כו׳ כי נתאוה הקב״ה להיות לו דירה בתחתונים״ — שהכוונה בפשטות ב„עלי׳״ זו היא (לא להעלי׳ שנעשית בהנשמה, כי אם) למעלת הענין ד„דירה בתחתונים״ גופא, או: להעלאת התחתונים ע״ד הלשון בתניא ספל״א (מ, ב) „ירידה זו היא צורך עלי׳ להעלות לה׳ כל נפש החיונית כו׳״. 21*) ראה לקו״ת ר״פ האזינו."],["22","22","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380610\" data-slug=\"likkutei-torah\" data-id=\"4001380610\">לקו״ת בלק עג, סע״א</a>. ד״ה ומעין תש״ו (וראה שם ס״ג). ועוד."],["23","23","ובזה גופא יש שני ענינים: מצד הענין דבירור העולם גופא (כדלקמן ס״ח), ומצד השלמת הכוונה דנתאוה הקב״ה (כדלקמן ס״ט). וראה לקמן הערה 44."],["24","24","אבות פ״ב מי״ב."],["25","25","משלי ג, ו. טושו״ע או״ח סרל״א."],["26","26","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081119\" data-slug=\"likkutei-sichot\" data-id=\"1300081119\">לקו״ש ח״ח ע׳ 108</a> ואילך. וש״נ. 26*) להעיר מהמבואר בכ״מ (ד״ה מלכא ומלכתא תרצ״א בסופו. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381307\" data-slug=\"likkutei-torah\" data-id=\"4001381307\">לקו״ת שה״ש מד, סע״ד</a>) שיושבי אהל ובעלי עסקים הם דוגמת צדיקים ובעלי תשובה."]]],[1300151259,"ווי ער איז זיך כופה צו מקיים זיין די מצוה איז „תשש יצרו״27 און עס ווערט נתגלה זיין אמת׳ער רצון — וואס יעדער איד (בפנימיותו) „רוצה הוא לעשות כל המצות״28 — קומט אויס, אז אין דעם קיום המצוה גופא האט דער יצה״ר קיין שייכות ניט; ובמילא איז דער קיום המצוה ניט אין דער בחי׳ פון אַ בעל תשובה נאר אין דער בחינה פון אַ צדיק:\nמשא״כ די עבודה פון „כל מעשיך יהיו לש״ש״ און „בכל דרכיך דעהו״, ווי־באלד אז זיין טאן די עניני הרשות קומט מצד דעם וואס בטבעו איז ער מתאווה צו זיי מצד דעם גוף וקיומו וחיותו29, מצד נפשו הבהמית30 [וואס דערפאר, איז אויך ווען ער טוט זיי „לשם שמים״ און אפילו אין אַן אופן פון „דעהו״ — פארבלייבן זיי „מעשיך״ און „דרכיך״] — איז בשעת אז ער טוט די עניני הרשות לשם שמים אדער אין אַן אופן פון „דעהו״, דאן איז די עשי׳ עצמה אין אַן אופן פון אַ „בעל תשובה״.\nז. דער ביאור בפרטיות יותר אין דעם עילוי ה„תשובה״ וואס ווערט דער־רייכט דורך דער עבודה פון „וכל מעשיך כו׳״ „בכל דרכיך כו׳״ אויף דער „תשובה״ פון „כבישת היצר״ וואס איז דאָ אויך אין דער עבודה פון תורה ומצוות:\nאיינע פון די מעלות אין עבודת התשובה (כפשוטה) איז, וואס תשובה ברענגט ארויס דעם תוקף פון דער\nהתקשרות פון אַ אידן מיטן אוי־בערשטן, אז די התקשרות פארלירט זיך ניט ח״ו אפילו דורך אַ חטא און וואס דערפאר קען ער31 אפילו לאחרי החטא נאך אלץ טאן תשובה32.\nועד״ז איז אויך בנוגע דעם ענין ה„תשובה״ וואס איז דאָ אין דער עבודת הנשמה בירידתה למטה אז אין דעם זאגט זיך ארויס בגילוי דער תוקף ההתקשרות פון דער נשמה מיטן אויבערשטן, אז אויך ווען זי איז אנ־געטאן אין גוף ונה״ב (און יצה״ר) איז זי פארבונדן מיטן אויבערשטן דורך עבודת ה׳.\nועפ״ז איז פארשטאנדיק דער עילוי פון דער „תשובה״ וואס ווערט דער־גרייכט דורך טאן עניני הרשות לשם שמים, לגבי דער „תשובה״ וואס איז דאָ אין דער עבודה פון תומ״צ:\nאין דער עבודה פון תומ״צ זאגט זיך ארויס דער תוקף ההתקשרות פון דער נשמה אין דעם, וואס אויך זייענדיק אין גוף ונה״ב האט זי בכח צו שטארקן זיך איבער זיי און „ארויסגיין״ פון זיי „תשש יצרו״; דורך דעם אבער, וואס אויך די עניני הרשות טוט זי „לשם שמים״ וכו׳ ברענגט זיך ארויס, אז איר התקשרות איז אפילו אין די ענינים וואו ס׳איז נרגש דער רצון פון נפש הבהמית.\nח. אבער אעפ״כ, איז אויך דער עילוי פון דער נשמה — דער עילוי פון תשובה וואס ווערט דורך עשיית עניני הרשות לשם שמים וכו׳ — קומט ניט צו דעם עילוי (ענין הג׳ דלעיל סעיף ה׳)",[["27","27","במכש״כ ממ״ש הרמב״ם (הל׳ גירושין ספ״ב) ענין זה אפילו כשאחרים כופין אותו."],["28","28","רמב״ם שם."],["29","29","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא רפ״ז</a>."],["30","30","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201347\" data-slug=\"likkutei-sichot\" data-id=\"1300201347\">לקו״ש ח״כ ע׳ 334</a> ובהערות שם."],["31","31","ויתירה מזו, „שבודאי סופו לעשות תשובה״ (<a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא ספל״ט</a>. הל׳ ת״ת לאדה״ז פ״ד סוס״ג)."],["32","32","ראה לקו״ש ח״ה ע׳ 249 הערה 59 (ענין הא׳)."]]],[1300151260,"וואס טוט זיך אויף אין איר דורך דעם וואס זי מאכט די וועלט פאר אַ דירה לו ית׳33.\nאיינער פון די ביאורים בזה:\nדי התקשרות פון דער נשמה מיטן אויבערשטן איז פארבונדן מיט איר „מציאות״ און „טבע״. און דעריבער, הגם אַז די טבע ההתקשרות איז מיט אַ תוקף (וואס בלייבט בשלימותו אפילו ווען זי איז מלובש אין נה״ב), ווייבאלד אבער אז דאס איז די „טבע״ פון איר „מציאות״, איז דאָ אין דעם אַ הגבלה34.\nמשא״כ35 דורך דעם וואס די נשמה פועלט אז די עניני העולם זאלן ווערן כלים לאלקות (וואס ווייבאלד אז דאס (וואס זיי ווערן כלים צו אלקות) קומט ניט מצד זייער „טבע״ און „מציאות״ [וואַרום אדרבה: די „מציאות״ פון „עולם״ (מלשון העלם<sup data-n=\"36\">36</sup> איז מעלים ומסתיר אויף אלקות], נאר מצד דעם אוי־בערשטן, וואס היות אז זיין „אחדות״ האט ניט קיין הגבלות קען דעריבער אויך דער „עולם״ זיין אַ דירה לו ית׳37,\nאיז דורך דעם וואס די נשמה מאכט פון וועלט אַ דירה צום אויבערשטן און ברענגט דערמיט ארויס דעם בל״ג פון אחדותו של הקב״ה — ווערט אויך איר התקשרות מיטן אויבערשטן (ניט נאר ווי ס׳איז מצד איר „מציאות״, נאר) ווי דאס איז מצד אחדותו של הקב״ה הבלתי מוגבל38.\nט. אַט די עליות, צו וועלכע די נשמה קומט צו דורך איר ירידה למטה, זיינען נאך ניט דער תכלית המכוון פון איר ירידה. וואַרום ווייבאלד אז „כל מה שברא הקב״ה (בעולמו) לא בראו אלא לכבודו״39 — און „אני נבראתי לשמש את קוני״40 — איז פארשטאנדיק, אז דער תכלית המכוון פון (בריאת האדם",[["33","33","ענין זה יש גם בבע״ת בתשובה כפשוטה, אשר [נוסף על העילוי שמצד האדם, זה שגם לאחרי החטא הוא שב לה׳ (כנ״ל סעיף ז׳), הנה] ע״י שמהפך הזדונות לזכיות (יומא פו, ב) מתוסף בו גם עילוי הבא מצד „זכיות״ אלו (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380190\" data-slug=\"likkutei-torah\" data-id=\"4001380190\">לקו״ת אחרי כו, ג</a>. דרמ״צ קצא, סע״א). ולהעיר מד״ה פדה בשלום תש״ט פ״א, שהצדיקים עבודתם היא לעצמם ועניין התשובה הוא „לפעול גם בדבר שחוץ להם״. וזהו״ע העלי׳ דהנשמה ע״י ירידתה למטה, שהיא „נעשית בבחי׳ בע״ת . . להאיר את העולם״. אלא שמלשון זה משמע שהעילוי בתשובה שנעשה בהנשמה ע״י ירידתה למטה הוא (לא העלי׳ של הנשמה הבאה ע״י שמאירה את העולם, כ״א) העניין ד„להאיר את העולם״ גופא. וראה לקמן ס״ט ובהערה 44."],["34","34","ראה ד״ה תניא ד״ד תרצ״ז (סה״מ קונט׳ ח״ב שצד, א), דזה ש„נשמת האדם .. חפצה וחשקה בטבעה . . ולדבקה בשרשה ומקורה״ (<a class=\"ft-cite\" href=\"#/read/tanya/3401310034\" data-slug=\"tanya\" data-id=\"3401310034\">תניא פכ״ט</a>) — אף שרצון זה אינו בשביל עצמה, שהרי כשתדבק בשרשה „תהי׳ אין ואפס ותתבטל שם במציאות לגמרי״ (<a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא שם</a>), מ״מ — מכיון שרצון זה הוא מצד טבעה, לכן ע״י רצון זה „אינו מתבטל מטבעו וכ״ש שאינו נאבד צורתו העצמי״. ושם (וראה עד״ז ד״ה וכל העם תרע״ח. ד״ה לריח שמניך תשי״ו פ״ז), שע״י שנה״א פועלת הבירור דנה״ב עד שגם נה״ב מתעוררת ברצוא לאלקות, מכיון שבנה״ב הרצוא לאלקות הוא היפך טבעה, הנה „זה פועל בהנפש האלקית דגם הוא מתבטל מטבעו״. ושם (ע״ב) שע״י״ז נעשה בה ה„יציאה מגדר הכלים והגבלה לגמרי״."],["35","35","ובדוגמת המבואר בד״ה לריח שמניך שם מעלת העלי׳ דנה״א שנעשה בה ע״י שפועלת בירור דנה״ב (שגם הנה״ב תתעורר ברצוא לאלקות) על העלי׳ שנעשה בה ע״י שמתגברת על נה״ב."],["36","36","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380459\" data-slug=\"likkutei-torah\" data-id=\"4001380459\">לקו״ת שלח לו, ד</a>."],["37","37","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121075\" data-slug=\"likkutei-sichot\" data-id=\"1300121075\">לקו״ש חי״ב ע׳ 75</a> ובהערות שם."],["38","38","ובדוגמת העלי׳ בנה״א שנעשה ע״י בירור נה״ב (ראה לעיל הערה 34). אלא שגם העילוי שנעשה ע״י בירור נה״ב — מכיון שנה״ב יש לה שייכות לנה״א (ראה סה״מ קונטרסים ח״א רסו, סע״ב ואילך) — לכן, החידוש ובמילא גם העילוי שנעשה עי״ז אינו כהחידוש והעילוי שע״י בירור עניני העולם."],["39","39","אבות ספ״ו."],["40","40","משנה סוף קידושין."]]],[1300151261,"און) ירידת הנשמה למטה איז (ניט צו־ליב דער עלי׳ פון דער נשמה, נאר) בכדי דורכצופירן דעם אויבערשטנ׳ס כוונה41.\nאון ע״ד ווי דער אלטער רבי זאגט אין תניא42, אז ירידת הנשמה למטה איז ניט לצורך, נאר בכדי צו איבער־מאכן דעם גוף ונפש החיונית און חלקו בעולם — „לקשרם ולייחדם באוא״ס ב״ה״, וואס דורך דעם וועט זיך אויס־פירן די כוונה פון „נתאווה43 הקב״ה להיות לו דירה בתחתונים״.\nעס איז נאר, וואס היות אז די נשמה איז די וואס פירט אויס די כוונה הנ״ל, קומט איר פאר דעם אַ „שכר טוב לאין קץ״, דערפאר44 האט אויך אין זי אַן „עלי׳ גדולה ונפלאה לאין קץ״45.\nדארף מען פארשטיין: ווי איז דאס מתאים דערמיט וואס עס שטייט בכמה מקומות46, אז די ירידת הנשמה למטה איז „בשביל העלי׳״, וואס דאס מיינט לכאורה אז די עליית הנשמה איז ניט קיין ענין צדדי, נאר דער טעם ותכלית פון איר ירידה ?\nיוד. איז דער ביאור אין דעם (בקצרה עכ״פ):\nס׳איז ידוע47 אז אין דעם ענין פון „דירה לו ית׳ בתחתונים״, אז דוקא „תחתונים״ ווערן אַ דירה לו ית׳ — לו לעצמותו. אין „עליונים״ זיינען מאיר „גילויים״, משא״כ „תחתונים״ ווערן אַ דירה לעצמותו ית׳.\nאון דער ענין, וואס עצמות „געפינט״ זיך דוקא למטה, איז פארבונדן דערמיט וואס דוקא אין עוה״ז איז דאָ דער ביטול פון „אין עוד״, ניט ווי אין עולמות עליונים וואס אין זיי איז דער ביטול פון „כלא״48.\nאון היות אז די כוונה איז אז די דירה זאל זיך אויפטאן דורך עבודת האדם דוקא49 — דארף דעריבער אויך די עבודה (דורך וועלכער עס טוט זיך אויף די „דירה״) זיין בבחינת ביטול לגמרי [ביז צו אַ ביטול וואס איז „מעין״ פונעם ביטול פון „אין עוד״, אזוי ווי דער ביטול פון אַן עבד פשוט50 וואס קומט (ניט מצד דעם וואס ער איז מרגיש הפלאת האדון וכיו״ב, נאר) מצד דעם אדון אליין51].",[["41","41","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380831\" data-slug=\"likkutei-torah\" data-id=\"4001380831\">לקו״ת ראה כח, ד</a>."],["42","42","פל״ז (מח, ב). וזה בא בהמשך להמבואר שם פל״ו שתכלית הבריאה הוא שיהי׳ לו (ית׳) דירה בתחתונים."],["43","43","תנחומא נשא טז. <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל״ו</a>."],["44","44","ויש לומר, שעלי׳ זו דהנשמה מצד זה שמשלמת הכוונה ד„דירה בתחתונים״ שבעצמותו ית׳ — מכיון שעצמותו ית׳ אין שייך לתארו גם בענין הבל״ג (ראה המשך תרס״ו ס״ע קסז. ובכ״מ), לכן גם השכר והעלי׳ שמצד השלמת כוונה זו הוא נעלה יותר מהעלי׳ דהנשמה שמצד גילוי אחדותו ית׳ הבלתי מוגבל דלעיל ס״ח. ואפ״ל, שענינה של עלי׳ זו (שמצד הכוונה) בעבודת האדם הוא שיורגש בו ענין זה שכל מציאותו היא רק לכבודו ית׳, לשמש את קונו."],["45","45","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380832\" data-slug=\"likkutei-torah\" data-id=\"4001380832\">לקו״ת שם כט, א</a>."],["46","46","ראה בהמצויין בהערה 22. ולהעיר שגם בלקו״ת שם איתא „הירידה . . היא בשביל עלי׳ כו׳״ (אלא שמסיים שם „שעכ״ז לא זה לבד הוא תכלית המכוון כו׳״)."],["47","47","ראה המשך תרס״ו ע׳ ג׳ (ושם ע׳ ח׳). ד״ה מצותה משתשקע תרע״ח — ע״פ <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל״ו</a>."],["48","48","ראה בארוכה ד״ה ולקחתם לכם תרס״א. וראה גם המשך תרס״ו ע׳ תלח."],["49","49","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121073\" data-slug=\"likkutei-sichot\" data-id=\"1300121073\">לקו״ש חי״ב ע׳ 73</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141135\" data-slug=\"likkutei-sichot\" data-id=\"1300141135\">חי״ד ע׳ 123</a>."],["50","50","ראה המשך תרס״ו שם: דענין העבודה בפועל דבחי׳ אין עוד הו״ע קבעו״ש בחי׳ עבודת עבד."],["51","51","שזהו העילוי שב„עבד פשוט״ על „עבד נאמן״ (המשך תרס״ו ע׳ שכו ואילך)."]]],[1300151262,"ועפ״ז יש לומר אז דאס וואס שטייט בכ״מ אז ירידת הנשמה למטה איז „בשביל העלי׳״52 איז פארבונדן דער־מיט וואס שטייט אין תניא אז ירידת הנשמה למטה איז בכדי צו דורכפירן די כוונה „דירה בתחתונים״: וואַרום די עליית הנשמה איז דאָך דאָס וואס זי קומט צו צו בחינת ביטול [אז איר עבודה איז ניט מצד איר „מציאות״ נאר מצד אחדותו של הקב״ה53 (כנ״ל ס״ח)] — און אין דער כוונה פון „דירה בתחתונים״ איז דאָך נוגע אז די עבודה וואס טוט אויף די „דירה״ זאל זיין בבחי׳ ביטול54.\nיא. ע״פ כל הנ״ל וועלן פארשטאנ־דיק ווערן די פיר ענינים הנ״ל וואס אין המשך הכתובים פון „וידר יעקב נדר״ —\nסיי די צוויי ענינים פונעם תנאי — (א) „יהי׳ אלקים עמדי ושמרני גו׳ ונתן לי לחם לאכול ובגד ללבוש״, און (ב) „ושבתי בשלום אל בית אבי״ [וואס פון זייער פאנאנדערטיילונג אין צוויי פסוקים איז מובן אז זיי זיינען צוויי סוגים, כנ״ל] און סיי די צוויי ענינים פון דעם „נדר״ (לפירוש הרמב״ן) — (א) „והי׳ ה׳ לי לאלקים״, און (ב) „והאבן הזאת אשר שמתי מצבה יהי׳ בית אלקים״ [וואס אויך זיי טיילן זיך אין צוויי פסוקים]:\nדער תכלית המכוון איז (כאמור לעיל סעיף א׳) דער נדר, און דער תנאי איז נאר די וועג ווי צו קענען דורכפירן דעם נדר. ועפ״ז הנ״ל אז דער תכלית פון ירידת הנשמה באשטייט פון צוויי פרטים [(א) בשביל עליית הנשמה, (ב) בכדי צו אויפטאן די „דירה בתחתונים״] און אזוי אויך אין איר עבודה וואס ברענגט צו דעם זיינען דאָ צוויי ענינים [די עבודה פון תומ״צ און די עבודה פון כל מעשיך לש״ש] — דארף אויס־קומען, אז די צוויי ענינים פון דעם תנאי זיינען די צוויי סוגי עבודה הנ״ל:",[["52","52","בפשטות אפ״ל, שהטעם „בשביל העלי׳״ הוא בבחינת הגילויים [ועד״ב הטעמים בסיבת הבריאה „בגין דישתמודעון לי״ (זח״ב מב, ב) ו„יתגלו שלימות כוחותיו כו׳״ (עח״ת בתחלתו. שער ההקדמות הקדמה ג׳) — ראה המשך תרס״ו ע׳ ד׳ ואילך. שם ע׳ תמו]. אבל יש לומר, שהטעם „בשביל העלי׳״** שייך גם להכוונה האמיתית ד„דירה בתחתונים״ שבעצמותו ית׳, כדלקמן בפנים."],["53","53","שביטול זה הוא דוגמת הביטול דעבד פשוט, העבודה בפועל ד„אין עוד״*. אבל למטה ממנו — ראה לעיל הערה 44."],["54","54","ומ״ש בכ״מ שכוונת ירידת הנשמה היא בשביל העלי׳ — אף שעניין זה מה שעבודתה היא בבחי׳ ביטול (שזהו עלייתה) היא (לכאורה) רק הכנה להשלמת הכוונה — יש לומר: מכיון דזה מה שבכח העבודה לעשות דירה לו ית׳ הוא ע״י שהיא בבחי׳ ביטול, הרי נמצא, שבאם העבודה היתה שלא בביטול — היתה ה„דירה״ נעשית מצד הקב״ה ולא מצד (ובכח) עבודת האדם. ולכן: כמו שהעבודה (שהדירה תיעשה ע״י עבודת האדם) הו״ע בהכוונה ד„דירה בתחתונים״ גופא (ולא רק הכנה אלי׳) — עד״ז הוא גם ענין הביטול שבהעבודה. *) וי״ל דאין סתירה לזה ממ״ש ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380610\" data-slug=\"likkutei-torah\" data-id=\"4001380610\">לקו״ת בלק (עג, א</a>) „התירוץ האמיתי הוא . . היתרון שלהם בירידתן בגוף שנעשים בחי׳ בעלי תשובה״ — כי הענין ד„נתאוה כו׳ דירה בתחתונים״ אינו בגדר „תירוץ״, מכיון שהענין ד„נתאוה״ הוא למעלה מטעם „אויף א תאוה איז קיין קשיא״ (המשך תרס״ו ס״ע ד ואילך); וה„תירוץ״ (הטעם) על הירידה הוא — מה שנעשה „יתרון״ ע״י הירידה, ובנוגע לזה אומר בלקו״ת שם „יש על זה כמה תירוצים אך התירוץ האמיתי הוא . . שנעשים בחי׳ בעלי תשובה״. **) ועד״ז הוא גם בנוגע להטעמים דסיבת הבריאה שבזהר וע״ח — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161021\" data-slug=\"likkutei-sichot\" data-id=\"1300161021\">לקו״ש חי״ו ע׳ 21</a> הערה 69."]]],[1300151263,"„יהי׳ אלקים עמדי ושמרני גו׳ ונתן לי לחם לאכול ובגד ללבוש״ — דאס איז דער נתינת כח מלמעלה אויף סור מרע, אויסצוהיטן זיך פון עבירות (ושמרני גו׳)55 און אויף עשה טוב, לימוד התורה וקיום המצוות („לחם״ ו„בגד״)56; און „ושבתי בשלום גו׳״ — די עבודה אין דברי הרשות [וואס איז דוגמת ענין התשובה („ושבתי״)]57, טראַץ דעם וואס זיין התעסקות אין דברי הרשות איז דערפאר וואס דער נפש הבהמית איז רוצה בהם פונדעסטוועגן58 זיינען אויך די ענינים אים ניט מוריד אין רע („שלם מן החטא שלא אלמוד מדרכי לבן״<sup data-n=\"59\">59</sup>, וואַרום ער טוט זיי ניט למלאות תאוותו נאר „לשם שמים״:\nאון די צוויי סוגי עבודה ברענגען־צו צו די צוויי ענינים פון „נדר״ — די כוו־נה און תכלית פון ירידת הנשמה למטה:\nפריער „והי׳ ה׳ לי לאלקים״ — די עלי׳ פון (מענטשן —) דער נשמה; און דער־נאך ו„האבן הזאת גו׳ יהי׳ בית אלקים״ — די „דירה לו ית׳ בתחתונים״.\n[און היות אז עיקר עליית הנשמה איז (כנ״ל סעיף ח׳) וואס זי „גייט ארויס״ פון איר „מציאות״ און זי איז עובד את ה׳ (ניט מצד איר „טבע״ נאר) מצד דעם אויבערשטן וואס ער איז נמצא בכל מקום אויך אין עניני העולם (וואס זיי־נען ניט אלקות) —\nדעריבער איז דער סדר הכתוב אז „והי׳ ה׳ לי לאלקים״ קומט אין איין המשך מיט „והאבן הזאת גו׳ יהי׳ בית אלקים״, ובלשון הרמב״ן: אעבוד השם המיוחד . . במקום האבן הזאת שתהי׳ לי לבית אלקים — אז זיין עבודה וועט זיך אנהערן ווי זי איז (ניט מצד זיין טבע נאר) בדוגמת „האבן הזאת שתהי׳ לי לבית אלקים״, וואס דאס וואס „אבן הזאת״ וועט זיין „בית אלקים״ איז דאָך נאר מצד דעם וואס אחדותו של הקב״ה איז בלי גבול].\nאבער אעפ״כ איז „והי׳ ה׳ לי לאלקים״ אין איין פסוק מיט „ושבתי בשלום גו׳״ און ניט מיט „והאבן הזאת גו׳״ — ווייל היות אז דער תכלית המכוון אין ירידת הנשמה למטה איז ניט די עליית הנשמה, נאר צו דורכפירן די כוונה פון דירה בתחתונים (כנ״ל סעיף ט׳), דעריבער, איז דער ענין פון „והי׳ ה׳ לי לאלקים״ (אע״פ אז דאס איז אַ תוצאה פון דער עבודה) שייך מער (בפרט אחד — היינו מצד דערויף וואס ס׳איז נאך ניט דער אמת׳ער תכלית) צום „תנאי״ (עבודה) „ושבתי בשלום״ ווי צום תכלית המכוון פון „והאבן הזאת גו׳ יהי׳ בית אלקים״ (דירה בתחתונים).",[["55","55","ראה גם כלי יקר פרשתנו כח, כ שבקשת יעקב „ושמרני גו׳״ היא „על שמירת הנפש מן החטא״."],["56","56","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא ספ״ה</a> (ובכ״מ) שהמצוות הן לבושים והתורה היא (גם) מזון. תנא דבי אלי׳ רבה פכ״ז."],["57","57","ראה גם תו״ח פרשתנו (כו, א־ב) ש„לחם ובגד״ הו״ע תומ״צ, „ושבתי בשלום״ הו״ע התשובה."],["58","58","ויש לומר, שלכן נאמר „ושבתי״ ולא „והשיבני״ (ראה לעיל בפנים ס״ג ובהערות שם) — כי מצד הירידה וההתלבשות בעניני העולם וכו׳, הנתינת כח שמלמעלה היא בהעלם, וכאילו שההשבה היא מעצמו (וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091064\" data-slug=\"likkutei-sichot\" data-id=\"1300091064\">לקו״ש ח״ט ע׳ 64</a> הערה 26). ועפ״ז יובן החידוש ש„ושבתי בשלום״ על „ושמרני״ — גם להפירוש (ראה לעיל הערה 55) ש„ושמרני״ קאי על שמירה מן החטא — כי ענין „ושמרני״ מן החטא הוא באופן ד„תשש יצרו״ (ראה לעיל בפנים ס״ו), שאז נרגש בו ששומרים אותו מלמעלה; והחידוש ב„ושבתי״ הוא שגם כשעוסק בעניני הרשות מצד רצון נפשו הבהמית („לבד״) ואינו מרגיש את הנתינת כח שמלמעלה, מ״מ „ושבתי בשלום — שלם מן החטא שלא אלמד מדרכי לבן״."],["59","59","רש״י פרשתנו כח, כא."]]],[1300151264,"יב. ויש לומר: אויך לויט פירוש רש״י — אז „והי׳ ה׳ לי לאלקים״ איז (ניט דער נדר, נאר) דער תנאי — איז „והי׳ ה׳ לי לאלקים״ אַ פרט (ניט אין עבודת הירידה למטה, נאר) אין דער עלי׳ וואס ווערט דורך דער עבודה, ע״ד ווי לפירוש הרמב״ן\n[וואַרום דער ענין פון „שיחול שמו עלי מתחלה ועד סוף שלא ימצא פסול בזרעי״ (אז שמו של הקב״ה זאל חל זיין ניט נאר אין זיין „תחילה״, נאר אויך אין זיין „סוף״, ביז אפילו אין „זרעי״ וואס קומען ארויס פון אים), קען זיין נאר דורך דעם וואס אין זיין התקשרות מיטן אויבערשטן איז ניטא קיינע הגבלות]:\nאון דאס וואס לפי פירוש רש״י גייט דער ענין („והי׳ ה׳ לי גו׳״) אריין אין „תנאי״ און ניט אין נדר (ווי לפירוש הרמב״ן) איז — ווייל די עלי׳ פון דער נשמה איז נאר אַ הכנה צום (תכלית ה)מכוון פון „והאבן הזאת גו׳ יהי׳ בית אלקים״, דירה בתחתונים.\nיג. ויש לומר, אז דער טעם פארוואס לפירוש רש״י איז „והי׳ ה׳ לי לאלקים״ אַ פרט אין „תנאי״ און לפירוש הרמב״ן איז עס אַ פרט אין „נדר״:\nאין פירוש הרמב״ן זיינען דאָ ניט נאר „פשטים״ נאר אויך „דברים נעימים . . ליודעים חן״60, וואס דאס איז פאַר־בונדן מיט בחי׳ „גילויים״61 — און מצד הגילויים איז אויך די עלי׳ פון דער נשמה אַ תכלית62:\nמשא״כ פירוש רש״י איז פשוטו של מקרא, וואס אין עבודת האדם איז עס די עבודה פון אַן עבד פשוט וואס זוכט ניט קיין תועלת לעצמו63 און ווייל נאר דורכצופירן דעם רצון האדון.\n(ממאמר ד״ה ושבתי בשלום תשל״ח, ומשיחות חורף תשכ״ד)",[["60","60","לשון הרמב״ן בה„פתיחה״ לפירושו עה״ת בסופה."],["61","61","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310045\" data-slug=\"tanya\" data-id=\"3401310045\">תניא (פ״מ</a> בהגה״ה. אגה״ק סכ״ו. תו״א יז, רע״א) מכתבי האריז״ל דקבלה היא באצילות."],["62","62","והגם ששלימות העלי׳ דנשמה הוא שהיא בבחי׳ ביטול בתכלית ועד שכל מציאותו הוא רק לשמש את קונו (ראה לעיל הערה 44) — מ״מ הוא מרגיש עילוי בזה גופא שהוא בטל כו׳. ובדוגמת ה„עבד נאמן״ שעבודתו היא „מצד הרגש העילוי וההפלאה שבאוא״ס״ (המשך תרס״ו ע׳ שכג), אשר עם היותו עבד „רק בשביל להשלים רצונו ית׳ . . ואין כוונתו לעצמו כלל״ (המשך שם), מ״מ הוא חפץ שהשלמת רצון האדון תהי׳ על ידו (המשך הנ״ל ריש ע׳ שכא)."],["63","63","גם לא העילוי דביטול (ראה הערה הקודמת)."]]],[1300151265,"<h3>ויצא ד</h3>\nא. אין דער היינטיקער סדרה ווערט דערציילט מיט א גרויסער אריכות, ווי יעקב אבינו זייענדיק בבית לבן, האט זיך באזונדערס אפגעגעבן מיט „צאן“ — סיי זיין עבודה דארט איז געווען אלס רועה צאן, און סיי דער שכר וואס לבן האט אים פאר דעם געצאלט לבסוף איז גע־ווען מיט צאן:\nאזוי אז זיין (עיקר) רכוש איז געווען צאן און פון דעם איז ער נתעשר גע־ווארן — „ויפרוץ האיש מאד מאד ויהי לו צאן רבות (און דורך דעם צאן האט ער אויך געהאט) ושפחות ועבדים וגמלים וחמורים“¹, ווי רש״י² איז מפרש: „מוכר צאנו בדמים יקרים ולוקח לו כל אלה“³.\nפונדעסטוועגן זעט מען אז אין פ׳ וישלח⁴, ביי דער שליחות פון יעקב צו עשו׳ן, ווערן דארט די פרטי הרכוש פון יעקב אויסגערעכנט מיט דעם סדר: „ויהי לי שור וחמור צאן ועבד ושפחה גו׳“ — „צאן“ נאך „שור וחמור“⁵ — און ניט צאן אלס ראשית ועיקר קנינו; ובפרט אז עס איז אויך ניט ווי פריער, ווען דער פסוק דערציילט ווי יעקב איז אנטלאפן פון לבן׳ען, וואס עס שטייט⁶ „וינהג (פריער) את כל מקנהו (און ערשט דערנאך) ואת כל רכושו גו׳ מקנה קנינו⁷ גו׳“.\nב. יעדער ענין אין תורה, איז א הוראה נצחית פאר יעדער איד׳ן בכל מקום ובכל זמן. ובפרט די „מעשה אבות“ וועלכע ווערן דערציילט אין תורה⁸ — ועל אחת כמה וכמה אן ענין וואס פארנעמט כמעט א גאנצע סדרה — וואס זיינען „סימן לבנים“, א נתינת כח צו דער עבודה פון די „בנים“, בני אברהם יצחק ויעקב.\nדערפון איז פארשטאנדיק, אז די פרטים הנ״ל אין יעקב׳ס פארנעמען זיך מיט צאן\n— (א) אז דוקא „צאן“ האט גע־בראכט דעם „ויפרוץ האיש מאד מאד“; (ב) לאידך, כאטש אז „צאן“ איז געווען עיקר רכושו, האט ער אבער פארביטן (א טייל פון) זיין צאן אויף „שפחות ועבדים וגמלים וחמורים“, (ג) אין זיין שליחות צו עשו׳ן האט ער דערמאנט „צאן“ נאך „שור וחמור“ —\nזיינען דא אין דער עבודה רוחנית פון יעדער אידן.\nג. וועט מען דאס פארשטיין בהק־דים וואס עס שטייט אין מדרש⁹ וועגן דעם פארבונד צווישן אידן מיטן אוי־בערשטן: „הוא לי לאב ואני לו לבן . . הוא לי לרועה . . ואני לו לצאן“. איז ידוע די שאלה אין דעם: וויבאלד אז אידן זיינען ווי א „בן“ צום אויבערשטן, וואס קען דא צוגעבן דאס וואס זיי זיי־נען ווי „צאן“ — ואדרבא, וואס פאר אן ערך האט די חביבות פון צאן ביי זייער רועה לגבי דער חביבות פון א בן ביי זיין אב?",[["1","1","פרשתנו ל, מג."],["2","2","עה״פ."],["3","3","ראה תו״ח פרשתנו (ל, ג)."],["4","4","לב, ו."],["5","5","ראה גם בחיי שם. ועוד."],["6","6","פרשתנו לא, יח."],["7","7","כפרש״י שם: מה שקנה מצאנו עבדים ושפחות וגמלים וחמורים."],["8","8","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051081\" data-slug=\"likkutei-sichot\" data-id=\"1300051081\">לקו״ש ח״ה ע׳ 69</a> ואילך."],["9","9","שהש״ר פ״ב, טז (א)."]]],[1300151266,"שטייט אויף דעם דער ביאור¹⁰, אז היא הנותנת:\nדאס וואס מ׳רופט אן אידן בשם „בנים“, ווייזט אז זיי זיינען א מציאות לגבי דעם „אב“ (דעם אויבערשטן): און אע״פ אז דער פארבונד פון א נשמה מיטן אויבערשטן איז ניט ווי א „בן“ למטה וואס „נהי׳ מהות בפ״ע“ פון דעם אב, נאר די נשמה איז „כולא חד (מיטן אויבערשטן) ואינה נפרדת ממנו ית׳ כלל“¹¹ — איז דאך אבער דער עצם תואר „בן“ א באווייז, אז דאס איז כאילו ווי א צווייטע מציאות (ניט דער „אב“), און זיין מציאות וחביבות האט אן ערך ותפיסת מקום ביים אב — וואס דאס קען מען זאגן נאר לגבי דעם אור אלקי פון סדר השתלשלות¹², וואס איז א שורש ומקור אויף נבראים, און דער־פאר זיינען זיי דארט תופס מקום.\nאבער לגבי דעם אור אלקי שלמעלה מהשתלשלות, איז — „גם בן ואח אין לו“¹³ — עס איז ניט שייך צו זאגן אז ס׳איז דא וועלכע ס׳איז מציאות אויסער אים; און לגבי אים ווערן אידן (וחביבו־תם) פארגליכן צו צאן, וואס זייער מציאות (ווי אויך זייער חביבות) האט ניט קיין ערך לגבי דעם מהות פון רועה.\nאבער לאידך גיסא, איז דאס גופא א באווייז אויפן גודל העילוי פון אידן, אז אויך אין דער דרגא פון אלקות וואו ס׳איז ניטא קיין נתינת מקום אויף דער מציאות פון נבראים — „גם בן ואח אין לו“ — אויך „דארטן“ איז דא די חביבות צו אידן¹⁴:\nנאר די חביבות זייערע איז ניט מצד זייער „מציאות“, נאר פארקערט — מצד זייער עצם הביטול צום אויבערשטן, וואס דוקא דער ביטול איז א כלי צום אור אלקי שלמעלה מהשתלשלות, כמש״נ¹⁵ „מרום וקדוש אשכון ואת דכא ושפל רוח“.\nאון אויך דער ענין — דער עצם הביטול — איז מרומז אין דעם וואס אידן זיינען געגליכן צו צאן. ווארום, ווי מ׳זעט במוחש, איז אין צאן דא די טבע הביטול מער ווי בא אנדערע מיני בהמה¹⁶.\nד. די צוויי תוארים פון אידן — „בן“ און „צאן“ — זיינען מרמז אויף צוויי אופנים אין עבודת האדם¹⁷:\nבחי׳ בן איז די עבודה פון לימוד התורה, וואס עיקרה איז — די הבנה והשגה שבמוח (אין וועלכער דער אדם הלומד פילט זיך אלס א מציאות — ער נעמט תורה דורך זיין פארשטאנד).\nאון אע״פ אז כדי ער זאל בלימודו מכוון זיין צו אמיתתה של תורה, צו חכמתו ית׳, מוז ער שטיין אין א תנועה",[["10","10","לכללות סעיף זה — ראה אוה״ת ראה ע׳ תשפד־ה. ע׳ תשצה ואילך."],["11","11","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380970\" data-slug=\"likkutei-torah\" data-id=\"4001380970\">לקו״ת ר״ה סב, ד</a>."],["12","12","להעיר גם מדרמב״ם (ד, א־ב) דענין היחוד והזיווג לא יתכן למעלה מאצילות, ע״ש."],["13","13","קהלת ד, ח."],["14","14","עד שההמלכה על כללות הבריאה היתה בנשמותיהן ש״י (ראה ב״ר פ״ח, ז. רות רבה פ״ב, ג. וראה לקו״א ואוה״ת להה״מ בתחלתן. נת׳ ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161499\" data-slug=\"likkutei-sichot\" data-id=\"1300161499\">לקו״ש חט״ז ע׳ 486</a>)."],["15","15","ישעי׳ נז, טו."],["16","16","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380234\" data-slug=\"likkutei-torah\" data-id=\"4001380234\">לקו״ת אמור לז, סע״א</a> ואילך. תו״ח פרשתנו לא, ב. וישלח מא, רע״א. אוה״ת וישלח רכח, ב. אוה״ת ראה שם (ע׳ תשצו)."],["17","17","לכללות סעיף זה — להעיר ממשנ״ת (לקו״ש חי״ב ע׳ 333 ואילך) בביאור מרז״ל (ב״ר פ״ס, ח. פרש״י ח״ש כד, מב) „יפה שיחתן של עבדי בתי אבות מתורתן של בנים“. ולהעיר מאוה״ת ראה שם ע׳ תתא (ושם, שצאן הו״ע עסק התפלה. וראה בלקו״ש ח״ב שם ע׳ 331 הערה 62)."]]],[1300151267,"פון ביטול — דוקא דורך „ונפשי כעפר לכל תהי׳“ קען זיין „פתח לבי בתורתך“¹⁸ (וכידוע בענין „ברכו בתורה תחלה“¹⁹) — איז דאס נאר וואס דער ביטול איז א יסוד והקדמה צו לימוד התורה; אבער דער לימוד התורה גופא איז דאך (ניט מיט ביטול, נאר פאר־קערט) מיטן כח השכל דוקא.\n„צאן“ ווייזט אויף דער עבודה פון „בירורים“. „צאן“ איז פון לשון „יציאה“²⁰ — „ארויסגיין“ פון די ד׳ אמות של תורה און פארנעמען זיך מיט עניני העולם צו מאכן פון זיי א דירה לו ית׳ בתחתונים.\nאון דוקא די עבודה ברענגט ארויס דעם אמת׳ן ביטול פון א אידן צום אוי־בערשטן — די יציאה („צאן“) פון זיין מציאות. ווארום דאס איז אן עבודה וואס א איד טוט זי ניט צוליב זיך, צוליב זיין שלימות און עלי׳\n(ווארום, אדרבה, דער עצם פאר־נעמען זיך מיט עניני העולם איז א ירידה פאר אים, ער דארף מפסיק זיין פון לימוד התורה, אין וועלכן עס זיינען אריינגעטאן זיינע העכערע און איידלערע כחות הנפש, און זיך מתעסק זיין אין עניני עשי׳)\nנאר בלויז כדי צו אויספירן דעם אויבערשטנ׳ס כוונה, לעשות לו ית׳ דירה בתחתונים²¹.\nה. דערמיט וועט מען פארשטיין דעם קשר ושייכות פון ענין הצאן צו עבודתו של יעקב בבית לבן.\nדער חילוק צווישן עבודת יעקב אין דעם זמן וועגן וועלכן עס רעדט זיך אין פ׳ תולדות און עבודתו ווי זי ווערט ארויסגעבראכט אין פ׳ ויצא²²:\nאין פ׳ תולדות רעדט זיך וועגן דער צייט וואס עבודת יעקב איז געווען בבחי׳ „בן“ — „ויעקב איש תם יושב אהלים“, „אהלו של שם ואהלו של עבר“²³; און אויך בסוף הסדרה, וואו עס ווערט דערציילט אז יעקב האט געמוזט אנטלויפן פון בית אביו, איז ער ניט אוועק פון אהלה של תורה, נאר אדרבה, „נטמן בבית עבר י״ד שנה“²⁴ און דארט געלערנט תורה.\nאין פ׳ ויצא אבער רעדט זיך וועגן דעם ווי ויצא יעקב, ער איז ארויס פון די ד׳ אמות של תורה און איז אנגעקומען קיין חרן — חרון אף של מקום בעולם²⁵, אין בית לבן הארמי; און דארט האט ער געארבעט אלס רועה פון צאן לבן (אויך) כפשוטו, און אין אן אופן פון „בכל כחי עבדתי גו׳“²⁶ (ביז אז מ׳לערנט אפ²⁷ פון יעקב׳ן ווי אזוי א פועל דארף ארבעטן פאר זיין בעה״ב);\nאון דוקא די עבודה — אז ניט קוקנ־דיק אויף דעם גודל ההעלם וההסתר",[["18","18","ברכות יז, א. אלקי נצור כו׳."],["19","19","נדרים פא, א. ב״מ פה, ריש ע״ב. נת׳ לעיל ע׳ 3 ואילך. וש״נ. ובכ״מ."],["20","20","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370109\" data-slug=\"torah-or\" data-id=\"3901370109\">תו״א פרשתנו כג, ג</a>. תו״ח פרשתנו לה, ב. שם ר״פ וישלח. אוה״ת שם רכח, א."],["21","21","ראה עד״ז לעיל ע׳ 247 והערה 34. וראה שם (ע׳ 248־9), שעילוי זה בהנשמה (מה שע״י עבודת הבירורים מגעת לבחי׳ הביטול) — נוגע להשלמת הכוונה דדירה בתחתונים. כי כדי שעבודת האדם תפעל שהתחתונים יהיו דירה לו ית׳, לו לעצמותו — שזהו מצד זה שדוקא בעוה״ז ישנו הביטול ד„אין עוד“ — צ״ל העבודה בביטול לגמרי, מעין הביטול ד„אין עוד“, ע״ש."],["22","22","בהבא לקמן — להעיר מתו״ח תולדות ד״ה ויתן לך פ״כ ואילך."],["23","23","תולדות כה, כז. ב״ר ופרש״י עה״פ."],["24","24","פרש״י ס״פ תולדות. מגילה טז, סע״ב ואילך. סדר עולם פ״ב."],["25","25","רש״י ס״פ נח."],["26","26","פרשתנו לא, ו."],["27","27","רמב״ם הל׳ שכירות בסופן. שו״ע אדה״ז חו״מ הל׳ שאלה ושכירות סעיף כ."]]],[1300151268,"בבית לבן, איז יעקב ניט נתפעל גע־ווארן, און „עם לבן הרשע גרתי, ותרי״ג מצות שמרתי“²⁸, און ער האט דארט אויפגעשטעלט די שבטים שבטי י־ה אין אן אופן פון „מטתו שלימה“²⁹ — די עבודה האט ארויסגעבראכט דעם תכלית הביטול פון יעקב׳ן.\nוי״ל אז דאס איז דער טעם (פנימי) וואס דער עיקר פונעם רכוש וואס יעקב האט פארדינט און מיטגענומען פון בית לבן איז געווען דוקא צאן — ווייל אין „צאן“ איז מרומז דער עילוי רוחני צו וועלכן ער איז צוגעקומען דורך עבודתו בבית לבן — דער ענין הביטול³⁰, כנ״ל.\n[און דאס איז אויך דער דיוק הלשון „ויפרוץ האיש מאד מאד“ — פון לשון פורץ גדר — ווייל דורך ביטול (צאן) איז מען פורץ די גדרים פון סדר השתל־שלות און מען קומט צו צום אור אלקי וואס האט ניט קיינע הגבלות — „מאד מאד“ (ב׳ פעמים „מאד“)³¹:\nביז — ווי חסידות³² טייטשט אפ די פסוקים³³ „והחליף את משכורתי עשרת מונים גו׳ אם כה יאמר נקודים יהי׳ שכרך גו׳ עקודים גו׳“ למעליותא — אז יעקב בעבודתו האט ממשיך געווען „עצמות רצון המאציל“ וואס איז העכער פון התחלקות וציור, און דערפאר האט זיין שכר געקענט נחלף ווערן פון איין ציור צום צווייטן].\nו. כשם ווי אין דער עבודה פון „בן“, וואס ענינה איז מיט הבנה והשגה („מציאות“), מוז אויך זיין דער ענין הביטול (כנ״ל ס״ד) — עד״ז איז אויך לאידך גיסא, אז אין דער עבודה פון „צאן“, וואס (עיקרה) איז ביטול, מוזן זיין (די פעולות פון) אלע כחות הנפש, זיין „מציאות“;\nואדרבה: מיט ביטול ושפלות אליין קען מען ניט לוחם זיין קעגן דעם העלם והסתר העולם, נאר עס מוז זיין — ווי די הוראה אין אנהויב פון אלע פיר חלקי הטור (ושו״ע³⁴) — „עז כנמר כו׳ גבור כארי“, אז מ׳דארף נוצן די מדת העזות³⁵ „שלא להתבייש מפני בני אדם המלעי־גים“, און די מדת הגבורה „להתגבר³⁶ על יצרו לנצחו כגבור המתגבר על שונאו לנצחו ולהפילו לארץ“³⁷.\nנאר דערביי דארף מען זיך באווארענען, אז דאס זאל געטאן ווערן אלס תוצאה פון זיין ביטול צום רצון העליון. אויב די גבורה וכו׳ איז מצד זיין אייגענער ישות, איז\n(נוסף אויף דעם, וואס ווען מ׳איז לוחם מיטן תוקף פון דער אייגענער מציאות, קען מען ניט וויסן ווער וועט מנצח זיין די מלחמה, ס׳איז מעגליך אז",[["34","34","אדה״ז במהדו״ת. — משא״כ במחבר ושו״ע אדה״ז מהדו״ק שם: יתגבר כארי כו׳. וברמ״א שם (ושו״ע אדה״ז שם ס״ג) „ולא יתבייש כו׳“ (ולא הזכיר ענין העזות. אלא שבשו״ע אדה״ז שם מסיים „ומ״מ לא יענה דברי עזות כו׳“, כבהערה הבאה). ואכ״מ."],["35","35","אלא ש„לא יענה דברי עזות כו׳ שלא יקנה קנין בנפשו כו׳“ (שו״ע אדה״ז שם. מבי׳ שם). ולהעיר ממרז״ל שישראל עזין שבאומות (ביצה כה, ב)."],["36","36","לשון אדה״ז במהדו״ת שם."],["37","37","להעיר גם מ„ויגבה לבו בדרכי ה׳“ (דה״ב יז, ו. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370411\" data-slug=\"torah-or\" data-id=\"3901370411\">תו״א צא, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370533\" data-slug=\"torah-or\" data-id=\"3901370533\">קיט, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380370\" data-slug=\"likkutei-torah\" data-id=\"4001380370\">לקו״ת במדבר טו, ג</a>. ובכ״מ)."],["28","28","וישלח לב, ה וברש״י שם."],["29","29","ויק״ר פל״ו, ה. פרש״י ויחי מז, לא. וראה פסחים נו, א. ספרי ואתחנן ו, ד. ועוד."],["30","30","וראה בארוכה תו״ח פרשתנו (ל, ג ואילך) — השייכות למדתו של יעקב דוקא, מדת הרחמים."],["31","31","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370109\" data-slug=\"torah-or\" data-id=\"3901370109\">תו״א פרשתנו כג, ג</a>. תו״ח וישלח לט, ד."],["32","32","תו״א סוף פרשתנו. תו״ח פרשתנו לח, א־ב."],["33","33","פרשתנו לא, ז־ח."]]],[1300151269,"דער צד שכנגד האט אין זיך מערער פון דעם סוג עזות און שטארקייט — איז)\nדאס היפך הקדושה, ובמילא קען אזא הנהגה ניט זיין קיין ריכטיגער סיוע אין זיין מלחמה מיט מלעיגים און מנגדים לתורה ומצות,\nדוקא ווען ער פירט זיך אזוי דער־פאר וואס אזוי האט אים תורה געהייסן, דאן איז דאס די עזות וגבורה וואס איז מנצח דעם מנגד.\nויש לומר, אז דאס איז אויך דער טעם פנימי וואס דער טור (און אזוי אויך דער אלטער רבי בשולחנו³⁸) ברענגט אויך דעם נאמען פון דעם בעל המאמר „עז כנמר כו׳“ — „יהודה בן תימא“:\nדאס קומט צו מרמז זיין³⁸*, אז די הוראה פון „עז כנמר כו׳“ איז א הנהגה ראוי׳ ווען זי קומט פון „יהודה בן תימא“ — יהודה מלשון הודאה, די עבודה פון הודאה וביטול³⁹; און ס׳איז ניט מספיק אז דער ביטול זאל זיין בלויז ווי א הקדמה בתחילת העבודה, נאר דער „יהודה“ דארף זיין „בן תימא“ — דער ביטול דארף זיך (נאכאנאנד) „ארויס־זאגן“ אין דער הנהגה פון „עז כנמר כו׳“⁴⁰. ווארום ווייבאלד אז מען שטייט אין דער תנועה פון עזות וגבורה קען\nמען אריינפאלן אין פשוט׳ער עזות פון ישות ח״ו⁴¹.\nז. און דאס איז דער ביאור אין די פרטים הנ״ל (סעיף א׳ וב׳) אין צאן יעקב:\nאע״פ אז כללות עבודתו (ורכושו) איז געווען צאן (ביטול), כנ״ל, האט ער זיך אבער דערמיט ניט באנוגנט, נאר ער האט אויך אריינגענומען אין זיין רכוש „שפחות ועבדים וגמלים וחמורים“ — ווייל כדי צו דורכפירן כדבעי די עבודה הבירורים, (ובפרט דערנאך די בירורים פון עשו), זיינען נויטיק אלע פאר־שידענע פרטי ואופני העבודה (וועלכע זיינען מרומז אין די ענינים הנ״ל⁴²).\nנאר אין דעם זיינען געווען צוויי בא־ווארענישן:\nא) די הגדלת הרכוש מיט די פרטים נוספים האט יעקב קונה געווען מיט און דורך דעם (אומבייט פון דעם) צאן — זיי זיינען ניט געקומען ווי אן עבודה פאר זיך, נאר אלס תוצאה פון עבודת הביטול.\nב) אויך נאכדעם האט ער ניט פאר־קויפט דעם גאנצן צאן און פארביטן מיט אנדערע קנינים, נאר אדרבה, דער צאן איז אויך דעמאלט געבליבן עיקר רכושו. ווארום אויך ווען מ׳איז אריינגעטאן אין דער מלחמה מיטן העלם והסתר העולם, וואס פאדערט תוקף וגבורה כו׳, מוז בלייבן דער הרגש הביטול און ענין עיקרי.\nח. עפ״ז איז אויך פארשטאנדיק וואס אין דער שליחות צו עשו׳ן ווערט דער",[["38","38","בטור דרכו להביא מרז״ל בשם אומרם. אבל אי״ז דרכו של אדה״ז בשולחנו. 38*) ידוע הרמז דמתחיל ביהודה, דשם הוי׳ בו (ראה סוטה י, ב. לו, ב), שהוא בן תימא (דכל התורה)."],["39","39","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370199\" data-slug=\"torah-or\" data-id=\"3901370199\">תו״א ר״פ ויגש (מד, א</a>) ור״פ ויחי."],["40","40","ויש לומר שבזה דוקא מתבטא אמיתית ענין הביטול, שלמעלה ממדידה והגבלה, שלכן גם התנועה דעזות (שבחיצוניות הוא היפך ענין הביטול) אינה בסתירה להביטול. *) להעיר מקה״י ע׳ יהודה בן תימא: תמא אותיות אמת חתן אמת ליעקב."],["41","41","שלכן צ״ל זהירות „שלא יענה דברי עזות כו׳“ (ראה לעיל הערה 35)."],["42","42","ראה תו״א ר״פ וישלח. תו״ח שם מב, ד."]]],[1300151270,"פרט פון „צאן“ ניט געשטעלט אלס ערשטער פון די אויסגערעכענטע פרטי הרכוש — כאטש אז דאס איז געווען עיקר רכושו:\nמיט זאגן „ויהי לי שור וחמור צאן ועבד ושפחה“ האט יעקב געוואלט דער־מאנען די זכיות⁴³ און כוחות נעלים וואס וועלן אים ביישטיין, און דערמיט אפ־שרעקן עשו׳ן פון צו טאן וואס עשו האט געוואלט טאן.\nאון דעריבער האט ער ניט מקדים געווען דעם פרט פון צאן, וואס ווייזט אויף טבע הביטול והשפלות וההכנעה — ווייל כדי צו אפשרעקן עשו׳ן, דארף ער (עשו) בעיקר און צום אלעם ערשטן דערהערן דעם תוקף פון יעקב⁴⁴; ער דארף טאקע וויסן אז ביי יעקב איז דא צאן — ד.ה. ענין הביטול, ובמילא איז זיין תוקף ניט קיין אייגענער, נאר ס׳איז א תוקף דקדושה — אבער מיט וואס שרעקט מען אים אפ — מיט תוקף.\nדאס איז אבער נאר בנוגע צו דעם וואס דער צד שכנגד דארף דערהערן. פאר זיך אליין דארף מען וויסן און געדענקען דעם אמת, אז דער תוקף איז א תוצאה פון ביטול, ואדרבה — דער עיקר רכוש פון א אידן איז צאן דוקא.\nט. די איינפאכע הוראה פון כל הנ״ל (בדורנו זה) איז: עס מוז זיין דער סדר עבודה פון „ויצא“ — ארויסגיין און ליכטיק מאכן די וועלט. מען דארף און מען מוז פריער האבן די הכנה פון לימוד התורה באהלי שם ועבר, מ׳דארף אבער צוקומען צו „ויפרוץ האיש מאד\nמאד“, מלאו את הארץ וכבשוהו⁴⁵, מוז מען ארויסגיין אין „ארץ“ און פאר־נעמען זיך מיט באלייכטן די וועלט⁴⁶.\nואדרבה, „בעתים⁴⁷ הללו בעקבתא משיחא“ איז דער עיקר העבודה דוקא אין עשי׳, משא״כ בזמן הש״ס ווען עס איז געווען אין תלמוד תורה⁴⁷, ע״ד דעם פסק דין אין שו״ע⁴⁸, אז היינטיקע צייטן איז ניטא די מציאות פון „תורתו אומנתו“ (די דרגא פון רשב״י וחביריו), אפילו ניט ביי א מיעוט פון אידן — ווייל עיקר העבודה בזמן הזה איז אין עשי׳, מעשה הצדקה.\nובפרט בדורנו זה, וואס אט די התעס־קות — צו אויפזוכן אידן וואס בלאנדזשען אין חושך הגלות און זיי אוועקשטעלן בקרן אורה פון נר מצוה ותורה אור — באשטייט ניט אזוי בעיקר אינעם אויפטו צו מאכן פון אן עם הארץ א למדן, פון א קלענערן א גרעסערן, פון א מקיל במצות א ירא־שמים בתכלית, נאר אין דעם ענין פון הצלת נפשות ממש!\nמען איז מציל דעם נפש פון דעם אידן ובניו כו׳, עד סוף כל הדורות, אז זיי זאלן בלייבן אידן און פירן זיך (אנ־הייבענדיג עכ״פ בנוגע למעשה) ווי א איד דארף זיך פירן.\nיו״ד. נאך א נקודה אין דעם: כדי אז די עבודה זאל זיין בהצלחה רבה, מוז עס געטאן ווערן מתוך ביטול; מ׳דארף עס טאן כדי צו אויספירן די שליחות פון אויבערשטן צו באלייכטן דעם חושך הגלות.",[["43","43","ראה ב״ר פע״ה, ו. שם, יב. יפה תואר שם. וראה אלשיך ומגלה עמוקות עה״פ ויהי לי שור גו׳. ועוד."],["44","44","להעיר גם מתו״ח וישלח מ, סע״ד."],["45","45","בראשית א, כח."],["46","46","ראה גם לקו״ש ח״ג ע׳ 788 ואילך."],["47","47","אגה״ק סי״ס ט."],["48","48","ראה טושו״ע ואדה״ז או״ח סי״ס קו."]]],[1300151271,"בשעת מען טוט די עבודה מתוך ביטול, איז זי ניט אויסגעמאסטן לויט די מדידות והגבלות פון טבע און געשמאק; ס׳איז בא אים ניטא קיין גרויסע נפק״מ וואוהין דער אויבערשטער שיקט — אין יעדער ארט ומצב וואו די השגחה עליונה פירט, און בא יעדן סוג אידן מיט וועלכע ער קומט אין פארבינדונג, לייגט ער זיך אריין מיט אלע כוחות און בכל התוקף צו אויפשטעלן „תלמידים הרבה“⁴⁹, למעלה ממדידה והגבלה, אין אן אופן פון „ויפרוץ האיש מאד מאד“.\nאון בשעת מען גייט מיט דער הנחה אז מ׳דארף אויספירן דעם אוי־בערשטנ׳ס שליחות, איז מען מצליח מיט אלע סוגי תלמידים — „אם כה יאמר נקודים גו׳“ און „אם כה יאמר עקודים גו׳“, איז — „וילדו כל הצאן גו׳“, אלע תלמידים וואקסן אויס כדבעי, און נאכמער „פרות ורבות יותר משאר צאן“⁵⁰, און ס׳איז „מטתו שלימה“ — ס׳איז ניטא קיין דופי ח״ו אין בניו־תלמידיו.\nאון דאס גרייט צו יעדן איד און אלע אידן צו דער גאולה האמיתית והשלימה, וואס בא דער גאולה וועט קיין איין איד ניט בלייבן אין גלות, ווי דער יעוד „ואתם תלוקטו לאחד אחד בני ישראל“⁵¹, און „קהל גדול ישובו הנה“⁵², בקרוב ממש.\n(משיחת י״ד כסלו תשל״ז)",[["49","49","אבות פ״א מ״א. וראה לקו״ש ח״ד ע׳ 1180."],["50","50","פרש״י פרשתנו ל, מג."],["51","51","ישעי׳ כז, יב. וברש״י נצבים (ל, ג): אוחז בידיו ממש איש איש ממקומו."],["52","52","ירמי׳ לא, ז."]]],[1300151272,"<h3>ויצא ה</h3>\nא. עס איז ידוע דער פתגם פון רבותינו נשיאינו¹ אז באלד נאך שמח״ת (ושבת בראשית)² הויבט זיך אָן דער סדר העבודה פון ״ויעקב הלך לדרכו״³ — א איד גייט צו זיין דרך (וסדר העבודה) פון דעם גאנצן יאר.\nאון ווי גערעדט שוין כמה פעמים⁴ דער ביאור אין דעם: במשך חודש תשרי זיינען אידן פארנומען בעיקר מיט עניני קדושה (די ימים טובים ומצות שבהם און די הכנות צו זיי); נאכן חודש תשרי גייט מען אריין אין וואכעדיקע טעג און וואכעדיקע ענינים — רוב טעג זיינען ימי החול וואס אין זיי זיינען די מערסטע אידן פארנומען מיט עסק הפרנסה וכו׳.\nאון אט דער איבערגיין פון דער עבודה פון חודש תשרי צו דער עבודה פון כל השנה איז מרומז אין ״ויעקב הלך לדרכו״, וואס די הדגשה פון ווארט ״לדרכו״ — צו זיין וועג — אנטהאלט אין זיך א תוכן פון צוויי קצוות: פון איין זייט ווערט דערמיט אנגעדייט, אז דער וועג, אויף וועלכן א איד גייט אין דער\nוואכעדיקייט פון גאנצן יאר נאך תשרי, איז ניט ווי דער וועג פון חודש תשרי, נאר ״דרכו״ — זיין (דעם מענטשס) וועג: דעם גרעסטן טייל פון טאג איז א איד פארנומען מיט פרנסה, עסן און טרינקען און שלאפן⁵ א.א.וו. — און אין דעם וועג זעט זיך ניט (בגלוי) קיין היילייקייט. אין דעם איז, לכאורה, ניטא קיין אונטערשייד צווישן א אידן און א ניט־אידן.\nלאידך, אין דעם זעלבן ווארט ״לדרכו״ ווערט אונטערגעשטראכן אז דער וועג אין וועלכן דער איד גייט במשך דעם גאנצן יאר איז ״דרכו״: זיין וועג — יעקב (אבינו)ס באזונדער דרך, וואס ער האט אויסגעטראטן פאר אלע אידן; ד.ה. אויך דער וואכעדיקער דרך פון א אידן, זיין גאנג און אויפפירונג במעשיו, במאכלו ובמשקהו כו׳ ובמשאו ובמתנו וכו׳⁶, איז אנדערש ווי ביי א ניט איד, להבדיל, ס׳איז אין א אידישן אופן, אין אן אופן פון ״לשם שמים״⁷ און ״בכל דרכיך דעהו״⁸.\nאון דערמיט איז אויך פארשטאנדיק די שייכות פון ״ויעקב הלך לדרכו״ צום זמן פון חודש תשרי — און מ׳איז מכריז (כידוע המנהג בכ״מ) ״ויעקב הלך לדרכו״⁹ — ווארום די נתינת כח וואס א",[["1","1","ראה שיחות: שמחת תרפ״ו. שמחת תרצ״ז (אות יג). אחש״פ תרצ״ה (סה״מ תיש״א ע׳ 240). יום שמחת תרצ״ט. ליל א׳ דחגה״ש תש״ח (סה״מ תש״ט ע׳ 173)."],["2","2","ראה הלשונות בשיחות הנ״ל. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201266\" data-slug=\"likkutei-sichot\" data-id=\"1300201266\">לקו״ש ח״כ ע׳ 266</a> ואילך הדרגות והזמנים. ועיקר הענין ד״לדרכו״ בעניני הרשות המבואר לקמן הוא במוצאי שבת בראשית. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201295\" data-slug=\"likkutei-sichot\" data-id=\"1300201295\">לקו״ש שם ע׳ 282</a> הערה *15. וראה לקמן הערה 35."],["3","3","פרשתנו לב, ב."],["4","4","ראה שיחת מוצש״ק בראשית תשל״ה (נדפסה בלקו״ש ח״ט בתחילתו). לקו״ש שנסמנו בהערה 2."],["5","5","בימות החול שאינו דומה להאכרש דשוויט״ט."],["6","6","להעיר מרמב״ם הל׳ דיעות רפ״ה. לקו״ד ח״ג תכא, א ואילך. תרה, א ואילך."],["7","7","אבות פ״ב מי״ב."],["8","8","משלי ג, ו. וראה רמב״ם שם ספ״ג. טושו״ע אור״ח סרל״א."],["9","9","ראה לקו״ש ח״כ <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201266\" data-slug=\"likkutei-sichot\" data-id=\"1300201266\">שם (ע׳ 266</a> ואילך) שהוא הנתינת כח כו׳ להעבודה."]]],[1300151273,"איד האט, צו קענען אויפטאָן אז אין ״דרכו״, אין זיינע וואכעדיקע ענינים¹⁰, זאל זיך אנזען און דערפילט ווערן אז דאס איז ״דרכו״ — דער ספּעציעלער וועג פון א אידן — נעמט זיך פון דער קדושה ותומ״צ וועלכע א איד שעפט אָן במשך פון חודש תשרי, חודש הכללי.\nב. די רייד פון רבותינו נשיאינו זיינען מדוייק בתכלית הדיוק, ובמילא דארף מען זאגן, אז דאס וואס דער אוועקגיין פון חודש תשרי אינעם דרך וסדר העבודה במשך השנה איז מתואר מיט די ווערטער ״ויעקב הלך לדרכו״, איז דאס ניט בלויז דערפאר וואס אין די ווערטער איז מרומז די עבודה, נאר ווייל דער דרך וסדר העבודה הנ״ל איז אויך בהתאם צו דעם ענין וסופו, וואו די ווערטער ווערן געזאגט בתורתנו תורת חיים (הוראה בחיים), בפרשתנו בקשר מיט ״ויעקב הלך לדרכו״.\nאיז ניט מובן: דער פסוק ״ויעקב הלך לדרכו״ רעדט וועגן יעקב׳ס גיין פון חו״ל, פון ״חרן״ — ״חרון אף של מקום בעולם״¹¹, קיין ארץ ישראל, ארץ הקודש; קומט אויס, אז די הליכה פון ״יעקב לדרכו״¹² ווי דאס איז מתואר אין פסוק, איז בסדר ותוכן הפכי פון דער הליכה הנ״ל פון א אידן (פון עניני קדושה (חודש תשרי) צו עובדין דחול (די עבודה פון כל השנה))¹³?\nג. דער ביאור אין דעם: דער פסוק ״ויעקב הלך לדרכו״ קומט בסיום סיפור המעשה ווי יעקב איז אנטלאפן פון לבן, ווי לבן האט אים נאכגעיאגט, און די טענות און איבעררייד צווישן יעקב און לבן¹⁴, ביז אז ״וישכם לבן בבוקר וינשק לבניו ולבנותיו ויברך אתהם וילך וישב לבן למקומו ויעקב הלך לדרכו גו׳״¹⁵. ד.ה. אז ״ויעקב הלך לדרכו״ קומט ניט בהמשך צו עבודת יעקב בבית לבן, נאר נאכדעם ווי ער איז שוין אוועק פון בית לבן בחרן, און לבן איז אים נאכגעלאפן.\nאון אין דעם באשטייט די שייכות צווישן ״ויעקב הלך לדרכו״ (אין אונזער פרשה) צו דער הכרזה פון ״ויעקב הלך לדרכו״ בסיום חודש תשרי: דער ענין פון רדיפת לבן וכו׳ בפנימיות הענינים, איז די נתינת כח צו יעקב׳ן אז ער זאל קענען בייקומען עשו׳ן (ווי דערציילט אין דער ווייטערדיקער פרשה וועגן די הרפתקאות פון יעקב׳ן ביים באגעגענען זיך מיט עשו׳ן), וואס דאס איז דער בירור פון עשו׳ן; און דאס איז ע״ד ווי די נתינת כח פון חודש תשרי אויף דער עבודת הבירורים פון כל השנה כולה.\nד. וועט מען דאס פארשטיין בהקדים דעם ביאור פון מעזריטשער מגיד¹⁶, אז דער טעם (בפנימיות הענינים) וואס לבן האט נאכגעיאגט יעקב׳ן איז: לפי שיעקב אבינו השאיר אחריו אותיות התורה שעדיין לא הוציא אותם מלבן ולזאת רדף לבן אחר יעקב ליתן לו את האותיות שנשארו אצלו",[["10","10","ובפרט ימי החול דימי החורף, כחצי שנה בלא רגלים (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381120\" data-slug=\"likkutei-torah\" data-id=\"4001381120\">לקו״ת ברכה צח, ב</a>). ואז העבודה קשה יותר מבימות החמה — ראה סה״מ — מלוקט ח״א ע׳ קנז. לקמן ע׳ 382. וש״נ."],["11","11","פרש״י ס״פ נח (ובכמה דפוסים ליתא תיבת ״בעולם״). וראה זח״א קמו, א."],["12","12","להעיר מאלשיך וישלח לב, ד."],["13","13","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201310\" data-slug=\"likkutei-sichot\" data-id=\"1300201310\">ע״פ</a> מה שנתבאר בד״ה ויאמר ה׳ כו׳ לך לך תשל״ח ס״ג (נדפס בלקו״ש ח״כ ע׳ 297. סה״מ — מלוקט שם ע׳ רפג). יש בהעבודה ד״ויעקב הלך לדרכו״ גם הליכה מלמטה למעלה אבל הפי׳ העיקרי ה״ה כנ״ל בפנים הליכה מלמעלה למטה."],["14","14","פרשתנו לא, יז ואילך."],["15","15","שם לב, א־ב."],["16","16","אור המאיר הובא ונתבאר ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480076\" data-slug=\"or-hatorah-hb\" data-id=\"8316480076\">אוה״ת</a> פרשתנו (כרך ה) תתסט, א ואילך."]]],[1300151274,"וניתוסף פרשה א׳ בתורה באלו האותיות¹⁷.\nאיז ניט מובן¹⁸: די ״אותיות התורה״ וואס יעקב האט איבערגעלאזן ביי לבן׳ען, זיינען דאך ניצוצות קדושה וואס האבן זיך געפונען בא לבן׳ען, היינט וויבאלד אז דער תכלית וואס יעקב האט זיך צוואנציק יאר געפונען בבית לבן איז געווען צוליב מברר זיין דארט די ניצוצות הקדושה — איז פארוואס האט ער די ניצוצות איבערגעלאזן און זיי ניט מברר געווען? און די העלאה זייערע איז געווען דוקא דורך לבן׳ס ״וירדף אחריו״?\nאיז פון דעם גופא מוכח, אז אין די ניצוצות קדושה, וואס זיינען געווען אין לבן׳ס רשות, זיינען געווען צוויי סוגים: א) ניצוצות וואס יעקב מיט זיין עבודה דארט האט זיי געקענט מברר זיין; ב) אזעלכע ניצוצות, וואס זייער בירור האט ניט געקענט זיין דורך יעקב׳ס עבודה אליין, נאר דורך לבן׳ס רדיפה נאך יעקב׳ן.\nע״ד דוגמא ווי עס זיינען פאראן צוויי סוגי מצוות: א) ״סתם כל המצוות״, ווי סוכה, לולב¹⁹ אד״ג, וואס זייער קיום איז\nאפהענגיק פונעם מענטשנס דעת ורצון — די מצוה ווערט דורכגעפירט דורך דעם וואס דער מענטש וויל און האט אין זינען צו טאן די מצוה; ב) מצוות וואס זיינען ניט תלוי אין רצון ודעת האדם, ואדרבה, זייער קיום איז דוקא שלא מדעתו ווי די מצוה פון שכחה וכה״ג (ע״ד ווי ס׳איז מבואר אויך בנוגע צו ״כבוד״ און ״גדולה״²⁰).\nאון דער טעם פנימי פון דעם חילוק איז: די מצוות וואס זיינען פארבונדן מיט דעת ורצון האדם, זיינען מושרש למעלה אין דער דרגא פון כתר, אריך אנפין וואס איז די בחי׳ פון רצון העליון — און דערפאר זיינען זיי אויך למטה פארבונדן מיט דעת ורצון המקיים און דורך זיין עשי׳ איז ער ממשיך פון רצון העליון; משא״כ די מצוות וואס זייער קיום איז דוקא שלא מדעת, ווי שכחה הנ״ל, זייער שורש איז אין בחי׳ תחתונה שבמאציל (וואס איז העכער פון רצון) — און דערפאר זיינען זיי אויך למטה העכער פון צו זיין געבונדן מיט דעת ורצון האדם, כמבואר בלקו״ת²¹.\nעד״ז וועט זיין פארשטאנדיק אויך בנוגע צו די צוויי סוגי ניצוצות וואס זיינען געווען ביי לבן׳ען: די ניצוצות וואס יעקב האט מברר געווען במשך זיין געפינען זיך ביי לבן׳ען, זיינען געווען פון דעם סוג וואס האט געקענט און געדארפט מבורר ווערן דורך דעם וואס יעקב האט זיך אין זיי מתעסק געווען ברצונו ודעתו. עס זיינען אבער ביי לבן׳ען געווען אויך אזעלכע ניצוצות נעלים, וואס יעקב האט זיי ניט געקענט מעלה זיין דורך זיין עבודה מיט רצון ודעת — און דערפאר זיינען זיי איבער־",[["17","17","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011080\" data-slug=\"likkutei-sichot\" data-id=\"1300011080\">לקו״ש ח״א ע׳ 80</a> הדמיון (והביאור) להמבואר באגה״ק סכ״ה."],["18","18","אוה״ת שם."],["19","19","הטעם שתפס בלקו״ת (בהערה 21) ב׳ מצות אלו סוכה ולולב י״ל כי במצות אלו תוכנם ועניינם הר״ע הדעת: בסוכה נאמר (אמור כג, מג) ״למען ידעו דורותיכם כי בסוכות״ (ולכן הכוונה במצות סוכה היא לא רק כוונת המצוה אלא גם חלק מקיום המצוה כתיקונה׳* — ראה ב״ח או״ח ר״ס תרכ״ה. שו״ע אדה״ז שם): ו״לולב ומיניו הוא המשכת הדעת כו׳״ (לקו״ת <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381111\" data-slug=\"likkutei-torah\" data-id=\"4001381111\">ברכה צו, א</a>. ובכ״מ). *) ואף שכ״ה גם בתפלין וציצית כבב״ח שם, הרי בהנ״ל הוא כפי שנאמר ״למען תזכרו גו׳״. ״למען תהי׳ תורת ה׳ בפיך״. ולא כבסוכה ״למען ידעו גו׳״."],["20","20","ראה עירובין יג, ב."],["21","21","ברכה צט, ב ואילך."]]],[1300151275,"געבליבן ברשות לבן; און זייער בירור ועלי׳ איז דורך א כח עליון (בדרך אתערותא דלעילא).\nה. די מדריגה וואס פון איר ווערט נמשך דער כח עליון בדרך אתערותא דלעילא, איז מרומז אינעם נאמען ״לבן״, ווי די רז״ל²² זאגן אויפן פסוק²³ ״הידעתם את לבן — הידעתם את מי שהוא עתיד ללבן עונותיכם כשלג״.\nאון די הסברה אין דעם איז (כמבואר בתו״א²⁴), אז דער ענין פון לבן דקדושה — די בחי׳ פון לובן העליון, ״בחי׳ אור עצמותו ומהותו של אא״ס ב״ה״ — איז דאס ווי, למשל, דער מראה וגוון לבן (דער ווייסער קאליר) וועלכער איז אנדערש פון אלע אנדערע קאלירן: די אנדערע גוונים ווערן אויפגעטאן דורך דער מציאות פון פארב וואס שאפט דעם באשטימטן גוון. משא״כ די מראה וגוון לבן איז דאס ווי עס זעט אויס דער עצם ומהות פון א זאך, וואס ווערט ניט אויפ־געמאכט דורך פארבן, ״וכן הוא עד״מ אוא״ס ב״ה בעצמו ובכבודו דלית בי׳ בחי׳ גוונין כלל״.\nאון דאס איז די שייכות פון לבן צו דעם וואס ער איז ״עתיד ללבן עונותיכם כשלג״, כמארז״ל הנ״ל, ווייל דער ליבון, די מחילה פון די עוונות, קומט דורך המשכת עצמות אוא״ס ב״ה וואס איז העכער פון סדר ההשתלשלות, וואס דאס איז די בחי׳ פון לובן העליון²⁵ — דער שורש בריבוי השתלשלות וכו׳ פון לבן שלמטה.\nאון דאס איז דער טעם וואס די רז״ל²⁶ זאגן: תשובה תולה ויוהכ״פ מכפר, אז תשובה אליין איז ניט גענוג און דווקא יוהכ״פ, עיצומו של יום איז מכפר — ווארום דער לובן העליון, וואס פון דארט קומט די מחילת העוונות, היות אז דאס איז א מדריגה וואס איז העכער פון השתלשלות, קען עס דעם אדם ניט ממשיך זיין דורך זיין עבודה און אתעדל״ת (אליין), אפילו ניט דורך עבודת התשובה, נאר זי קומט מלמעלה בדרך אתעדל״ע²⁵ אין יוהכ״פ²⁷.\nו. עפ״י הנ״ל (אז די בחי׳ פון לובן העליון [וואס איז ״נשפל״ געווארן ״בלבן גשמי״²⁸] קען ניט נמשך ווערן דורך עבודת האדם ואתעדל״ת, נאר דוקא דורך אתעדל״ע) איז פארשטאנדיק, אז דער בירור פון די (נידעריקערע) ניצוצות, וואס יעקב האט אויפגעטאן אין די צוואנציק יאר בבית לבן, וויבאלד דאס איז געווען דורך זיין עבודה בדרך אתעדל״ת, האט נאך ניט פועל געווען דעם גילוי פון לבן דקדושה וואס איז ״נשפל״ געווארן אין דעם לבן הגשמי; דוקא ווען לבן (דורך זיין שורש — לובן העליון) איז נאכגעלאפן יעקבן (היינו בדרך אתעדל״ע) צו איבערגעבן אים די ניצוצות נעלים (אותיות) וואס זיינען ביי אים איבערגעבליבן, דעמאלט איז ביי יעקבן נתגלה געווארן די בחי׳ לובן העליון וואס איז געווען באהאלטן אין (גשמיות׳דיקן) לבן למטה.",[["22","22","ב״ר פרשתנו פ״ע יוד."],["23","23","פרשתנו כט, ה."],["24","24","סוף פרשתנו כד, ב. וראה שם כג, א."],["25","25","ראה לקרית דרושים ליו״כ סח, ד. ד״ה כתפוח בעצי היער מאדה״ז (קה״ת תשי״ד) פ״ד ואילך (<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316640192\" data-slug=\"or-hatorah-hb\" data-id=\"8316640192\">אוה״ת שה״ש כרך א׳ ע׳ קצב</a> ואילך)."],["26","26","יומא פו, א. וראה משנה שם פה, ב."],["27","27","להעיר ממשנ״ת, בלקו״ש ח״ד (ע׳ 1149 ואילך) במחלוקת רבי ורבנן (שבועות יג, א), דגם לרבנן עיצומו של יום מכפר אלא שס״ל שגילוי הכפרה דעיצומו של יום (שלמעלה מהכפרה שע״י התשובה) הוא ע״י התשובה."],["28","28","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370107\" data-slug=\"torah-or\" data-id=\"3901370107\">תו״א פרשתנו כג, א</a>."]]],[1300151276,"און דערמיט איז מובן דער המשך הענין ״וישכם לבן בבוקר וינשק לבניו ולבנותיו״ (אלס הקדמה צו ״ויעקב הלך לדרכו״): נאך דעם ווי ס׳איז געווען ״וירדוף״ פון לבן — לובן העליון כנ״ל — איז דאן נמשך און נתגלה געווארן דער לובן העליון אין דעם אופן פון ״נשיקין ואתדבקות רוחא ברוחא״²⁹ צו יעדן פון די בני ישראל — ״וינשק לבניו ולבנותיו״, וואס דאס איז תכלית הדביקות באלקות.\nאון דאס איז דער צוזאמענהאנג פון ״וישכם גו׳ וינשק (לבן) וגו׳״ מיט ״ויעקב הלך לדרכו״: אויפן וועג פון יעקב׳ס הליכה צו ארץ ישראל האט ער זיך באגעגנט און געהאט צו טאן מיט עשו׳ן און האט זיך ״מתאבק״ געווען מיט שרו של עשו — עבודת הבירורים — איז אים די נתינת כח אויף דער עבודה געקומען פון ״וישכם לבן בבוקר״, פון המשכת לובן העליון.\nז. עפ״י הנ״ל איז פארשטאנדיק די שייכות פון ״ויעקב הלך לדרכו״ (שבפרשתנו) צו דער עבודה פון יעדן אידן אין זיין הליכה פון חודש תשרי צו דער עבודה פון כל השנה:\nנאך די טעג פון התעוררות און עבודת התשובה פון יעדן אידן אין חודש אלול, אין די ימי הסליחות ובפרט אין די עשרת ימי תשובה, וואס דערמיט איז ער מעורר וממשיך מלמעלה דאס וואס ער איז בכח צו ממשיך זיין דורך אתעדל״ת, דורך אייגענער עבודה, ווערט דערנאך נמשך דער גילוי בחי׳ לובן העליון בדרך אתעדל״ע — ״וישכם לבן בבוקר״ — אין יום הכפורים [וואס דערפאר³⁰ זיינען\nדי ספּעציעלע לבושים פון כה״ג ביוהכ״פ געווען בגדי לבן³¹, וואס ווייזט אויף דעם גילוי פון אוא״ס ממש, פשוט בתכלית הפשיטות כנ״ל], און ווי ס׳איז מבואר אין לקו״ת³², אויף ״ביום הזה יכפר עליכם לפני ה׳״, אז עס ווערט נתעורר ״פנימיות רצונו ית׳״, וואס דאס ווערט אנגערופן ״כארז בלבנון״ ווייל ער איז ״מלבין עונותיהם של ישראל״ —\nאון ״וינשק לבניו ולבנותיו״: עס ווערט נמשך אין אלע ״פרצופים העליונים״, ביז אויך אויף צו מהפך זיין דעם רע פון נפש הבהמית וואס ווערט אנגערופן ״בניו ובנותיו״, אז ״זדונות נהפכים לזכיות ממש״³³.\nאון דעריבער, איז באלד נאך יוהכ״פ, נאכדעם ווי ס׳איז געווען די המשכה נעלית פון לובן העליון, הויבט זיך אָן די עבודה פון ״ויעקב הלך לדרכו״, כמבואר אין דרושי חסידות³⁴.\nאבער דער עיקר הענין פון ״ויעקב הלך לדרכו״ פאנגט זיך אָן נאכן חודש תשרי, דהיינו נאכדעם ווי די בחי׳ פון לובן העליון קומט אראפ בגלוי און אין א פנימיות אין חג הסוכות און שמע״צ ושמח״ת, וואס דעמאלט איז אויך דער עיקר המשכה פונעם נתינת כח אויף",[["29","29","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370114\" data-slug=\"torah-or\" data-id=\"3901370114\">תו״א שם כד, ב</a>."],["30","30","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380198\" data-slug=\"likkutei-torah\" data-id=\"4001380198\">לקו״ת אחרי כח, ג</a>."],["31","31","וי״ל שגם מזה סמך ללבוש בגדים לבנים (וקיטול) ביוהכ״פ. ולהעיר מאלף למטה אפרים סתר״י סק״ז."],["32","32","יוה״כ שם."],["33","33","ד״ה כתפות שם."],["34","34","המשך וככה תרל״ז רפצ״ו. ולהעיר ע״ד כהנ״ל מאגה״ק סימן ד׳, בפירוש ״צדק לפניו יהלך״ — ״לפניו הוא מלשון פנימיות ויהלך הוא מלשון הולכה שמוליך את פנימיות הלב לה׳ (שהוא למעלה מהדעת באדם, היא בחי׳ מתנה נתונה מאת ה׳ כו׳ — כמ״ש שם לפנ״ז קו, רע״א) ואחר כך ישים לדרך ה׳ פעמיו כו׳ בכל מעשי המצות ות״ת כו׳״."]]],[1300151277,"דער עבודה פון ״ויעקב הלך לדרכו״ — אויף זיין דרך העבודה אין אלע עניני חול³⁵, צו מברר זיין די ניצוצות און זיי\nמעלה זיין לקדושה³⁶ דורך דער עבודה פון ״וכל מעשיך יהיו לשם שמים״ און ״בכל דרכיך דעהו״.\n(משיחת שבת בראשית תשי״ב)",[["35","35","משא״כ ויעקב הלך לדרכו שלאחרי יוהכ״פ הוא בתורה ומצות כמפורש בהמשך וככה שם: ״פי׳ שהלך לדרכו בדרך התורה והמצות להיות בבחי׳ סר״מ ועש״ט שזהו דרך ה׳ .. כמ״ש מזה בד״ה כתפוח בעצי היער״, וכ״כ שם רפ״ד ״והו״ע העסק בתומ״צ״. ועד״ז בתו״א סוף פרשתנו. משא״כ ״דרכו״ שלאחרי שמחת תורה ובמיוחד לאחרי שבת בראשית וחודש תשרי בדברי הרשות ועניני חול, כמשנ״ת ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201266\" data-slug=\"likkutei-sichot\" data-id=\"1300201266\">לקו״ש ח״כ ע׳ 266</a> ואילך. ולהעיר דבסה״מ תש״ט (הנ״ל הערה 1): אין ויעקב הלך לדרכו אין דער עבודה פון תורה ומצות כו׳. וראה מה שהובא (סה״מ תיש״א ע׳ 78) מכ״ק אדמו״ר מהורש״ב נ״ע מתחיל הסדר דויעקב הלך לדרכו הוא דרך הוי׳, דרך התורה והמצוה. וי״ל בזה עדמשנ״ת בלקו״ש ח״ט (ע׳ IX הערה *7). וראה הנסמן בהערה הבאה."],["36","36","ראה תו״ח סוף פרשתנו. ולהעיר מההגה״ה לפ״ד בד״ה כתפוח שם."]]],[1300151278,"<h3>וישלח</h3>\nא. אין פסוק¹ „ויאמר אם יבוא עשו אל המחנה האחת והכהו וגו' המחנה הנשאר לפליטה”, שטעלט זיך רש\"י (אין צווייטן דיבור המתחיל) אויף די ווער־טער „והי' המחנה הנשאר לפליטה” און איז מפרש: „על כרחו כי אלחם עמו”, און דערנאך איז ער ממשיך ווייטער „התקין עצמו לשלשה דברים כו'” (כד־לקמן סעיף ג).\nדאס וואס רש\"י דארף זיך בכלל אפ־שטעלן אויף די ווערטער פון פסוק און זיי מפרש זיין\n— וואס לכאורה איז דער פירוש פון פסוק מובן בפשטות²,\nאז דורך צעטיילן אלעמען אין צוויי מחנות, איז אפילו ווען עשו זאל בא־פאלן און אייננעמען איין מחנה, וועט די צווייטע מחנה קענען אנטלויפן —\nאיז³ ווי מפרשי רש\"י⁴ זאגן, אז דא איז שווער דער לשון „והי'”, וואס איז משמע אז „המחנה הנשאר” וועט זיכער זיין „לפליטה” — וואס אויף דעם קען מען פרעגן: אפילו דורך צעטיילן אלעמען אין צוויי מחנות איז נאך ניט אינגאנצן זיכער אז די צווייטע מחנה וועט זיך גע־וויס ראטעווען; ס'איז נאר אז דאס גיט א בעסערע מעגלעכקייט פאר דער הצלה פון דער צווייטער מחנה —\nהאט דאך בהתאם לזה געדארפט שטיין (אנשטאט „והי'”) א לשון וואס ווייזט אויף „אולי”?\nבאווארנט עס רש\"י, אז דער לשון „והי'” מיינט טאקע „על כרחו” (און ניט ווי דער אבן עזרא און אנדערע מפר־שים ווילן איינטייטשן אז „והי'” דא איז פירושו „אולי יהי'”), אז ס'איז א דבר ברור אז די מחנה וועט זיין לפליטה, און די זיכערקייט איז — „כי אלחם עמו” און ניט דערלאזן אז עשו זאל אייננעמען אויך די צווייטע מחנה.\nדער פירוש איז אבער ניט מובן:\nא) מיט וואס גיט דער „אלחם עמו”⁵ א וודאות גמורה⁶ אז די צווייטע מחנה⁷ וועט זיין לפליטה?⁸ אפילו אויב די כוונה איז⁹, אז אין דער צייט פון יעקב'ס מלחמה מיט עשו'ן פאר דער ערשטער מחנה וועט די צווייטע מחנה זיך קענען ראטעווען דורך אנטלויפן — איז נאך אלץ ניט פארזיכערט די פליטה פון דער",[["1","1","פרשתנו לב, ט."],["2","2","כפי הראב\"ע ורמב\"ן עה\"פ. וברמב\"ן: על דרך הפשט כו'."],["3","3","כדמשמע מקושיות הראב\"ע לרש\"י. וראה הערה הבאה."],["4","4","ספר זכרון, גו\"א באר מים חיים, מהרש\"ל הובא בשפ\"ח דבק טוב, דברי דוד להט\"ז."],["5","5","באם הכוונה למחנה השני שהם ילחמו כמשמע מפי' ספר זכרון. ועד\"ז בפסיקתא דר\"כ יט: מיכא ולהלאה אנו עבדין קרבא עימי'. מדרש לקח טוב."],["6","6","ראה משכיל לדוד בפרש\"י. וגם לפי' הב' בחזקוני ד„לאחר שיכה המחנה הראשון יהא הוא ואנשיו יגעים ועייפים ויהא המחנה הנשאר לפליטה שלא יהא יגע וילחם עמם ויהרגם”, הרי מידי ספק לא יצא."],["7","7","נוסף על הקושיא שמקשה באלשיך כאן (קושיא הד' והה')."],["8","8","ולפי זה צריך לפרש לפליטה מן המלחמה לא שינוסו וכיו\"ב, אלא ינצלו מן המלחמה כי ינצחו אותו. וראה לך יד, יג ובפרש\"י."],["9","9","כפי' הא' בחזקוני עה\"פ. ט\"ז ושפ\"ח בפרש\"י. וראה ספורנו עה\"פ."]]],[1300151279,"צווייטער מחנה¹⁰; ס'איז נאר וואס נאכן צעטיילן „לשני מחנות” גיט דער „אלחם עמו” א נאך בעסערע געלעגנהייט פאר הצלה ופליטה, כנ\"ל.\nב) וואס איז דער „על כרחו”, און למאי נפק\"מ דא די הדגשה אז ס'איז „על כרחו” — נגד רצונו פון עשו'ן? דא איז דאך נאר נוגע צו מדגיש זיין, אז דורך „אלחם עמו” וועט די צווייטע מחנה זיכער געראטעוועט ווערן.\nדער רמב\"ן איז מסביר, אז די זיכער־קייט פון יעקב'ן¹¹ איז געווען צוליב דעם וואס „יעקב יודע שאין זרעו כולו נופל ביד עשו, אם כן ינצל המחנה האחד על כל פנים” — אבער מען קען ניט לערנען אזוי לויט רש\"י, ווארום דעמאלט איז די וודאות פארבונדן מיט אן אנדער סיבה און ניט מיטן טעם „כי אלחם עמו”, ווי רש\"י איז מפרש ומדייק בפירושו.\nב. לכאורה וואלט מען געקענט פארענטפערן שאלה אחת בחבירתה — עכ\"פ בדוחק גדול: מיט די ווערטער „על כרחו” מיינט ניט רש\"י צו זאגן, אז די פליטה וועט זיין בוודאות, נאר ער איז מסביר דעם אופן פון דער פליטה, אז זי וועט זיין „על כרחו” ווייל „אלחם עמו”¹².\nלפ\"ז איז (נוסף על העיקר אז „על כרחו” — איז דאך וודאות) די שאלה אויף דעם גופא: פון וואנעט איז די הוכחה פון פסוק (לפשש\"מ) אז „אלחם עמו”?\n[בשלמא לפי הנ\"ל אז רש\"י'ס כוונה בפירושו איז צו מדגיש זיין די וודאות פון „המחנה .. לפליטה” איז ער עס מדייק ומוכיח פון לשון „והי'” וואס שטייט אין פסוק, כנ\"ל, און מיט „כי אלחם עמו” איז ער נאר מסביר דעם טעם פארוואס ס'איז וודאי; משא\"כ לפי הנ\"ל, איז (אדרבה) רש\"י (בעיקר) אויסן צו מפרש ומחדש זיין אז דא רעדט זיך וועגן „אלחם עמו” (און דעריבער וועט זיין „המחנה הנשאר לפליטה” באופן פון „על כרחו”) — איז אויף דעם ניטא קיין הוכחה פון פסוק].\nג. ווייטער איז רש\"י ממשיך (אין דעם ד\"ה הנ\"ל) „התקין עצמו לשלשה דברים לדורון לתפלה ולמלחמה, לדורון ותעבור המנחה על פניו¹³, לתפלה אלקי אבי אברהם¹⁴, למלחמה והי' המחנה הנשאר לפליטה”.\nאיז דא ניט מובן: א) פארוואס ברענגט רש\"י דא אלע שלשה דברים בעת אז אין זיין פירוש רעדט ער נאר וועגן זיין גרייט זיין למלחמה? דאס וואס „התקין עצמו” אויך „לדורון לתפלה”, ווייס מען פון די ווייטערדיקע פסוקים און דארטן שטייט עס במפורש, ווי רש\"י ברענגט זיי אראפ.\nב) את\"ל אז אין דעם פסוק וואו ס'רעדט זיך אז יעקב איז געווען גרייט גיין אויף מלחמה איז נוגע וויסן אז דאס איז ניט דער איינציגער מיטל און אפילו ניט דער ערשטער מיטל והתחלה — נאר, אדרבא, פריער זיינען דורון",[["10","10","וראה ט\"ז שם: וזהו הוא בודאי שבידו לנוס משם אע\"פ שספק אם תועיל הפליטה."],["11","11","כן משמע מפשטות לשונו, דמ\"ש „והכוונה בזה” בא להסביר דעת המדרש ורש\"י. וכן מוכח מהלשון בטור הארוך. אבל ראה המשך לשונו „גם זה ירמוז כו'”. וראה בבחיי כאן, שהעתיק מ„דרשו רז\"ל” רק תיבת „על כרחו”, ומוכח, שלא בא לבאר דעת רש\"י (והמדרש) ע\"ז שינצל ע\"י מלחמה, כ\"א רק זה שינצל בודאי, כדלקמן בפנים."],["12","12","ראה באר יצחק בפרש\"י כאן"],["13","13","לקמן לב, כב."],["14","14","לב, יו\"ד."]]],[1300151280,"ותפלה, איז אבער ניט פארשטאנדיק פארוואס ער פארבינדט עס און — אלס א המשך צו זיין פירוש „על כרחו כי אלחם עמו”?\nג) נאכמער: אפילו ווען רש\"י וויל (מאיזה טעם שיהי') מפרט זיין אז צוזא־מען מיט זיין גרייטן זיך למלחמה האט זיך יעקב אויך געגרייט לדורון ולתפלה (וואס טעמא בעי, כנ\"ל, ויבאלד אז זיי שטייען גלייך ווייטער אין דער פרשה מפורש) קען מען פרעגן לאידך גיסא: צוליב וואס דארף ער איבער'חזר'ן אז „התקין עצמו” (אויך) צו „מלחמה” — נאכדעם ווי ער איז מפרש פריער אז יעקב האט געזאגט „אלחם עמו” — רש\"י האט בלויז געדארפט מוסיף זיין אז „התקין עצמו” (אויך) לדורון ולתפלה”.\nדער ראַ\"ם¹⁵ לערנט, אז מיטן המשך הפירוש „התקין עצמו לשלשה דברים” איז רש\"י אויסן צו ברענגען א הוכחה צו זיין פירוש אז „והי' המחנה הנשאר לפ־ליטה” מיינט „על כרחו כי אלחם” — וויבאלד רז\"ל¹⁶ זאגן אז „התקין עצמו לשלשה דברים”, און דעם פרט אז התקין עצמו למלחמה געפינט מען ניט אין פסוק מפורש (ווי מען געפינט בנוגע דורון און תפלה), במילא מוז מען זאגן אז די ווערטער „והי' המחנה הנשאר לפליטה” מיינט דעם ענין המלחמה.\nרש\"י זאגט אבער ניט אז „התקין עצמו כו'” איז א מאמר חז\"ל (מדרש),\nואדרבא — פשטות לשון רש\"י איז אז נאכדעם ווי מען ווייס אז „אלחם עמו” ווייס מען אז לויט פשוטו של מקרא איז „התקין עצמו לשלשה דברים” — אויך מלחמה.\nד. אויך פאדערט זיך ביאור אין דעם המשך בפירושו „התקין וכו'”:\nא) דער סדר פון די שלשה דברים ווי רש\"י רעכנט זיי בפירושו — „לדורון לתפלה ולמלחמה”¹⁷ — איז בהיפך פון דעם סדר הפסוקים וועלכע רש\"י ברענגט דא גלייך לראי'¹⁸: „ותעבור המנחה על פניו” („לדורון”) שטייט נאך דעם פסוק „אלקי אבי אברהם” (לתפלה), וועלכער קומט (גלייך) נאך דעם פסוק „והי' המחנה גו'” (מלחמה) — רש\"י איז משנה פון זייער סדר אין דער תורה¹⁹?\nב) אין מדרש געפינט מען (אויסער די ראיות פון די פסוקים וועלכע רש\"י ברענגט בפירושו, כנ\"ל) ראיות פון אנ־דערע פסוקים: „תפילה²⁰ — הצילני נא מיד אחי²¹, לדורון — ואמרת לעבדך ליעקב מנחה היא שלוחה²², למלחמה — וישם את השפחות וגו' והוא עבר לפניהם גו'”²³; און במ\"א²⁴ במדרשים",[["15","15","ועד\"ז בשפ\"ח בשם המהרש\"ל."],["16","16","תנחומא (באבער) כאן ו. קהי\"ר פ\"ט, יח. יל\"ש כאן רמז קלא. פסיקתא דר\"כ יט."],["17","17","ברמב\"ן הביא מפרש\"י הסדר „לתפלה ולדורון ולמלחמה”. אבל בדפוסים שראיתי וכן בדפוס ראשון דרש\"י הוא כבפנים. ואולי העתיק זה הרמב\"ן ממדרש שכן הוא סדרם בקה\"ר ותנחומא (באבער) ופסיקתא דר\"כ שם. ובדפוס שני וכו\"כ כת\"י רש\"י הסדר: לדורון למלחמה ולתפלה (כביל\"ש ומדרש לקח טוב)."],["18","18","להעיר דבכמה כת\"י (שבהערה הקודמת), אף שבתחילת הלשון הסדר הוא „לדורון למלחמה ולתפלה”, הנה בהמשך הלשון כשמפרט הראיות מהכתובים, סדרם הוא דורון תפלה ומלחמה. ועד\"ז הוא במדרש לקח טוב (אלא ששם הראי' לדורון ולמלחמה היא לא מאותם הכתובים שבפרש\"י כדלקמן בפנים)."],["19","19","ובקה\"ר שם הלימוד מהכתובים הוא כפי סדרם בהפרשה (כדלקמן בפנים). וכסדרם בהתחלת הדברים „לתפלה לדורון ולמלחמה”."],["20","20","קה\"ר שם."],["21","21","לב, יב. וכתוב זה הובא גם בפסיקתא דר\"כ (ניוארק, תשכ\"ב) שם כראי' על תפלה."],["22","22","לב, יט."],["23","23","לג, ב־ג."],["24","24","מדרש לקח טוב שם."]]],[1300151281,"געפינט מען די ראי' אויף „דורון” — „דכתיב²⁵ ויקח מן הבא בידו מנחה”, „למלחמה דכתיב²⁶ ויחץ את העם אשר אתו”²⁷:\nלפ\"ז איז ניט מובן אין פירוש רש\"י: ממנ\"פ, אויב רש\"י וויל ברענגען די פסוקים וואו עס איז מפורש ווי יעקב האט די ענינים געטאן בפועל (ניט די פסוקים וואו ס'רעדט זיך וועגן דער הכנה וההקדמה צו זיי) — ווי ס'איז משמע פון דעם וואס די ערשטע ראי' אויף „דורון” ברענגט ער פון „ותעבור המנחה על פניו” (און ניט פון די פריער־דיקע פסוקים, אנהויבנדיק פון „ויקח מן הבא בידו מנחה לעשו” וכיו\"ב, וואו ס'רעדט זיך ווי יעקב האט צוגעגרייט און אויסגעשטעלט די מנחה, און דער־פאר האט רש\"י (בפשטות) בוחר געווען די ראי' פון „ותעבור המנחה” — שילוח המנחה בפועל)\n— לפ\"ז האט ער געדארפט אויך אויף תפלה און מלחמה ברענגען די פסוקים וואו דער תוכן הדברים איז דער לפועל: בנוגע לתפלה פון „הצילני נא מיד אחי מיד עשו” און בנוגע למלחמה פון „וישם את השפחות וגו' והוא עבר לפניהם” (ווי רש\"י טייטשט דארטן „אם יבוא אותו רשע להלחם ילחם בי תחילה”). און ניט פון התחלת התפלה „אלקי אבי אברהם” און ניט פון יעקב'ס דיבור („והי' המחנה וגו'”, פון וואנעט מ'לערנט ארויס אז ער האט געזאגט) אז ער איז גרייט אויף מלחמה;\nאון אויב רש\"י וויל ברענגען ניט די מעשה בפועל נאר ווי „התקין עצמו לשלשה דברים”, זיין הכנה, האט ער אויך בא דורון געדארפט ברענגען דעם פריערדיקן פסוק כנ\"ל.\nג) וויבאלד רש\"י האט שוין געזאגט אז דער פסוק „והי' המחנה הנשאר לפ־ליטה” מיינט „אלחם עמו”, וואס דארף ער נאכאמאל אויסטייטשן בסוף פירושו אז די ראי' אויף „התקין עצמו .. למלחמה” איז פון דעם פסוק „והי' המחנה הנשאר לפליטה”?²⁸\nד) דיוק הלשון „התקין” — ניט „הכין” וכיו\"ב.²⁹\nה. דער ביאור בכל זה:\nפון פשטות המשך הכתובים איז משמע, אז נאכדעם וואס די מלאכים האבן זיך אומגעקערט און מודיע גע־ווען יעקב'ן אז עשו איז „הולך לקראתך וארבע מאות איש עמו”, האט יעקב זיך צום אלעם ערשטן געגרייט למלחמה — „ויחץ את העם גו' ויאמר אנו יבוא עשו גו'”, דערנאך האט ער מתפלל געווען ויאמר יעקב אלקי אבי אברהם גו', און דערנאך האט ער אנגעהויבן צו גרייטן א מנחה לעשו³⁰.\nדאס איז אבער ניט גלאטיק: עס איז מובן בפשטות, אז בשעת א איד הערט אז אימיצער קומט לוחם זיין מיט אים, איז ער צום אלעם ערשטן מתפלל צום אויבערשטן און ערשט דערנאך הייבט",[["25","25","לב, יד."],["26","26","לב, ח."],["27","27","בתנחומא (באבער) ועד\"ז ביל\"ש שם הפסוקים הם כבפרש\"י אלא שלמלחמה הובאה התחלת הכתוב „ויאמר אם יבא עשו וגו'”. אבל שם קאי על הכתוב „ויחץ את העם אשר אתו” — זיינן מבפנים והלבישן לבנים מבחוץ. ובפסיקתא דר\"כ שם קאי על הכתוב „והוא עבר לפניהם כו' מה עשה זיינן מבפנים כו'”."],["28","28","משא\"כ במדרשים הנ\"ל שלא קאי על כתוב זה, כבהערה שלפנ\"ז."],["29","29","במדרש לקח טוב „שכוון עצמו”."],["30","30","ראה מדרש לקח טוב שם בסופו: להלחם כנגדו כו' ואחר כך התחיל בתפלה ובדורון."]]],[1300151282,"ער אן טאן בדרך הטבע (גרייטן זיך צו למלחמה וכו') — היינט ווי איז שייך צו זאגן, ובפרט בא יעקב אבינו אז ער האט זיך פריער געגרייט למלחמה און ערשט דערנאך מתפלל געווען³¹?\nמוז מען זאגן אז אויך יעקב האט זיך אזוי געפירט (וכדלקמן). און דאס וואס דער פסוק זאגט „ויחץ את העם אשר אתו ואת הצאן גו' ויאמר אם יבוא עשו גו' והי' גו' לפליטה” איז עס א הקדמה — ביאור צו זיין תפלה\n— הערנדיק די שמועה פון די מלאכים („הולך לקראתך וארבע מאות איש עמו”) איז „וירא יעקב מאד ויצר לו” און דאס האט געבראכט אז „ויחץ את העם גו'”, וואס נאכדעם איז פאר־שטאנדיק תפלתו. און נאכדעם — אויף מארגן — ווען יעקב האט געזען „והנה עשו בא ועמו ארבע מאות איש”, ערשט דעמאלט — „ויחץ את הילדים גו'”³².\nוארום דער „ויחץ את העם” פון דעם פסוק איז ניט דער „ויחץ” וואס שטייט ווייטער³³, כפשוט — דא איז געווען „ויחץ את העם גו' ואת הצאן גו'” און דערנאך איז ויחץ נאר פון „הנשים ואת הילדים” און ניט לשתי מחנות;\nדא זאגט ער אז „ויחץ גו' לשני מחנות” און מיט דער כוונה אז „אם יבוא עשו אל המחנה האחת והכהו והי' המחנה הנשאר לפליטה”, און ווייטער זאגט ער „ויחץ את הילדים על לאה ועל רחל ועל שתי השפחות וישם את השפחות ואת ילדיהן ראשונה ואת (גלייך נאך זיי) לאה וילדי' אחרונים ואת רחל ואת יוסף אחרונים” — איין מחנה, ווי ער זאגט בפירוש³⁴ אז ווען עשו „וישא את עיניו” איז געווען „וירא את הנשים ואת הילדים” די אלע אויבן־דערמאנטע, ניט אז עס זיינען געווען צוויי באזונדערע מחנות וואס די צווייטע האט געקענט אנטלויפן (אין דער צייט ווען עשו האט באפאלט די ערשטע מחנה).\nאון רש\"י איז מפרש אז „והי' המחנה הנשאר לפליטה” מיינט „על כרחו כי אלחם עמו”, אז עשו וועט בעל כרחו ניט קענען זיי שלעכטס טאן\nדער „ויחץ גו' לשני מחנות” — איז מחנה האחת געווען הצאן והבקר והגמלים (וכמובן אויך פון דעם „עם אשר אתו” — די רועים וכו' וואס זיי־נען שייך צו זיי), און די „מחנה הנשאר” איז די „נשים והילדים” און דער „עם” וואס איז שייך צו זיי³⁵ — כמפורש דער־נאך בא „ויעבור את מעבר יבק”³⁶ צוויי באזונדערע ויעבור.\nנאך דעם ויחץ — קען ערשט קומען די תפלה — וויבאלד און מצד הבטחות שהבטחתני³⁷ — וואס דערפאר איז מחנה הנשאר (הנ\"ל) לפליטה בודאות, משא\"כ צאן וכו' פון מחנה האחת.\nאון כדי צו מוכיח זיין די וודאות פון יעקב'ן אז ער וועט מנצח זיין עשו'ן, איז",[["31","31","ראה אלשיך כאן קושיא הי\"ד."],["32","32","לג, א־ב."],["33","33","בפשש\"מ, ודלא כרבינו בחיי עה\"פ. ועד\"ז בתיב\"ע עה\"פ לג, ב (וראה תרגומו עה\"פ לב, ח *). *) ושם, שהב' מחנות הם מחנה לאה ומחנה רחל. אבל שם לג, ב: דמחנה הא' הוא השפחות ובניהם, ומחנה הב' לאה וילדי' ורחל ויוסף. אבל אינו ע\"פ פשש\"מ — דהרי העביר גם הצאן גו'."],["34","34","לג, א. לג, ה."],["35","35","וכן הוא באברבנאל שם (ועד\"ז הוא בעקידה ובאלשיך) דמחנה האחד הי' מהצאן והבקר והגמלים ושאר המקנה (עם הרועים), ונשיו וילדיו במחנה בפ\"ע."],["36","36","לב, כג־כד."],["37","37","פרש\"י לב, יו\"ד."]]],[1300151283,"רש\"י ממשיך „התקין³⁸ עצמו לשלשה דברים” — אז יעדע פעולה וואס יעקב האט געטאן פאר די הצלה, איז געווען אין אן אופן פון „התקין עצמו”, כדלקמן.\nו. ווען א מענטש גרייט זיך צו טאן א געוויסע זאך, אדער מערערע זאכן, איז דער ביטוי ע\"ד הרגיל דערויף: „הכין³⁹ עצמו” וכיו\"ב. דא שטייט אבער דער לשון „התקין עצמו”, קומט דאס מדגיש זיין נאך אן ענין אין דער הכנה:\n„הכין” מיינט כפשוטו, אז ער גרייט זיך טאן א געוויסע פעולה וואס די הכנה קען זיין אדער דורך א מעשה בפועל, אדער דאס איז א הכנה בנפש צו טאן די פעולה, צו מתפלל זיין וכיו\"ב.\nדער לשון „התקין” — מלשון תיקון⁴⁰ — מיינט ניט בלויז הכנה סתם, נאר ס'איז אויך מתאר דעם אופן ההכנה — ער איז „מתקן” עצמו, ער טוט אויף אין זיך די צוגעגרייטקייט צו טאן דאס.\nעד\"ז איז געווען ביי יעקב'ן. דאס וואס ער האט זיך געגרייט לדורון ולתפלה ולמלחמה איז געווען באופן של „התקין עצמו”:\nווי רש\"י איז מפרש — בנוגע למלחמה — מצד עצמו איז וירא ויצר⁴¹ האט געדארפט זיין „התקין עצמו”: בנוגע לדורון — איז ער געווען שרוי בכעס שהי' צריך לכל זה⁴² — נאר „התקין עצמו”: און אזוי אויך בנוגע לתפלה — אז אע\"פ וואס „אני⁴³ ירא שמא משהבטחתני נתלכלכתי בחטא ויגרום לי להמסר ביד עשו” איז התקין עצמו און האט מתפלל געווען און מוסיף געווען בתפלתו „היטב איטיב⁴⁴ — היטב בזכותך איטיב בזכות אבותיך”.\nז. עפ\"ז איז מוסבר דער טעם וואס רש\"י ברענגט די ראיות דוקא פון די פסוקים (און ניט פון אנדערע), ווייל די ראיות פון זיי זיינען ניט בנוגע דער עצם הכנה, אז ער האט זיך געגרייט צו די דריי זאכן, נאר אז די הכנה צו די דריי זאכן איז געווען אין אן אופן פון „התקין עצמו”.\n„לדורון — ותעבור המנחה על פניו” (וואס דערפון איז מעתיק רש\"י פון פסוק אויך די ווערטער „על פניו” איז מובן אז די ווערטער זיינען נוגע צו דער ראי') — ווייל פון דעם פסוק לערנט מען ארויס „על פניו אף הוא שרוי בכעס שהי' צריך לכל זה”.\n„לתפלה — אלקי אבי אברהם”, וואס דער לשון איז מרמז אויף הבטחת הקב\"ה לאבות, כנ\"ל.\nועד\"ז ביי מלחמה, וואס רש\"י ברענגט דערויף די ראי' פון פסוק „והי' המחנה הנשאר לפליטה”: אז כאטש מען ווייס פון פריער אז וירא ויצר כו' (כנ\"ל) איז „התקין עצמו” למלחמה, וויבאלד אז „והי' המחנה הנשאר לפליטה”, עס איז ברור ודאי אז די מחנה הנשאר מוז ניצל ווערן (מצד הבטחת הקב\"ה),\nאון רש\"י ברענגט „למלחמה” לבסוף — ווייל דאס איז געווען די שווערסטע זאך פון דעם „התקין עצמו” בא די",[["38","38","ודלא כמדרשים (הנ\"ל הערה 16) „והתקין” (בוא\"ו המוסיף), כי אי\"ז הוספה וענין חדש בפירושו, כ\"א הסברה וטעם בגוף פירושו."],["39","39","ביתרו יט, יא. טו „נכונים” (וראה רש\"י שם). ולהעיר מנח יא, ז: הבה."],["40","40","להעיר מלשון תיקון שכבר הובא בפרש\"י, לדוגמא — בראשית (א, ז. כה). וירא (יח, ח. שם, כב)."],["41","41","פרשתנו לב, ח."],["42","42","פרש\"י פרשתנו לב, כב."],["43","43","פרש\"י שם, יא."],["44","44","פרש\"י שם, יג."]]],[1300151284,"שלשה דברים, אראפנעמען דעם וירא ויצר — פון שמא יהרג אדער יהרוג אחרים⁴⁵.\nח. עס בלייבט אבער נאך ניט פאר־ענטפערט: פארוואס איז רש\"י מקדים „דורון” פאר „תפלה”? לכאורה איז תפלה געקומען פריער.\nאיז דער ביאור בזה, אז אע\"פ אז לפועל האט ער דעם דורון געשיקט נאך דער תפלה, איז אבער דער תוכן הענין פון דורון — „למצוא חן בעיניך”⁴⁵ — געווען די ערשטע זאך וואס יעקב האט מקדים געווען צו טאן — נאך דאן ווען ער האט געשיקט די מלאכים צו עשו'ן, כמפורש בהתחלת הפרשה.\n[אמת טאקע אז בעת צרה איז צום אלעם ערשטן איז מען מתפלל צום אוי־בערשטן אז ער זאל שיקן א הצלה וישועה מלמעלה, אבער בא יעקב'ן איז דאך געווען — כפרש\"י⁴⁶ — היית אומר — ניט כרגיל „אמרת”⁴⁷ — געהאלטן אין איין זאגן „אחי הוא”\nמער ניט וואס יעקב האט געוואלט עס זאל זיין נאך מער פון אחוה סתם, נאר — למצוא חן בעיניך און דערפאר — איז „וישלח יעקב מלאכים גו' ואשלחה להגיד לאדוני למצוא חן בעיניך — שאני שלם עמך ומבקש אהבתך”⁴⁸ ניטא קיין עת צרה.\nערשט ווען די מלאכים האבן זיך צוריקגעקערט און דערציילט אז עס איז ניט „אחי הוא” נאר „עשו הרשע”⁴⁶, האט יעקב מתפלל געווען „הצילני נא גו'”, און דערנאך אים געשיקט דעם דורון, אפשר וועט ער אים מיט דעם קענען מפייס זיין].\nט. ס'איז אבער נאך אלץ ניט גלא־טיק דער לשון רש\"י „התקין עצמו לשלשה דברים” — דלכאורה האט ער געדארפט זאגן „התקין עצמו לדורון לתפלה ולמלחמה” (ובלשון הש\"ס בכ\"מ⁴⁹: מניינא למה לי)? והביאור בזה:\nאויך נאך דעם ווי די מלאכים האבן מודיע געווען יעקב'ן אז ניט „אחי הוא” נאר „נוהג עמך כעשו הרשע ועודנו בשנאתו” — איז בא יעקב'ן געווען דריי מעגליכקייטן בבת אחת:\nמצד עשו, איז אפשר מספיק צו שיקן אים א דורון און דערמיט אים מפייס זיין, ווי ס'איז מובן געווען בא יעקב'ן פון דעם וואס רבקה האט עם געשיקט⁵⁰ אז ער זאל זיך אומקערן קיין ארץ ישראל\n— דלכאורה תמוה: וויבאלד אז עשו הרשע איז „עודנו בשנאתו”, ווי אזוי האט רבקה געשיקט צו יעקב'ן אז ער זאל זיך אומקערן? איז דערפון גופא א הוכחה, אז כאטש עשו איז „עודנו בשנ־אתו”, איז אבער בטל געווארן חמת עשו, און ס'איז ניטא קיין סכנה פון „אשכל גם שניכם יום אחד”⁵¹. און שנאתו קען מען אראפנעמען דורך שיקן אים א דורון,\nמצד יעקב אבער, וואס ער האט חושש געווען („שמא .. נתלכלכתי",[["45","45","לב, ו."],["46","46","פרשתנו שם, ז."],["47","47","גם בזה מודגש גודל הדיוק בפרש\"י עה\"ת. „נפלאות” — בשינוי תיבה אחת!"],["48","48","פרש\"י שם. וי\"ל שכוונת יעקב בזה שהודיע לו „ויהי לי שור וחמור גו' למצוא חן בעיניך” היתה גם לרמז לו שמוכן ליתן לו ממנו במתנה, אף שבעיקר הי' בשביל לומר לו „זו אינה לא מן השמים ולא מן הארץ” (פרש\"י שם עה\"פ ד\"ה ויהי)."],["49","49","שבת סט, א. וש\"נ."],["50","50","פרש\"י פרשתנו לה, ח."],["51","51","תולדות כז, מד־מה."]]],[1300151285,"בחטא\") קען זיין אז דער „עודנו בשנאתו” איז גענוג אויף זיין א מצב פון סכנה ע\"ד ווי מ'געפינט בא לוט אז דער חטא פון ישיבתו בסדום האט געבראכט דעם „ויקחו את לוט”⁵² — האט ער אויך געדארפט האבן די תפלה „אלקי אבי אברהם” — בזכות אבותיך.\nאון וויבאלד די פעולות ההצלה שע\"י תפלה קען זיין אויף צוויי אופנים — (א) ווי דער אויבערשטער האט אים מציל געווען פון לבן — „אלקי אבי אברהם ופחד יצחק הי' לי גו' ויוכח אמש”⁵³; (ב) א הצלה וואס מ'דארף אנקומען צו א מלחמה, ווי די הצלה פון לוט⁵⁴ וואו אברהם האט געדארפט מלחמה האבן אים צו ראטעווען — דערפאר האט יעקב געמוזט זיך מכין זיין אויך צו מלחמה.\nיו\"ד. ע\"פ יינה של תורה שבפירוש רש\"י י\"ל — אין דעם וואס יעקב „התקין עצמו” צו אלע שלשה דברים בבת אחת. און דאס איז אויך דער דיוק לשון רש\"י „התקין עצמו לשלשה דברים”, ווייל כדי גרייט זיין צו טאן די דריי זאכן צוזא־מען, איז היפך הטבע, מוז זיין „התקין עצמו”, מען דארף זיך מתקן ומשנה זיין. וארום יעדער פון די דריי ענינים איז א תנועה הפכית פון דעם צווייטן ענין: דורון איז א תנועה פון קירוב וחסד, מלחמה — א תנועה פון ריחוק וגבורה. און ביידע — בין בנ\"א. תפלה — איז בקשת רחמים מלמעלה. און דעריבער, כדי צו קענען שטיין אין די דריי פאר־שידענע (הפכיות'דיקע) תנועות בבת אחת, איז דאס ניט בטבע האדם — אפילו ניט לפי טבע דקדושה פון נפה\"א (וואס יעדע מדה איז אין א באזונדער תנועה וציור), נאר עס פאדערט זיך אן ענין פון „התקין עצמו”, שינוי הטבע.\nיא. ס'איז אבער הא גופא טעמא בעי — פארוואס האט זיך געפאדערט אז יעקב זאל שטיין אין די אלע דריי תנועות בבת אחת?\nוועט מען דאס פארשטיין לויט דעם ביאור אין חסידות⁵⁵ אויף דעם פסוק⁵⁶ „ונאספו שמה כל העדרים”, ע\"פ המשל פון א מלחמה גשמית, אז די הצלחה במלחמה ווערט דורך דעם וואס מ'שטעלט אוועק „כל ג' מחנות שלו נגד מחנה וחלק א' של השונא”, וואס דאן „יתגבר בודאי עליו”, און דערנאך „יעשה כן למחנה ב' של השונא וכו'”.\nאון עד\"ז איז אין עבודת ה', אז כדי צו מנצח זיין מלחמת היצר, דארף מען מעורר זיין „כל ג' מדות דקדושה (אהבה יראה און רחמים) לעומת מדה אחת דקליפה ועי\"ז בודאי יפילו וינצחו אותה”. און דאס מיינט „ונאספו שמה כל העדרים” — „שהם אהוי\"ר ורחמנות דקדושה”.\nכשם ווי דאס איז אין מלחמת היצר (ביי יעדן אידן בפרט), עד\"ז איז דאס אין דער עבודה פון אידן אין גלות בכלל, וואס אין גלות זיינען דא כמה סוגים כלליים — גלות ישמעאל און גלות אדום (עשו) — אז כאטש יעדער סוג גלות האט זיין פרטיות'דיקן אופן",[["52","52","פרש\"י לך יד, יב. וראה ג\"כ פרש\"י וירא יט, יט."],["53","53","ויצא לא, מב."],["54","54","לך יד, יד ואילך."],["55","55","כ\"ק הצ\"צ (נעתק ב„התמים” חוברת ג' קכ, א)). וראה לקו\"ת ואתחנן ה, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201420\" data-slug=\"likkutei-sichot\" data-id=\"1300201420\">לקו\"ש ח\"כ ע' 407</a> ואילך."],["56","56","ויצא כט, ג. *) עיי\"ש שהוא „ע\"פ הקדמה ששמעתי מפה הק' כאאזמו\"ר נ\"ע כו'”."]]],[1300151286,"העבודה מתאים לאופן הגלות (ישמעאל חסד דקליפה, עשו גבורה דקליפה⁵⁷) — איז אבער דער זיכערער דרך צו ביי־שטיין (און — ביז צו מנצח זיין און איבערמאכן) דעם גלות דארף מען צונויפקלייבן אלע ג' מדות דקדושה ביחד.\nאון וויבאלד אז די נתינת כח אויף דער עבודה פון אידן (סימן — לבנים) נעמט זיך פון „מעשה אבות” — גע־פינט מען ביי יעקב'ן, בחיר שבאבות, די התכללות פון אלע ג' מדות אין די ביידע סוגים פון גלות:\nאלס הקדמה צו זיין זיין אין בית לבן (וואס איז פארבונדן מיט גלות בבל⁵⁸) — ונאספו שמה כל העדרים; און עד\"ז אין דער עבודה פון בירור פון עשו'ן (גלות אדום) אז עס איז געווען „התקין עצמו לשלשה דברים (ביחד)” — די דריי קוין פון חסד (דורון) גבורה (מלחמה) און ת\"ת ורחמים (תפלה).\nיב. פון כהנ\"ל איז אויך די הוראה אין דער עבודה פון יעדן אידן:\nבשעת מ'דארף ראטעווען אידישע קינדער פון דעם אופן החינוך פון עשו'ן, קען מען זיך ניט באגנוגענען מיט זיין אייגענעם טבע ווי ער איז איינגע־וואוינט אין עבודת ה', נאר עס דארף זיין „התקין עצמו”, זיך מתקן זיין און איבערמאכן. וואַרום בשעת מען גייט מיט א חשבון וטעם ודעת, מתאים לפי עבודה פרטית נגד עשו'ן, קען מען ניט זיין זיכער אז מ'וועט קענען מיט אים זיך איינקערן ובעיקר ראטעווען אלעמען וועמען מ'דארף פון אים ראטעווען.\nדוקא בשעת מען גייט אן חשבונות אין אן אופן פון „על כרחו”, און מיט אלע זיינע כוחות צוזאמען, התקין עצמו, איז מען מצליח אז מען נעמט איין עשו'ן ביז עס ווערט מקוים דער יעוד „ועלו מושיעים בהר ציון לשפוט את הר עשו והיתה לה' המלוכה”⁵⁹, בביאת משיח צדקנו, במהרה בימינו ממש.\n(משיחת ש\"פ וישלח תש\"ל)",[["57","57","לקו\"ת שם."],["58","58","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158670075\" data-slug=\"or-hatorah-hb\" data-id=\"8158670075\">אוה\"ת</a> ויצא רכו, סע\"א."],["59","59","עובדי' בסופו. הובא בפרש\"י בפרשתנו לג, יד."]]],[1300151287,"וישלח ב — י״ט כסלו —\nא. אין פסוק 1 „קטונתי מכל הח־סדים גו׳ כי במקלי עברתי את הירדן הזה ועתה הייתי גו׳”, זיינען דא צוויי פירושים הפכיים:\nא) דער פירוש הפשוט (ווי עס טייטשט דער תרגום און רש״י אין זיין ערשטן פירוש, ועוד), אז יעקב איז איבערגעגאנגען דעם ירדן ניט האבנדיק מיט זיך קיין שום זאך אויסער זיין „מקל” — וואס לויט דעם פירוש קומט אויס, אז די ווערטער „במקלי עברתי את הירדן הזה” דריקן אויס (ניט די חסדים וואס דער אויבערשטער האט געטאן מיט יע־קב׳ן, נאר, פארקערט) דעם בגשמיות־ארעמקייט מצב פון יעקב אבינו בעת ער איז אריבער דעם ירדן; עס איז א הקדמה וואס איז נאכמער מבליט די גרויסקייט פונעם שפעטער׳דיקן חסד פון „ועתה הייתי לשני מחנות”, וואס שטייט נאכדעם אין פסוק.\nב) דער פירוש המדרש 2 (אראפ־געבראכט אויך אין פי׳ רש״י), אז „נתן מקלו בירדן ונבקע הירדן” — וואס לויט דעם פירוש אנטהאלטן די ווערטער „במקלי עברתי גו׳” גופא אן ענין פון חסדי ה׳ *2.\nאון די פירושים זיינען הפכיים בתכלית: לויטן ערשטן פירוש — עניות בתכלית; לויטן צווייטן פירוש\n— ראוי צו א נס הכי גדול, ובלשון חז״ל 3: כמה נפיש גברא כמשה ושתין רבוון, שנחלק להם ים סוף.\nב. צו פארשטיין דעם פארבונד פון די צוויי פירושים (וואַרום ווי פיל מאל גערעדט 4, האבן אלע פירושים אויפן זעלבן ווארט, פסוק, אדער ענין, א קשר תוכני צווישן זיך),\nובפרט אז באגדת בראשית *4 קומען זיי בהמשך זה לזה,\nדארף מען מקדים זיין דעם לשון פון אלטן רבי׳ן אין זיין באוואוסטער אגרת „קטנתי” 5 (וואס ער האט גע־שריבן קומענדיק פון פעטערבורג, נאך דער גאולה פון י״ט כסלו) — „מפני היות קטן יעקב במאד מאד בעיניו מחמת ריבוי החסדים כי במקלי כו׳” (עכ״ל בהנוגע לעניננו).\nלכאורה איז ניט פארשטאנדיק: וויבאלד דער אלטער רבי וויל דא בא־טאנען דעם „ריבוי החסדים” וואס דער אויבערשטער האט געטאן מיט יעקב׳ן (וואס דאס האט ביי אים ארויסגערופן דעם „קטנתי”), האט ער געדארפט ברענגען אויך (ואדרבא — בעיקר) דעם סיום הכתוב „עברתי את הירדן הזה ועתה הייתי לשני מחנות” ?\nלכאורה וואלט מען געקענט לער־נען, אז מיט „כי במקלי כו׳” מיינט",[["1","1","פרשתנו לב, יא."],["2","2","אגדת בראשית פמ״ה, ד. תנחומא (באבער) ויצא ג. וראה מדרש אגדה כאן. *2) ראה ראב״ם וגו״א בפרש״י."],["3","3","חולין (ז, א) ובפרש״י."],["4","4","לקו״ש ח״ג ע׳ 782. ועוד. *4) שם. וכן הוא בתנחומא (באבער) שם."],["5","5","אגה״ק סי׳ ב׳ (קג, ב)."]]],[1300151288,"דער אלטער רבי אנדייטן אויפן אויבענגעבראכטן פירוש פון מדרש: „נתן מקלו בירדן ונבקע הירדן” — אבער מען קען אזוי ניט זאגן, ווייל: א) עס בלייבט נאך אלץ שווער, פאר־וואס ער דערמאנט ניט אויך דעם צווייטן חסד וואס שטייט מפורש אין פסוק: „ועתה הייתי לשני מחנות” ? ב) ועיקר: אויב דער אלטער רבי מיינט מיט דער הוכחה פון פסוק, דעם נס (לויטן פירוש פון מדרש) אז „נבקע הירדן”, וואלט ער דאך געדארפט צוליב דעם גופא בריינגען דעם המ־שך, „עברתי את הירדן הזה”, אין וועלכן ס׳ווערט נרמז דער נס וואס האט זיך אויפגעטאן מיטן „במקלי” 6 ?\nמען קען ניט זאגן אז דער אלטער רבי מיינט טאקע דעם גאנצן פסוק, נאר בכדי צו מקצר זיין בריינגט ער בלויז די התחלה פון פסוק, און דעם סיום איז ער מרמז מיטן ווארט „כו׳” 7 — וואַרום א) עכ״פ נאך דעם איין ווארט „עברתי” — האט מען גע־דארפט בריינגען, ב) אויב אזוי איז, ווי ערקלערט אמאל באריכות 8, וואלט געדארפט שטיין „וכו׳” (מיט א וא״ו המוסיף); אויב עס שטייט „כו׳” (אן א וא״ו) איז דאס א באווייז אז דער\nהמשך הכתוב איז ניט נוגע צום תוכן המדובר (און דאס צוגעבן „כו׳” (אדער „גו׳”) איז צו באווארענען וואס די רז״ל 9 האבן געזאגט, אז „כל פסוקא דלא פסקי׳ משה אנן לא פסקינן”).\nאיז פון דעם אלעם מובן, אז דער ענין פון „כי במקלי” אליין, און די ענינים וואס בהמשך הכתוב, איז גענוג צו פועל זיין ביי יעקב׳ן דעם „קטונתי”.\nג. דער צ״צ בריינגט אראפ אין אוה״ת 10 פון של״ה 11, אז „כי במקלי” איז ר״ת „ברוך כבוד ה׳ ממקומו 12 לישועתך קויתי ה׳”, און דער צ״צ איז מוסיף: „ור״ל ע״ד שנתבאר בתו״א 13 כו׳ בענין משפט וצדקה ביעקב אתה עשית 14 שצ״ל ב׳ הבחינות צדקה ומשפט והיינו ב׳ הבחינות בכה״מ ושיהי׳ לישועתך קויתי וכו׳”.\nדער ביאור אין דעם איז: פון דעם וואס עס שטייט „משפט וצדקה ביעקב אתה עשית”, איז מובן, אז ביי יעקב׳ן זיינען געווען די ביידע מדות 15, און די הנהגה מיט עם איז אויך געווען",[["6","6","דזהו ההכרח לפירוש זה, דאל״כ למה הזכיר את הירדן, הו״ל למכתב כי במקלי באתי עד הנה (גו״א כאן)."],["7","7","את״ל שגם בזה מדויקות העתקות אגה״ק (אף שהיו „מפוזרים אצל התלמידים” — הסכמת הרבנים שי׳ בני כו׳) — נראה שבמכתבים לא דייק רבנו הזקן לכתוב בכתוב „גו׳”, ובמרז״ל „כו׳” (ראה תשבי ערך גמר „נוהגין רז״ל בדבריהם כשמביאין פסוק אחד ואינם משלימין אותו . . כותבין וגומר . . וכאשר מביאין מאמר מדבריהם ואינם משלימין אותו כותבין וכולי”)."],["8","8","לקו״ש ח״ה ע׳ 387. ועוד."],["9","9","מגילה כב, א."],["10","10","פרשתנו רלג, א."],["11","11","רצה, ב."],["12","12","בשל״ה שם „כי ב״מ שהוא שם מכב״י . . מר״ת פסוק מי כמוכה באלים ה׳”. וי״ל שמ״ש הצ״צ הוא ע״פ של״ה רנט, א ש„מכב״י” הוא גם ר״ת „ברוך כבוד ה׳ ממקומו”. וראה אוה״ת בשלח ע׳ תקנא. סד״ה מי כמוכה תרפ״ח."],["13","13","בשלח סג, ב."],["14","14","תהלים צט, ד."],["15","15","וגם מה שבאברהם נאמר (וירא יח, יט) „לעשות צדקה ומשפט” הרי „אברהם עצמו לא נברא אלא בזכותו של יעקב כו׳, ואין צדקה ומשפט אלא ביעקב שנאמר משפט וצדקה ביעקב גו׳” (ויק״ר פל״ו, ד. הובא ונתבאר באוה״ת וירא צו, א. וראה שם צט, א)."]]],[1300151289,"סיי משפט סיי צדקה — חאטש לכאו־רה זיינען זיי הפכים: משפט מיינט, אז דאס וואס ער מאנט קומט אים ע״פ דין; און דער מין פון צדקה איז, אז עפ״י דין ומשפט איז מען אים ניט מחוייב צו געבן, נאר דאס ווערט אים געגעבן אלס צדקה.\nלכאורה וואלט מען געקענט זאגן אז דאס רעדט זיך אין שייכות צו צוויי באזונדערע בחינות: מצד דער נשמה קען א איד מאנען עניניו ביים אויבער־שטן בתורת „משפט” — דער נשמה קומען אירע ענינים עפ״י דין; און מצד דעם גוף קען ער עס בלויז בעטן אלס צדקה.\nדאס איז אבער ניט אויסגעהאלטן, וואַרום דער פסוק זאגט דאך „משפט וצדקה ביעקב אתה עשית” ד.ה. אז ביידע מדות (הפכיות) זיינען אין (שיי־כות צו דעם זעלבן גדר — וועלט — פון) „עשית” — עשי׳ — בפועל.\nאיז די הסברה אין דעם: אויך דאן ווען מ׳האלט ביי א מדרי׳ וואס בא־רעכטיקט צו מאנען השפעת הטוב פון אויבערשטן מצד הדין — ווי די גמרא 16 זאגט אויפן פסוק 17 „שמעו אלי אבירי לב הרחוקים מצדקה”, אז „כל העולם כולו ניזונין בצדקה והם ניזונין בזרוע” — פונדעסטוועגן דארף מען דאס בעטן אלס צדקה און ווי עס שטייט 18 „לך אדנ־י הצדקה”.\nד. דאס איז אויך דער טעם פון יעקב׳ס מורא פאר עשו׳ן, הגם ער האט שוין דערויף געהאט א הבטחה פון אויבערשטן („והנה אנכי עמך\nגו׳”<sup data-n=\"19\">19</sup> — וואַרום, אמת טאקע, אז ער האט מורא געהאט „שמא . . נתלכ־לכתי בחטא” 20, אבער דאס גופא פאדערט ביאור: חז״ל 21 זאגן דאך אז „כיון שיצאו רוב שנותיו של אדם ולא חטא שוב אינו חוטא”, ובמילא איז דאך דאס מחייב אז יעקב האט שוין ניט געהאט וואס צו חושש זיין „שמא נתלכלכתי בחטא”, ויבאלד ס׳זיינען שוין אדורך „רוב שנותיו” 22 ? —\nאבער דאס אלץ איז ווען זיין מצי־אות פארנעמט ביי אים אן ארט, און דערפאר קען דער חשבון אים ברענ־גען צו דער מסקנא אז ס׳איז „יצאו רוב שנותיו” ולא חטא, און במילא מובטח לו ד„שוב אינו חוטא”; און אויב ער איז פון די „אבירי לב” קען ער מאנען „בזרוע” וואַרום עס קומט עם ע״פ משפט:\nבשעת אבער ער שטייט אין א אמת׳ן ביטול, אז ער איז ביי זיך קיין",[["16","16","ברכות יז, ב. ובפרש״י שם."],["17","17","ישעי׳ מו, יב. וראה אוה״ת עה״פ."],["18","18","דניאל ט, ז."],["19","19","ויצא כח, טו."],["20","20","ל׳ רש״י כאן. ובברכות (ד, א) שמא יגרום החטא. ובאגה״ק (שם) מוסיף: שנדמה בעיניו שחטא. וראה לקו״ש ח״ה ע׳ 398 הערה 67. וראה לקמן בפנים סוס״ד וסוס״ז."],["21","21","יומא לח, סע״ב."],["22","22","דהרי כשהלך יעקב לחרן (זמן ההבטחה) הי׳ בן ע״ז שנה (רש״י תולדות כח, ט). ולהעיר מפרש״י על אמרו בהיותו בן פ״ד שנה „כי מלאו ימי” (ויצא כט, כא). וראה רמב״ן (בראשית ה, ד) דבימי אברהם יצחק ויעקב הי׳ הימים בעם שבעים ושמונים שנה. ועוד הרי כבר נאמר (בראשית ו, ג) והיו ימיו מאה ועשרים שנה (וראה מדרש הגדול שם דגזירה זו באה לסיבת המבול). ועוד שיעקב בחיר שבאבות נביא הי׳ (ראה רש״י ויגש מה, כז), ובמכש״כ מאמהות (רש״י ויצא כט, לד) ומאברהם (וירא כ, ז). ואף שבאמירת יצחק „לא ידעתי יום מותי” הוזקקו לטעם שהגיע לפרק אמו (תולדות כז, ב ובפרש״י שם) י״ל דשאני התם כיון דאפליג אפליג (גיטין כח, א). וראה מפרשים עה״פ ויגש מז, ט. לעיל ע׳ 217 ואילך."]]],[1300151290,"מציאות ניט — איז מצד דעם הרגש הקטנות והביטול איז „נדמה בעיניו שחטא” 23: ער איז חושש אז ס׳איז דא א חטא, עכ״פ — א חסרון 24 אין זיין עבודה און דערפאר לייגט זיך ביי אים אפ אז די השפעת הטוב קען ער בא־קומען נאר אלס צדקה.\nה. עס איז אבער ניט מובן: ווי־באלד אז דער ביטול פון יעקב׳ן האט עם געבראכט צו דעם אופן פון צדקה, טא ווי זאגט מען „משפט וצדקה ביעקב גו׳” — וואס פון דעם איז משמע, אז עס (איז געווען בא יעקב׳ן, ובמילא — אז עס) דארף זיין *24 אויך דער אופן פון משפט ?\nאיז דער ענין בזה: בשעת מען איז באמת (אדער ס׳איז נדמה לו כן) אין א מצב וואס בעטן ביים אויבערשטן בלויז אלס צדקה — איז דאס בעטן צדקה ניט קיין הוכחה אף ביטול, ווייל ער האט דאך קיין ברירה ניט. בעומק יותר: דאס איז לויט זיין (ביטול׳־דיקער) מציאות ומדידה והגבלה. ומדה כנגד מדה, קומט אויך די השפעה מלמעלה לויט דער מדידה והגבלה וואס איז אין צדקה — ווי די גמרא 25 זאגט, אז דער חיוב פון צדקה איז „די מחסורו אשר יחסר לו” 26, אבער „אי אתה מצווה עליו לעשרו”: מ׳גיט אים דאס וואס עס פעלט לויט זיין „מציאות”, אין וואס ער איז איינגע־וואוינט (וואס דאס קען אויך זיין א ריבוי גדול, אבער דאך — געמאסטן\nלויט זיין רגילות: אויב ער איז רגיל צו האבן א סוס לרכוב עליו ועבדים לרוץ לפניו, דארף מען דאס עם אויך געבן 27 — אבער אי אתה מצווה עליו לעשרו.\nאבער בשעת ער איז אין א מצב ומציאות וואס ער איז ווערט צו בא־קומען די השפעות ובמילא קען ער זיי מאנען בתורת „משפט”, און דאך קומט ער צום אויבערשטן (ניט מיט דער תביעה פון משפט, נאר) מיט דער בקשה אלס צדקה 28, איז דאס א הוכחה אז ער איז ארויס פון חש־בונות מדידות והגבלות, אז ער איז ארויס פון זיין מציאות 29:\nאון דעמאלט איז די השפעת הצדקה אין אן אופן פון למעלה ממדידה והגבלה; וואס איז ניט פארבונדן מיט זיין מציאות ומחסרו אשר יחסר לו 30.\nו. אט די צוויי בחינות — [(א) א מצב פון בעטן אלס צדקה (ב) א מצב פון „אבירי לב” און קען מאנען „בזרוע”, ובכל זה בעט ער בצדקה וואס דע־מאלט ווערט די צדקה אין אן אופן פון בלי גבול] — זיינען מתאים צו די",[["23","23","ל׳ אדה״ז באגה״ק שם."],["24","24","מל׳ אני ובני שלמה חטאים (מלכים א א׳ כא). *24) ובפרט שהאבות היו המרכבה שכל איבריהם כולם היו כו׳ רק לרצה״ע (<a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא פכ״ג</a>)."],["25","25","כתובות סז, ב."],["26","26","ראה טו, ח ובפרש״י."],["27","27","כתובות שם. פרש״י שם."],["28","28","ראה פרש״י ר״פ ואתחנן (מספרי שם): אע״פ שיש להם לצדיקים לתלות במעשיהם הטובים אין מבקשים מאת המקום אלא מתנת חנם. וראה לקמן הערה 39."],["29","29","בתו״א בשלח שם מבואר ענין המשפט — שהאדם עושה משפט בעצמו לגבי העני כו׳. אבל גם שם מבואר שבמשפט שעושה האדם בנפשו הוא ביטול נעלה יותר מהביטול שבנתינת צדקה סתם, דהרי המשפט הוא שלא לתת יניקה וחיות מותרות הגוף, עיי״ש."],["30","30","להעיר מהפס״ד דמי שיש לו מאתים זוז לא יטול, פחות מזה — נותן לו כאחת (בתורת צדקה) אפילו אלף (פאה בסופה. טושו״ע יו״ד ר״ס רנג)."]]],[1300151291,"צוויי ענינים: א) „לישועתך קויתי הוי׳”, ב) „ברוך כבוד הוי׳ ממקומו”:\n„לישועתך קויתי הוי׳” פירושו אז ער קען זיך בלויז פארלאזן אויף דער ישועה פון אויבערשטן, ווייל ער איז ניט ראוי צו האבן א תביעה, און דער־פאר האפט ער אויף דעם אוי־בערשטנ׳ס ישועה — אלס צדקה.\n„ברוך כבוד הוי׳ ממקומו” ווייזט אויף דער המשכה פון כבוד הוי׳ וואס נעמט זיך פון „מקומו” — אמיתיות המקום פון „כבוד הוי׳” 31 — און דאס ווערט נמשך („ברוך” ל׳ המשכה<sup data-n=\"32\">32</sup> ביז למטה מטה; ד.ה. המשכת הבל״ג דא למטה, וואס ווערט אויפגעטאן דורך דעם ביטול המציאות פון די „אבירי לב הרחוקים מצדקה” 33.\nז. עפ״י כל הנ״ל איז מובן וואס דער אלטער רבי שרייבט „מפני היות קטן יעקב במאד מאד בעיניו מחמת ריבוי החסדים כי במקלי כו׳” (און ברענגט ניט אראפ דעם המשך וסיום הכתוב): דורך דעם וואס ביי יעקב׳ן זיינען געווען די ביידע הפכיות׳דיקע\nבחינות פון „משפט וצדקה” 34, וועל־כע זיינען מרומז אין „כי במקלי” 35, כנ״ל, האט ער דערלאנגט אין דער מדריגה וואו אלע השפעות זיינען בבחי׳ „חסדים” און „ריבוי החסדים”: די השפעה איז אין אן אופן פון „ברוך כבוד הוי׳ ממקומו” — א ריבוי חס־דים בבחי׳ בלי גבול; און מצד דעם וואס די הגדלה און „ריבוי החסדים” זיינען בא אים געווען אלס תוצאה פון „כי במקלי”, האט אט דער „קרבת אלקים ממש” 36 ביי אים געבראכט דעם „קטנתי” בתכלית השלימות — „קטן במאד מאד”.\nאון דאס איז אויך וואס דער אלטער רבי איז ממשיך, אז „היות קטן יעקב במאד מאד בעיניו מחמת ריבוי החס־דים כי במקלי כו׳”, איז דערפאר „ואינו ראוי וכדאי כלל להנצל כו׳ וכמארז״ל שמא יגרום החטא שנדמה בעיניו שחטא”:\nוויבאלד יעקב איז געשטאנען בתכ־לית הביטול, האט ער דערלאנגט אין אט דער מדריגה וואו די מציאות און (בדרך ממילא אויך) עבודת הנבראים פארנעמען בא זיי ניט קיין ארט; און דערפאר איז „נדמה בעיניו שחטא” 37: ער איז געשטאנען אין א חטא (מל׳) חסרון וביטול בעצם 38, און זיין עבו־",[["31","31","ראה ד״ה ואולם חי אני (דרמ״צ קעה, ב ואילך)."],["32","32","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370171\" data-slug=\"torah-or\" data-id=\"3901370171\">תו״א לז, ג</a>. ובכ״מ."],["33","33","בתו״א בשלח שם, שמצד בחי׳ צדקה מצ״ע מעורר מלמעלה מבחי׳ חסדו הבל״ג, אבל מכיון שהוא בבחי׳ א״ס הוא שוה ומשוה, ובבחי׳ זו נאמר שממית בידים תתפש והיא בהיכלי מלך. ועפ״י המשפט שהאדם עושה בנפשו על מותרות חיי גופו גורם למעלה בחי׳ משפט שלא יומשך חיות לסט״א. ואין מזה סתירה להמבואר בפנים, ע״פ הידוע שהיניקה לסט״א הוא מחיצוניות המקיף, בהבחי׳ ד„אח עשו ליעקב”, ובכדי שלא תהי׳ יניקה הוא ע״י ההמשכה מפנימיות המקיף (בל״ג האמיתי), ששם „ואוהב את יעקב” דוקא, וזה בא ע״י המשפט בצדקה כמבואר שם."],["34","34","ראה אוה״ת נ״ך שבהערה 17, דמבאר זה שיעקב נקרא אביר בחי׳ הת״ת כולל חו״ג, בהמשך להענין דאבירי לב כו׳."],["35","35","ראה תו״ח פרשתנו נד, ג. ושם: כי במקלי עברתי הוא ביטול הרצון דיראה ותשובה, עיי״ש."],["36","36","ל׳ אגה״ק שם."],["37","37","ראה בארוכה ד״ה ויכנעו עמי תרנ״א. ושם: וש״א חטאנו כו׳ מפני שאין עבודתם אמיתית כלל לגבי בחי׳ אמיתית עצמותו כו׳."],["38","38","היינו לא שנדמה בעיניו שיש חסרון בעבודתו, אלא שהוא ביטול בעצם, וע״ד משנ״ת"]]],[1300151292,"דה האט ביי אים ניט געהאט קיין תפיסת מקום 39.\nח. און דאס איז אויך דער קשר צווישן די צוויי פירושים אויף די ווערטער „כי במקלי” (פירוש הפשוט: „לא הי׳ עמי כו׳ אלא מקלי לבדו” 40; און פירוש המדרש: „נתן מקלו בירדן ונבקע הירדן”), ווייל די ביידע פירו־שים דריקן אויס די צוויי הפכית׳דיקע תנועות וואס זיינען געווען ביי יעקב׳ן:\nמצד אחד, האט ער גארניט געהאט און ער בעט ביים אויבערשטן נאר אלס צדקה; און לאידך, שטייט ער אין אזא דערהויבענער דרגא, ביז צו ווערט זיין די הנהגה נסית פון „נבקע הירדן”, וואס דאס גופא באווייזט אז ער איז ראוי צו האבן די השפעות החסדים בתורת משפט 41.\nאון דער „משפט וצדקה ביעקב אתה עשית” וואס האט גורם געווען אז די בחי׳ פון „קטנתי” זאל זיין בתכלית השלימות — דאס איז געווען די\nהקדמה והכנה עס זאל מקויים ווערן די תפלה „הצילני נא גו׳ ואתה אמרת גו׳ ושמתי את זרעך כחול הים אשר לא יספר מרוב” 42.\nט. די הוראה פון דעם אין עבודת כאו״א:\nס׳איז ידוע 43 אז יעדער איד האט בירושה א מעין פון די עבודות וואס זיינען געווען ביי די אבות (ד״אין קורין אבות אלא לשלשה”<sup data-n=\"44\">44</sup>, וואס פון דעם איז מובן בעניננו: אז ניט בלויז איז יעדער איד ראוי צו בעטן ביים אויבערשטן השפעת החסד אלס „צדקה”, נאר ער איז אויך ווערט צו באקומען עס בתורת „משפט”:\nוואַרום וויבאלד „כל ישראל בני מלכים הם” 45, איז דערפאר (ווי כ״ק מו״ח אדמו״ר האט אמאל געזאגט) ווערט אויך א טירחא הכי קלה פון א אידן גערעכנט ווי אן עבודת פרך *45, און צוליב דעם קען ער שוין מאנען ביים אויבערשטן כל הון דעלמא 46, בבני חייא ומזוני רויחי.\nאון ווי דער אלטער רבי זאגט אין תורה אור 47, אז מה־דאך נבוכדנצר, וואס איז געגאנגען ג׳ פסיעות לכבוד המקום, האט מען אים געגעבן דער־פאר מלכות וכו׳ אויף ג׳ דורות 48 —",[["","","(<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131036\" data-slug=\"likkutei-sichot\" data-id=\"1300131036\">לקו״ש חי״ג ע׳ 36</a> ואילך ובהערות שם) בענוה דמשה רבינו שהיא בחי׳ ביטול וענוה בעצם, וכענוה דכתר. וראה פנ״י אוה״ת שבהערה הבאה (ובאוה״ת שם דבקשת מתנת חנם דמשה היא כהביטול דכתר, עיי״ש)."],["39","39","ראה פנ״י ר״פ ואתחנן (הובא באוה״ת שם ע׳ קיח) דזה שמשה „לא התפלל רק בחסדי ה׳ במתנת חנם . . הוא מחמת גודל הכרתם בגדולת הבורא יקטין מאד מעשיהם הטובים בעיניהם כמ״ש יעקב אבינו קטנתי מכל החסדים”. וראה אוה״ת שם ס״ז."],["40","40","ל׳ רש״י כאן."],["41","41","ראה שלי״ה שם (רצד, סע״ב ורצה, סע״א ואילך), דפי׳ הא׳ דרש״י בכי במקלי („לא הי׳ לי כו׳”) מורה על שפלותו והוא ההכנעה של יעקב כלפי עשו למטה, ופי׳ הב׳ („שבקע את הירדן כו׳”) מורה על התרוממותו והוא הזכות שזכר יעקב לפני הקב״ה. וזהו ג״כ ב׳ הפירושים בב״ר (פע״ו, ה׳) בקטנתי — איני כדאי, כדאי."],["42","42","פרשתנו שם, יב־יג."],["43","43","תו״א ר״פ וארא."],["44","44","ברכות טז, ב."],["45","45","שבת סז, א. ובזח״ב (כו, רע״ב. הקדמת תקו״ז בתחלתה): דמלכים הם. *45) ע״ד מרז״ל (סוטה יא, ב) במלאכת נשים לאנשים."],["46","46","ראה ב״מ (פג, א): אפילו אם אתה עושה להם כסעודת שלמה בשעתו לא יצאת ידי חובתך עמהן שהן בני אברהם יצחק ויעקב."],["47","47","מקץ לא, ג."],["48","48","סנהדרין צו, א. יל״ש מלכים רמז רמד."]]],[1300151293,"איז במכ״ש ביי אידן, וואס „אין לך אדם מישראל שלא כיבד את המקום בכך”, איז „כל טוב עוה״ז כדאי הוא לו”.\nאון דאס וואס מ׳זעט אז א איד האט יסורים אין עוה״ז, איז עס בלויז „לבטש את האדם להכניעו ולהשפיל גסות רוחו” 49: בשעת אבער, א איד האלט ביי „משפט וצדקה”, אז הגם ער איז ווערט בתורת משפט, פונ־דעסטוועגן בעט ער ביי אויבערשטן אלס צדקה — וואס ווייזט אויף דער תנועה פון ביטול ושפלות, כנ״ל — דעמאלט ווערט נמשך די ברכת הוי׳ ממקומו: עס ווערט נמשך הצלחה למעלה מכל מדידה והגבלה אין אלע זיינע ענינים, בני חיי ומזוני אין אן אופן פון רויחי, און עס ווערן בטל אלע דברים המבלבלים אז ער זאל זיין „יושב בשלות עוה״ז” 50.\nיוד. דאס איז אויך די שייכות פון אט די ענינים צו דער גאולה פון אלטן רבי׳ן: דער אלטער רבי האט זיך מוסר נפש געווען אויף הפצת פנימיות התורה, ער האט זיך אפגעריסן פון זיינע ענינים כדי מפיץ זיין תורת החסידות ביז אויף אין חוצה — איז דאך זיכער, אז ער האט געקענט מאנען זיין באפרייאונג בתורת דין ומשפט; דאך האט ער דאס געבעטן אלס צדקה, ווי ער איז מאריך אין זיינע מכתבים 51 אז זיין גאולה איז גע־ווען חסדי ה׳ 52 וואס „הפליא והגדיל ה׳ לעשות בארץ”;\nאון דערפאר האט דאס געבראכט, אז די גאולה זאל זיין אין אן אופן פון „פדה בשלום נפשי” 53 — עס איז בטל געווארן די התנגדות אויף תורת החסידות ואדרבא זיי זיינען געווארן „עמדו” און אין אן אופן פון „שלום” 54, ווי דער פסוק איז מסיים — „כי ברבים היו עמדי” 55.\n(משיחת י״ט כסלו תשכ״ו)",[["49","49","תו״א שם."],["50","50","ע״ד הל׳ בתו״א שם. תו״ח מקץ (עח, ג)."],["51","51","נדפס בבית רבי ח״א פי״ח. אג״ק שלו סל״ח."],["52","52","ע״פ המבואר בפנים, יש לבאר ג״כ מה שבתחילת האגרת כותב אדה״ז „קטנתי מכל החסדים ומכל כו׳” — דלכאורה אינו מובן: הכוונה היתה למש״נ „ומכל האמת” וא״כ הו״ל להעתיקו בפירוש; ואם הענין ד„אמת” אינו שייך לכאן (ולכן לא העתיקו) א״כ גם תיבת „ומכל” אינה שייכת לכאן ? והביאור בזה: החילוק בין „חסדים” ו„אמת” הוא (כפי׳ רש״י עה״פ): חסדים הם מה שהקב״ה עושה מעצמו (כענין מדת הצדקה); ו„אמת” הוא מה שעושה מחמת הבטחתו — וה״ז בדוגמת מדת ה„משפט”, כי מוכרח כביכול בהשפעה (מחמת הבטחתו). ולכן: מכיון שאצל אדה״ז הי׳ נרגש (מצד עוצם ביטולו) שכל הטובות עמו הם בבחי׳ „צדקה” ו„חסדים”, לכן לא העתיק ענין ד„אמת”; אבל לאידך, מכיון שאמיתית הביטול והפעולה וענין הצדקה הוא כאשר ישנה גם מדת המשפט (שהוא ראוי לכך, ומ״מ מבקש מצד צדקה — כמבואר בפנים בארוכה), לכן רמזו ע״י „ומכל כו׳”. ועוי״ל (ובפשטות יותר): לאדה״ז לא היתה הבטחה מפורשת ומפורטת על גאולתו (כביעקב), ולכן לא העתיק „האמת”; ובכ״ז רמזו ע״י העתקת „ומכל כו׳” — כי ישנה הבטחה הכללית ששמע מהה״מ — כמסופר מרבותינו נשיאינו."],["53","53","תהלים נה, יט. וכמ״ש אדה״ז באגרתו (נדפס בבית רבי שם. היום יום ע׳ ד. אג״ק שלו סל״ח. ובכ״מ): „וכשקריתי בס׳ תהלים בפסוק פדה בשלום נפשי . . יצאתי בשלום מה׳ שלום”."],["54","54","שהוא דבר המחבר ומתווך ב׳ קצוות הפכים כו׳ (אגה״ק סוס״ל). ובשייכות הגאולה לתוכן הכתוב פדה גו׳ — עיקרו „שלום” — כדמוכח מל׳ אדה״ז (הובא בהערה הקודמת)."],["55","55","כדרשת הירושלמי סוטה פ״א סה״ח."]]],[1300151294,"וישלח ג — י״ט כסלו —\nא. אויפן פסוק 1 „ויותר יעקב לבדו” זיינען פאראן עטלעכע פירושים, ומהם:\nא) די גמרא 2 זאגט (און עס ווערט אראפגעבראכט — בשינוי לשון — אין פרש״י על התורה): „נשתייר על פכין קטנים”; און דאס איז מרומז אין ווארט „לבדו”, ווי רבותינו בעלי התוספות 3 ברענגען אראפ: „אל תיקרי לבדו אלא לכדו” 4.\nב) אין מדרש 5 שטייט: „מה הקב״ה כתוב בו 6 ונשגב ה׳ לבדו אף יעקב ויותר יעקב לבדו”.\nווי פיל מאל גערעדט 7, האבן אלע פירושים אויפן זעלבן פסוק (ומכ״ש — אויפן זעלבן ווארט) צווישן זיך א קשר תוכני. דארף מען פארשטיין: וואס איז די שייכות צווישן די צוויי פירושים בנדו״ד, ואדרבא, לכאורה, זיינען זיי פירושים הפכיים:\nלויטן פירוש הגמרא איז יעקב׳ס אי־בערבלייבן „לבדו” געווען פארבונדן מיט „קטנים”, מיט זאכן וואס האבן געהאט גאר ווייניק חשיבות 8 [און אזוי ווערט אויך געטייטשט דער ווארט „לבדו” — „אל תיקרי לבדו אלא לכדו”]; דאקעגן לויטן פירוש המדרש איז „ויותר יעקב לבדו” אן ענין פון תכלית העילוי והמעלה 9: ס׳איז ע״ד ווי „ונשגב ה׳ לבדו” פון הקב״ה — דער ענין פון אחדות והתגלות של הקב״ה, ווי עס וועט זיין ערשט לעתיד לבוא — „ביום ההוא” (כההמשך אין פסוק).\nב. ס׳איז ידוע וואס דער של״ה שרייבט 10, אז אלע מועדי השנה זיינען מרומז אין די פרשיות התורה וואס ווערן געלייענט אין די זמנים אין וועלכע די מועדים זיינען חל.\nדערפון איז פארשטאנדיק בנוגע דעם מועד 11 פון י״ט כסלו, וואס איז חל — בכמה שנים, ווי דעם יאר — אין (שבת) פ׳ וישלח 12, אז דער תוכן פון י״ט כסלו איז מרומז אין פ׳ וישלח 13.\nוועט מען דאס פארשטיין בהקדים:\nדאס וואס תורת החסידות איז נתגלה געווארן דוקא אין די דורות האחרונים (און ניט אין די פריערדיקע דורות, וואס „ראשונים בני מלאכים כו׳”<sup data-n=\"14\">14</sup>, זיינען",[["1","1","פרשתנו לב, כה."],["2","2","חולין צא, סע״א."],["3","3","וכ״ה בבחיי (בשם „רבותינו ז״ל”) ורע״ב עה״פ."],["4","4","וראה עוד טעם בבעה״ת שם: לשון בית הבד כו׳. ובהדר זקנים: ממשמעות דלבדו ידענא כו׳, עיי״ש. וראה מפרשי רש״י כאן."],["5","5","ב״ר פע״ז, א."],["6","6","ישעי׳ ב, יז."],["7","7","ראה לקו״ש ח״ג ע׳ 782. ועוד."],["8","8","ובפרט עפ״י פי׳ הכלי יקר כאן. וראה ג״כ אור״ת להה״מ (קיא, א): „יעקב לבדו כי שכח פחים * קטנים כי בלי מוחין פחים קטנים היינו כלים קטנים והם המוחין כו׳”. *) כן הוא בדפוס שלפני ואולי צ״ל „פכים”."],["9","9","להעיר גם מתורת לוי״צ (ע׳ יא), ד„ויותר יעקב לבדו” שייך ל„הן עם לבדד ישכון”."],["10","10","חלק תושב״כ ר״פ וישב."],["11","11","כ״ה לשון אדה״ז — לקו״ד ח״א יט, ב. ובל׳ כ״ק מו״ח אדמו״ר (במכתב שנעתק בהקדמה להיום יום. בהקדמה לחוברת י״ט כסלו) — „חג החגים” (נתבאר בלקו״ש ח״ה ע׳ 436 ואילך)."],["12","12","וגם כשחל בשבוע דפ׳ וישב — הרי „מתברך” הוא משבת שלפניו — ש״פ וישלח."],["13","13","ראה גם ס׳ השיחות תש״ד ע׳ 50 (וראה לקמן הערה 65). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011070\" data-slug=\"likkutei-sichot\" data-id=\"1300011070\">לקו״ש ח״א ע׳ 70</a>. ועוד."],["14","14","כ״ה בשבת קיב, ב. ירושלמי דמאי פ״א ה״ג („קדמאי בני מלאכים”). ובשקלים רפ״ה וב״ר פס״ה, ח — ליתא תיבת „בני” („קדמאין מלאכין”). וכ״ה"]]],[1300151295,"פאראן צוויי הסברות:\nא) מצד דעם חושך כפול ומכופל וואס איז נתוסף געווארן אין די דורות האחרונים (ובפרט אין דרא דעקבתא דמשיחא), מוז מען אנקומען צו א העכערן אור, וואס זאל בייקומען אויך אט דעם חושך 15;\nב) ע״ד ווי עס שטייט אין כתבי האריז״ל 16 (און עס ווערט אראפ־געבראכט אין מגן אברהם 17 ושו״ע אדה״ז 17* — בעל הגאולה והשמחה — להלכה), אז ערב שבת דארף מען פארזוכן פון די מאכלים פון שבת („טועמי׳ חיים זכו”<sup data-n=\"18\">18</sup>, אזוי איז עס אויך אין די כללות׳דיקע „טעג” פון „שית אלפי שנין” 19, אז אין די לעצטע דורות פאר ביאת המשיח, דעם „ערב שבת” פון „יום שכולו שבת” — ווערט נמשך א הארה (בדרך טעימה עכ״פ) פונעם גילוי פון פנימיות התורה וואס וועט נתגלה ווערן (בשלימותה) דורך משיח צדקנו 20.\nאון אויך אין די צוויי הסברות געפינט מען די צוויי קצוות (ע״ד ווי אין „ויותר יעקב לבדו”, כנ״ל): לויט דער ערשטער הסברה קומט אויס, אז דער גילוי אור החסידות אין דורות האחרונים איז מצד זייער נידעריקייט — צוליב דעם גודל החושך אין אט די דורות פאדערט זיך לעומתו דער גילוי פונעם אור נעלה פון פנימיות התורה; משא״כ לויט דער צווייטער הסברה, איז דער גילוי החסידות אין די דורות האחרונים פאר־בונדן מיט מעלת הזמן: זייענדיק בבחי׳ „ערב שבת לאחרי חצות” איז שוין דעמאלט דא א מעין פון דעם גילוי דלעתיד 21.\nג. דער ביאור אין דעם:\nס׳איז ידוע 22 אז י״ט כסלו האט אויפ־געטאן די התחלה פון דעם עיקר ד„יפוצו מעינותיך חוצה” — די הפצה פון מעינות החסידות צו אלע אידן, אויך צו אזעלכע וואס געפינען זיך אין „חוצה” 23.\nשוין פיל מאל גערעדט 24 וועגן דעם דיוק הלשון „יפוצו מעינותיך חוצה”, אז דאס מיינט, אז די מעינות אליין דארפן קומען אין „חוצה”; ד. ה. ניט נאר דארפן די מעינות האבן א ווירקונג אויפן „חוצה” (בעת זיי אליין בלייבן במקומם), נאר אויך זיי אליין דארפן זיך געפינען אין „חוצה” 25.",[["","","גירסת ר״נ גאון שבת שם. תוד״ה ר״נ שבת יב, ב. ב׳ הגירסאות הובאו בדק״ס שבת קיב, ב. ובתוס׳ ד״ה צדיקים, חולין ה, ב: „אם הראשונים כמלאכים כו׳” — ולשון זה רגיל בכמה ספרים."],["15","15","קונטרס עה״ח פי״ג. מכ׳ כ״ק אדמו״ר נ״ע (נדפס בהוספות לקונטרס הנ״ל ע׳ 82 ואילך). וראה ג״כ: משל אדה״ז („התמים” ח״ב ע׳ מט [עב]) מבן מלך שנחלה כו׳: הבעש״ט עורר את ישראל מהתעלפותם כו׳ (כת״י דא״ח ישן (לא נודע למי)) — נדפס בסה״מ תרס״ג ע׳ רנא. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021240\" data-slug=\"likkutei-sichot\" data-id=\"1300021240\">לקו״ש ח״ב ע׳ 516</a> ואילך). ועוד."],["16","16","פע״ח שי״ח רפ״ג. שעה״כ ענין טבילת ע״ש."],["17","17","או״ח סר״נ סוסק״א. 17*) שם ס״ח."],["18","18","פע״ח שם. שעה״כ שם."],["19","19","ראה רמב״ן בראשית ב, ג."],["20","20","ראה בכ״ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011059\" data-slug=\"likkutei-sichot\" data-id=\"1300011059\">לקו״ש ח״א ע׳ 59</a>. ועוד (וראה גם לקו״ש ח״ב ע׳ 467 ואילך). וראה ג״כ זח״א קיז, א (ושם קיח, א) — נת׳ בארוכה בשיחת אחש״פ תש״ל (נדפסה בלקו״ש ח״ז ע׳ 206 ואילך. בהוספות להמשך תרס״ו); לעיל ע׳ 42 ואילך. ולהעיר ג״כ מאוה״ת פ׳ צו ו, ב: ממ״ש הרמב״ם באגרת תימן — הובא ונת׳ בלקו״ש <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071217\" data-slug=\"likkutei-sichot\" data-id=\"1300071217\">ח״ב ע׳ 588</a> ואילך. ועוד."],["21","21","היינו, דלא רק שתורת החסידות („יפוצו מעינותיך חוצה”) היא הכנה ל„אתי מר” (אגה״ק הידועה של הבעש״ט — נדפסה בסו״ס בן פורת יוסף. ובכ״מ), כ״א שעכשיו כבר מאיר מהגילוי דלעתיד."],["22","22","תורת שלום ס״ע 112 ואילך."],["23","23","ראה תורת שלום שם (ע׳ 113)."],["24","24","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101106\" data-slug=\"likkutei-sichot\" data-id=\"1300101106\">לקו״ש ח״י ע׳ 106</a>. ועוד."],["25","25","ראה ספר השיחות תש״ד ע׳ 106."]]],[1300151296,"און נאכמער: די מעינות דארפן זיך געפינען אין חוצה אין אן אופן פון „יפוצו” — זיך פארשפרייטן אין חוצה, ביז אז יעדער פרט און נקודה פון „חוצה” זאל זיין דורכגענומען דורך די מעינות.\nאזוי ווי אלע ענינים הויבן זיך אן פון תורה, איז מובן אז אויך דער ענין פון „יפוצו מעינותיך חוצה” — די הפצה און גילוי פון פנימיות התורה צו די אידן וועלכע געפינען זיך אין חוצה — הויבט זיך אן דערמיט וואס די מעינות פון פנימיות התורה קומען לידי גילוי אין נגלה דתורה, ביז זיי ווערן פאר־איינציקט לאחדים ממש.\nאויך פאר דעם אלטן רבי׳ן זיינען געווען גדולי ישראל וואס זיינען געווען גרויס אין ביידע חלקי התורה, סיי אין נגלה דתורה און סיי אין נסתר דתורה; ופשוט, אז זייער לימוד נסתר דתורה האט אויפגעטאן אז זייער לימוד פון נגלה דתורה איז געווען באופן אחר — פונדעסטוועגן איז עס ביי זיי געווען אין אן אופן פון צוויי באזונדערע חלקים, גליא און סתים.\nאין דעם איז באשטאנען דער אויפטו פון אלטן רבי׳ן, אז ער האט מאחד געווען ביידע חלקי התורה לאחדים ממש 26.\nד. וויבאלד אז „ישראל מתקשראן באורייתא” 27, און נאכמער: „היא חיינו” און ישראל ואורייתא כולא חד — איז מובן, אז כשם ווי ס׳איז דא דער ענין פון „יפוצו מעינותיך חוצה” אין תורה — דער איחוד פון סתים וגליא דאורייתא, אזוי איז עס אויך אין (נשמות) ישראל: דורך גילוי תורת החסידות האט זיך אויפגעטאן דער ענין פון „יפוצו מעינותיך חוצה” 28 אין דעם אדם גופא — דער איחוד פון סתים וגליא שבנשמתא 29:\nאמת טאקע, אז אויך פאר דעם גילוי פון תורת החסידות האט דער אור האמונה (סתים דנשמתא), וואס איז העכער פון שכל, פועל געווען אויך אויף די כחות הגלויים — און אויך די כחות פון שכל ומדות זאלן זיין באופן אחר — פונדעסטוועגן איז די אמונה אליין געבליבן סתים און העכער פון שכל (גליא):\nדער אלטער רבי האט אויפגעטאן אז די אמונה וקב״ע שלמעלה מן השכל זאלן דורכנעמען דעם מענטשן אין־גאנצן, ביז אז זיי גופא זאלן אראפ־קומען און נתאחד ווערן מיט גליא דנשמתא: אין שכל גופא זאלן זיך אפלייגן און דערהערט ווערן די ענינים שלמעלה מן השכל.\nה. כשם ווי ס׳איז ביי יעדערן בפרט — אז חסידות האט אויפגעטאן דעם „יפוצו מעינותיך חוצה”, דעם איחוד פון „מעין” שבנשמה מיטן „חוצה” שבנשמה — אזוי איז עס אויך ביי אידן בכלל, וואס אלע צוזאמען זיינען זיי א „קומה אחת שלימה” 30:\nדי „ראשי אלפי ישראל” וועלכע זיינען „בחי׳ ראש ומוח” 31 פון אידן, זיינען בבחי׳ „מעין”; איז אמאל (פאר",[["26","26","ראה בכ״ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061037\" data-slug=\"likkutei-sichot\" data-id=\"1300061037\">לקו״ש (ח״ו ע׳ 37</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161038\" data-slug=\"likkutei-sichot\" data-id=\"1300161038\">חט״ז ס״ע 38</a> ואילך. ועוד). וש״נ."],["27","27","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380903\" data-slug=\"likkutei-torah\" data-id=\"4001380903\">ראה זח״ג עג, א</a>. וראה לקו״ת נצבים מו, א. ובכ״מ."],["28","28","ראה עד״ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101102\" data-slug=\"likkutei-sichot\" data-id=\"1300101102\">לקו״ש ח״י ע׳ 102</a> ואילך."],["29","29","ראה בארוכה לקו״ש שם בכללות יותר (ד„מעינותיך” קאי על הנשמה ו„חוצה” על הגוף)."],["30","30","לקו״ת ר״פ נצבים. ובכ״מ."],["31","31","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא פ״ב</a>."]]],[1300151297,"גילוי החסידות) געווען דער סדר, אז די גדולי ישראל זיינען געווען אפגע־זונדערט אין זייערע ד׳ אמות. אמת טאקע, אז זיי האבן געהאט א השפעה אויף כללות עם ישראל\n— צי דורך תורה, וואס מ׳פלעגט פון זיי לערנען, אדער דורך אפלערנען זיך פון זיי הנהגות טובות וכו׳ —\nדאך זיינען זיי אליין בכלל געווען אפגעשלאסן פונעם „חוצה”: ס׳איז נאר וואס זיי האבן געהאט א ווירקונג אויף כללות עם ישראל (און אויף פרטי בנ״י).\nדער סדר העבודה פון „יפוצו מעינותיך חוצה” האט אויפגעטאן, אז די גדולי ישראל זאלן ניט זיין אפגעשלאסן אין זייערע ד׳ אמות 32, נאר זיי אליין זאלן אריינקומען אין „חוצה”: און אין „חוצה” זאלן זיי זיין בעני עמם וואס „אין עני אלא בדעה” 33 — און ריידן מיטן „עני” אויף דעם לשון און מיט די אותיות וואס יענער פארשטייט.\nנאך מער: וויבאלד אז די „מעינות” דארפן דערגרייכן יעדער נקודה און פרט פון דעם „חוצה”, איז מובן, אז דאס איז כולל אז די גדולי ישראל גיבן זיך אפ אויך מיט די ענינים גשמיים פון עם ישראל.\nו. תורה איז דאך די נשמה פון דער וועלט, ווי חז״ל 34 זאגן אז די וועלט איז באשאפן געווארן „בשביל התורה שנקראת ראשית”, איז דערפון פאר־שטאנדיק, אז וויבאלד י״ט כסלו האט אויפגעטאן א חידוש אין תורה, האט זיך ממילא אויפגעטאן בדוגמא לזה אויך אין וועלט.\nוהביאור: עס איז ידוע, אז מצד (העלם פון) עולם אליין קען מען נאר צוקומען צום אור אלקי וואס איז מלובש אין וועלט, צום שם אלקים (בגימטריא הטבע) — דורך התבוננות אין עניני העולם כו׳ קען מען צוקומען צו דער ידיעה והכרה אז יש מנהיג לבירה זו 35; אבער ניט צום שם הוי׳ וואס איז העכער פון וועלט 36.\nאון הגם אז ס׳איז דא דער גילוי פון שם הוי׳ אין וועלט, דורך די נסים וואס קומען פאר מזמן לזמן, פונדעסטוועגן, איז דאס ניט שייך צו וועלט גופא, ואדרבה: דאס איז אן ענין פון שידוד הטבע והעולם.\nחסידות האט אויפגעטאן, אז אין וועלט גופא זאל זיין דער גילוי אלקות וואס איז העכער פון וועלט: וואס דער־פאר איז חסידות מבאר אויך בהסברה פון שכל אנושי — מיט משלים וכו׳ פון עניני העולם 37 — ווי וועלט איז מיוחד מיטן אור אלקי וואס איז העכער פון וועלט.\nז. וי״ל, אז דערמיט איז מבואר וואס דער אלטער רבי שרייבט אין זיין באוואוסטן בריף 38, אז די גאולה פון י״ט כסלו איז געווען אין אן אופן פון",[["32","32","ראה ס׳ השיחות הש״ית (ע׳ 111 ואילך. נעתק בהיום יום ע׳ נו): „אמאל איז דער רבי — דער ראש מתיבתא און גאון געווען עלענט און די תלמידים זיינען געווען עלענט. דער דרך החסידות וואס דער רבי האט מייסד געווען . . וואס דער רבי איז ניט עלענט און חסידים זיינען ניט עלענט”."],["33","33","נדרים מא, א."],["34","34","פרש״י בראשית א, א. וראה ב״ר פ״א, ד."],["35","35","ראה ב״ר ר״פ לך."],["36","36","וכידוע בענין האמונה דאוה״ע שהיא רק בבחי׳ ממכ״ע — ראה בפרטיות ס׳ הערכים־חב״ד (כרך ב׳) ערך אוה״ע ס״ב. וש״נ."],["37","37","ראה ד״ה מצה זו תש״ז פ״ב. ובכ״מ. ולהעיר ג״כ מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310038\" data-slug=\"tanya\" data-id=\"3401310038\">תניא פל״ג</a>: וכמ״ש ג״כ במ״א משל גשמי לזה וכו׳."],["38","38","נדפס בבית רבי ח״א פי״ח אג״ק שלו סל״ח. ס׳ התולדות — אדה״ז ע׳ ריח (בהוצאת תשמ״ב — ח״ג ע׳ 720)."]]],[1300151298,"„הפליא ה׳ והגדיל לעשות בארץ” 39:\nאין דעם סדר הנהגה ווי דער אויב־ערשטער פירט די וועלט, זיינען פאראן צוויי אופנים: א) הנהגה עפ״י טבע, אין וועלכער עס זעט זיך ניט אן בגלוי דער חיות אלקי, וואס די הנהגה קומט מצד דעם שם אלקים. ב) השגחה פרטית בגלוי, אז אין דער הנהגת הטבע איז ניכר דער אור וחיות אלקי, און די השגחה פרטית, וואס די הנהגה נעמט זיך פון שם הוי׳ 40.\nאון אין דער הנהגה פון שם הוי׳ גופא זיינען פאראן פארשידענע אופנים 40: א) אין אן אופן פון, כביכול, „קטנות” — אז די השגחה פרטית ווערט דערהערט אין א הנהגה בדרכי הטבע; ב) אין אן אופן פון „גדלות” („הגדיל וכו׳”) — ווען דאס ווערט דערהערט און אנטפלעקט אין א הנהגה וואס איז העכער פון טבע, ע״ד מחז״ל 41: דבר גדול מעשה מרכבה.\nאבער אויך „הגדיל” ווייזט אויף א הנהגה וואס האט אן ערך ושייכות צו דער הנהגה פון „קטנות” — ס׳איז אין דעם זעלבן סוג נאר גרעסער, אמאל — א סך גרעסער, אבער ניט באין ערוך פון הנהגת הטבע. ג) די הנהגה אין אן אופן פון „הפליא”, וואס איז מובדל פון הנהגת הטבע 42.\nח. אט די דריי אופני הנהגה פון שם הוי׳ זיינען די דריי סוגים אין נסים 43:\nא) נסים וואס זיינען מלובש אין דרכי הטבע, ביז אז ס׳איז ניט קענטיק אז ס׳איז א נס (ווי דער נס פון פורים); וואס הגם דאס איז א הנהגה פון שם הוי׳, וויבאלד עס זעט זיך אין דעם די השגח״פ — איז דאס אבער אין אן אופן פון, כביכול, קטנות כנ״ל.\nב) נסים גלוים, זיי האבן אבער א שייכות און אחיזה אין טבע; וי״ל אז ע״ד זה איז אויך כיבוש יריחו דורך יהושע: נאך דעם נס פון נפילת החומה, א נס וואס איז ניט געווען מלובש אין דרכי הטבע, איז ויעל העם גו׳ ויחרימו גו׳ לפי חרב 44 — אן אחיזה אין טבע. ובפרטיות יותר — מלחמת מדין: החלצו מאתכם אנשים לצבא גו׳ ויצבאו גו׳ און צוזאמען דערמיט „ולא נפקד ממנו איש” 45, א מלחמה וואס איז ניט קיין טבע׳דיקע.\n[ע״ד הסיפור הידוע, אז אמאל איז צום אלטן רבי׳ן געקומען א חולה, וואס אלע דאקטוירים האבן פאר אים ניט געפונען קיין רפואה. האט דער אלטער רבי געזאגט אז ער זאל עסן א האלבע שמורה־מצה מיט וואסער — און ער איז געזונט געווארן.\nלכאורה איז עס א סתירה מיני׳ ובי׳: עס איז אן עשי׳ וואס פועל׳ט בגוף החולה, מחזק הבריאות; אבער פון דער צווייטער זייט איז, בדרכי הטבע, האבן שמורה מיט וואסער קיין שייכות ניט צו רפואה פאר א חולה (וואס דאקטוירים האבן אים אפגעזאגט)?\nנאר, כנ״ל: די רפואה איז געווען אן ענין וואס איז העכער פון טבע, אבער אין אן אופן פון האבן אן אחיזה אין טבע].\nג) נסים וואס האבן אפילו ניט קיין אחיזה אין טבע, אזוי ווי דער נצחון נסי",[["39","39","בבית רבי שם הגירסא: הפליא והגדיל ה׳ לעשות בארץ כי הגדיל והפליא ה׳ לעשות בארץ כי׳ ה׳ הפליא והגדיל להעשות בארץ."],["40","40","ראה ד״ה צהר תעשה תרע״ג. ועוד."],["41","41","סוכה כח, א. וראה רמב״ם הל׳ יסוה״ת ספ״ד, ד„דבר קטן הוויות דאביי ורבא” „הם הטובה . . ליישוב העולם הזה כו׳”."],["42","42","ראה שער האמונה פט״ו (כט, ב ואילך)."],["43","43","עיין בד״ה ועתה אם נא פ׳ תשא רע״ח, שי״ל שגם בנסים שלמעלה מהטבע יש מדרי׳."],["44","44","יהושע ו, כ־כא."],["45","45","מטות לא, ג־ז. שם, מט."]]]]});
